cat > lz4blk.c <<'EOF'
/* LZ4 block format - fast compressor & decoder (clean-room implementation) */
#include "lz4blk.h"
#include <string.h>
#include <stdlib.h>

#define MINMATCH 4
#define LASTLITERALS 5
#define MFLIMIT 12
#define LZ4_MIN_LENGTH (MFLIMIT + 1)
#define KB *(1U<<10)
#define GB *(1U<<30)
#define DIST_MAX 65535
#define ML_BITS 4
#define ML_MASK ((1U<<ML_BITS)-1)
#define RUN_BITS (8-ML_BITS)
#define RUN_MASK ((1U<<RUN_BITS)-1)
#define LZ4_64KLIMIT ((64 KB) + (MFLIMIT - 1))
#define SKIP_TRIGGER 6

typedef uint8_t BYTE;
typedef uint16_t U16;
typedef uint32_t U32;
typedef uint64_t U64;

enum { NO_DICT = 0, WITH_PREFIX64K, USING_EXTDICT, USING_DICTCTX };
enum { NO_DICT_ISSUE = 0, DICT_SMALL };
enum { NOT_LIMITED = 0, LIMITED_OUTPUT = 1 };

static inline U32 rd32(const void* p) { U32 v; memcpy(&v, p, 4); return v; }
static inline U64 rd64(const void* p) { U64 v; memcpy(&v, p, 8); return v; }
static inline U16 rd16(const void* p) { U16 v; memcpy(&v, p, 2); return v; }
static inline void wr16(void* p, U16 v) { memcpy(p, &v, 2); }

int lz4_compressBound(int isize) { return LZ4_COMPRESSBOUND(isize); }

static inline U32 hash4(U32 seq, int tt) {
    if (tt == TT_BYU16) return (seq * 2654435761U) >> ((MINMATCH * 8) - (LZ4_HASHLOG + 1));
    return (seq * 2654435761U) >> ((MINMATCH * 8) - LZ4_HASHLOG);
}
static inline U32 hash5(U64 seq, int tt) {
    const U32 hashLog = (tt == TT_BYU16) ? LZ4_HASHLOG + 1 : LZ4_HASHLOG;
    const U64 prime5bytes = 889523592379ULL;
    return (U32)(((seq << 24) * prime5bytes) >> (64 - hashLog));
}
static inline U32 hashPos(const BYTE* p, int tt) {
    if (tt != TT_BYU16) return hash5(rd64(p), tt);
    return hash4(rd32(p), tt);
}
static inline void putIndex(U32 idx, U32 h, void* table, int tt) {
    if (tt == TT_BYU16) ((U16*)table)[h] = (U16)idx;
    else ((U32*)table)[h] = idx;
}
static inline U32 getIndex(U32 h, const void* table, int tt) {
    if (tt == TT_BYU16) return ((const U16*)table)[h];
    return ((const U32*)table)[h];
}

static inline unsigned lz4_count(const BYTE* pIn, const BYTE* pMatch, const BYTE* pInLimit) {
    const BYTE* const pStart = pIn;
    while (pIn < pInLimit - 7) {
        U64 diff = rd64(pMatch) ^ rd64(pIn);
        if (!diff) { pIn += 8; pMatch += 8; continue; }
        pIn += __builtin_ctzll(diff) >> 3;
        return (unsigned)(pIn - pStart);
    }
    if ((pIn < pInLimit - 3) && (rd32(pMatch) == rd32(pIn))) { pIn += 4; pMatch += 4; }
    if ((pIn < pInLimit - 1) && (rd16(pMatch) == rd16(pIn))) { pIn += 2; pMatch += 2; }
    if ((pIn < pInLimit) && (*pMatch == *pIn)) pIn++;
    return (unsigned)(pIn - pStart);
}

static int compress_generic(lz4_stream* const cctx, const char* const source, char* const dest,
                            const int inputSize, const int maxOutputSize, const int limited,
                            const int tableType, const int dictDirective, const int dictIssue,
                            const int acceleration)
{
    const BYTE* ip = (const BYTE*)source;
    U32 const startIndex = cctx->currentOffset;
    const BYTE* base = (const BYTE*)source - startIndex;
    const BYTE* lowLimit;
    const lz4_stream* dictCtx = cctx->dictCtx;
    const BYTE* const dictionary = dictDirective == USING_DICTCTX ? dictCtx->dictionary : cctx->dictionary;
    const U32 dictSize = dictDirective == USING_DICTCTX ? dictCtx->dictSize : cctx->dictSize;
    const U32 dictDelta = (dictDirective == USING_DICTCTX) ? startIndex - dictCtx->currentOffset : 0;
    int const maybe_extMem = (dictDirective == USING_EXTDICT) || (dictDirective == USING_DICTCTX);
    U32 const prefixIdxLimit = startIndex - dictSize;
    const BYTE* const dictEnd = dictionary ? dictionary + dictSize : dictionary;
    const BYTE* anchor = (const BYTE*)source;
    const BYTE* const iend = ip + inputSize;
    const BYTE* const mflimitPlusOne = iend - MFLIMIT + 1;
    const BYTE* const matchlimit = iend - LASTLITERALS;
    const BYTE* dictBase = (dictionary == NULL) ? NULL :
        (dictDirective == USING_DICTCTX) ? dictionary + dictSize - dictCtx->currentOffset :
        dictionary + dictSize - startIndex;
    BYTE* op = (BYTE*)dest;
    BYTE* const olimit = op + maxOutputSize;
    U32 offset = 0;
    U32 forwardH;
    void* const table = cctx->hashTable;

    if ((U32)inputSize > (U32)LZ4_MAX_INPUT_SIZE) return 0;
    if (inputSize == 0) {
        if (limited && maxOutputSize <= 0) return 0;
        dest[0] = 0;
        return 1;
    }

    lowLimit = (const BYTE*)source - (dictDirective == WITH_PREFIX64K ? dictSize : 0);

    if (dictDirective == USING_DICTCTX) {
        cctx->dictCtx = NULL;
        cctx->dictSize = (U32)inputSize;
    } else {
        cctx->dictSize += (U32)inputSize;
    }
    cctx->currentOffset += (U32)inputSize;
    cctx->tableType = (U32)tableType;

    if (inputSize < LZ4_MIN_LENGTH) goto _last_literals;

    {   U32 const h = hashPos(ip, tableType);
        putIndex(startIndex, h, table, tableType);
    }
    ip++; forwardH = hashPos(ip, tableType);

    for (;;) {
        const BYTE* match;
        BYTE* token;

        {   const BYTE* forwardIp = ip;
            int step = 1;
            int searchMatchNb = acceleration << SKIP_TRIGGER;
            do {
                U32 const h = forwardH;
                U32 const current = (U32)(forwardIp - base);
                U32 matchIndex = getIndex(h, table, tableType);
                ip = forwardIp;
                forwardIp += step;
                step = (searchMatchNb++ >> SKIP_TRIGGER);

                if (forwardIp > mflimitPlusOne) goto _last_literals;

                if (dictDirective == USING_DICTCTX) {
                    if (matchIndex < startIndex) {
                        matchIndex = getIndex(h, dictCtx->hashTable, TT_BYU32);
                        match = dictBase + matchIndex;
                        matchIndex += dictDelta;
                        lowLimit = dictionary;
                    } else {
                        match = base + matchIndex;
                        lowLimit = (const BYTE*)source;
                    }
                } else if (dictDirective == USING_EXTDICT) {
                    if (matchIndex < startIndex) {
                        match = dictBase + matchIndex;
                        lowLimit = dictionary;
                    } else {
                        match = base + matchIndex;
                        lowLimit = (const BYTE*)source;
                    }
                } else {
                    match = base + matchIndex;
                }
                forwardH = hashPos(forwardIp, tableType);
                putIndex(current, h, table, tableType);

                if ((dictIssue == DICT_SMALL) && (matchIndex < prefixIdxLimit)) continue;
                if ((tableType != TT_BYU16) && (matchIndex + DIST_MAX < current)) continue;
                if (rd32(match) == rd32(ip)) {
                    if (maybe_extMem) offset = current - matchIndex;
                    break;
                }
            } while (1);
        }

        /* catch up */
        if ((match > lowLimit) && (ip[-1] == match[-1])) {
            do { ip--; match--; } while (((ip > anchor) & (match > lowLimit)) && (ip[-1] == match[-1]));
        }

        {   unsigned const litLength = (unsigned)(ip - anchor);
            token = op++;
            if (limited && (op + litLength + (2 + 1 + LASTLITERALS) + (litLength / 255) > olimit))
                return 0;
            if (litLength >= RUN_MASK) {
                unsigned len = litLength - RUN_MASK;
                *token = (BYTE)(RUN_MASK << ML_BITS);
                for (; len >= 255; len -= 255) *op++ = 255;
                *op++ = (BYTE)len;
            } else {
                *token = (BYTE)(litLength << ML_BITS);
            }
            memcpy(op, anchor, litLength);
            op += litLength;
        }

_next_match:
        if (maybe_extMem) {
            wr16(op, (U16)offset); op += 2;
        } else {
            wr16(op, (U16)(ip - match)); op += 2;
        }

        {   unsigned matchCode;
            if ((dictDirective == USING_EXTDICT || dictDirective == USING_DICTCTX) && (lowLimit == dictionary)) {
                const BYTE* limit = ip + (dictEnd - match);
                if (limit > matchlimit) limit = matchlimit;
                matchCode = lz4_count(ip + MINMATCH, match + MINMATCH, limit);
                ip += (size_t)matchCode + MINMATCH;
                if (ip == limit) {
                    unsigned const more = lz4_count(limit, (const BYTE*)source, matchlimit);
                    matchCode += more;
                    ip += more;
                }
            } else {
                matchCode = lz4_count(ip + MINMATCH, match + MINMATCH, matchlimit);
                ip += (size_t)matchCode + MINMATCH;
            }

            if (limited && (op + (1 + LASTLITERALS) + (matchCode + 240) / 255 > olimit))
                return 0;
            if (matchCode >= ML_MASK) {
                *token += ML_MASK;
                matchCode -= ML_MASK;
                while (matchCode >= 255) { *op++ = 255; matchCode -= 255; }
                *op++ = (BYTE)matchCode;
            } else {
                *token += (BYTE)matchCode;
            }
        }

        anchor = ip;
        if (ip >= mflimitPlusOne) break;

        {   U32 const h = hashPos(ip - 2, tableType);
            U32 const idx = (U32)((ip - 2) - base);
            putIndex(idx, h, table, tableType);
        }

        {   U32 const h = hashPos(ip, tableType);
            U32 const current = (U32)(ip - base);
            U32 matchIndex = getIndex(h, table, tableType);
            if (dictDirective == USING_DICTCTX) {
                if (matchIndex < startIndex) {
                    matchIndex = getIndex(h, dictCtx->hashTable, TT_BYU32);
                    match = dictBase + matchIndex;
                    lowLimit = dictionary;
                    matchIndex += dictDelta;
                } else {
                    match = base + matchIndex;
                    lowLimit = (const BYTE*)source;
                }
            } else if (dictDirective == USING_EXTDICT) {
                if (matchIndex < startIndex) {
                    match = dictBase + matchIndex;
                    lowLimit = dictionary;
                } else {
                    match = base + matchIndex;
                    lowLimit = (const BYTE*)source;
                }
            } else {
                match = base + matchIndex;
            }
            putIndex(current, h, table, tableType);
            if (((dictIssue == DICT_SMALL) ? (matchIndex >= prefixIdxLimit) : 1)
                && ((tableType == TT_BYU16) ? 1 : (matchIndex + DIST_MAX >= current))
                && (rd32(match) == rd32(ip))) {
                token = op++;
                *token = 0;
                if (maybe_extMem) offset = current - matchIndex;
                goto _next_match;
            }
        }

        forwardH = hashPos(++ip, tableType);
    }

_last_literals:
    {   size_t lastRun = (size_t)(iend - anchor);
        if (limited && (op + lastRun + 1 + ((lastRun + 255 - RUN_MASK) / 255) > olimit))
            return 0;
        if (lastRun >= RUN_MASK) {
            size_t acc = lastRun - RUN_MASK;
            *op++ = (BYTE)(RUN_MASK << ML_BITS);
            for (; acc >= 255; acc -= 255) *op++ = 255;
            *op++ = (BYTE)acc;
        } else {
            *op++ = (BYTE)(lastRun << ML_BITS);
        }
        memcpy(op, anchor, lastRun);
        op += lastRun;
    }
    return (int)(((char*)op) - dest);
}

void lz4_initStream(lz4_stream* s) { memset(s, 0, sizeof(*s)); }

static void prepareTable(lz4_stream* cctx, const int inputSize, const int tableType) {
    if (cctx->tableType != TT_CLEARED) {
        if (cctx->tableType != (U32)tableType
            || ((tableType == TT_BYU16) && cctx->currentOffset + (unsigned)inputSize >= 0xFFFFU)
            || ((tableType == TT_BYU32) && cctx->currentOffset > 1 GB)
            || tableType == TT_BYPTR
            || inputSize >= 4 KB) {
            memset(cctx->hashTable, 0, sizeof(cctx->hashTable));
            cctx->currentOffset = 0;
            cctx->tableType = TT_CLEARED;
        }
    }
    if (cctx->currentOffset != 0 && tableType == TT_BYU32) cctx->currentOffset += 64 KB;
    cctx->dictCtx = NULL;
    cctx->dictionary = NULL;
    cctx->dictSize = 0;
}

void lz4_resetStream_fast(lz4_stream* s) { prepareTable(s, 0, TT_BYU32); }

static int clampAccel(int a) {
    if (a < 1) a = 1;
    if (a > LZ4_ACCEL_MAX) a = LZ4_ACCEL_MAX;
    return a;
}

int lz4_compress_fast_extState_fastReset(lz4_stream* ctx, const char* src, char* dst, int srcSize, int dstCapacity, int accel) {
    int const limited = (dstCapacity >= lz4_compressBound(srcSize)) ? NOT_LIMITED : LIMITED_OUTPUT;
    accel = clampAccel(accel);
    if (srcSize < (int)LZ4_64KLIMIT) {
        prepareTable(ctx, srcSize, TT_BYU16);
        return compress_generic(ctx, src, dst, srcSize, dstCapacity, limited, TT_BYU16, NO_DICT,
                                ctx->currentOffset ? DICT_SMALL : NO_DICT_ISSUE, accel);
    } else {
        prepareTable(ctx, srcSize, TT_BYU32);
        return compress_generic(ctx, src, dst, srcSize, dstCapacity, limited, TT_BYU32, NO_DICT, NO_DICT_ISSUE, accel);
    }
}

int lz4_compress_fast_extState(lz4_stream* ctx, const char* src, char* dst, int srcSize, int dstCapacity, int accel) {
    int const limited = (dstCapacity >= lz4_compressBound(srcSize)) ? NOT_LIMITED : LIMITED_OUTPUT;
    lz4_initStream(ctx);
    accel = clampAccel(accel);
    if (srcSize < (int)LZ4_64KLIMIT)
        return compress_generic(ctx, src, dst, srcSize, dstCapacity, limited, TT_BYU16, NO_DICT, NO_DICT_ISSUE, accel);
    return compress_generic(ctx, src, dst, srcSize, dstCapacity, limited, TT_BYU32, NO_DICT, NO_DICT_ISSUE, accel);
}

int lz4_compress_fast(const char* src, char* dst, int srcSize, int dstCapacity, int accel) {
    lz4_stream* s = (lz4_stream*)malloc(sizeof(lz4_stream));
    int r;
    if (!s) return 0;
    r = lz4_compress_fast_extState(s, src, dst, srcSize, dstCapacity, accel);
    free(s);
    return r;
}

static void renormDictT(lz4_stream* d, int nextSize) {
    if (d->currentOffset + (unsigned)nextSize > 0x80000000) {
        U32 const delta = d->currentOffset - 64 KB;
        const BYTE* dictEnd = d->dictionary + d->dictSize;
        int i;
        for (i = 0; i < LZ4_HASH_SIZE_U32; i++) {
            if (d->hashTable[i] < delta) d->hashTable[i] = 0;
            else d->hashTable[i] -= delta;
        }
        d->currentOffset = 64 KB;
        if (d->dictSize > 64 KB) d->dictSize = 64 KB;
        d->dictionary = dictEnd - d->dictSize;
    }
}

int lz4_compress_fast_continue(lz4_stream* s, const char* source, char* dest, int inputSize, int maxOutputSize, int accel) {
    const int tableType = TT_BYU32;
    const char* dictEnd = s->dictSize ? (const char*)s->dictionary + s->dictSize : NULL;
    int const limited = LIMITED_OUTPUT;  /* always limited in continue mode */

    renormDictT(s, inputSize);
    accel = clampAccel(accel);

    if ((s->dictSize < 4) && (dictEnd != source) && (inputSize > 0) && (s->dictCtx == NULL)) {
        s->dictSize = 0;
        s->dictionary = (const BYTE*)source;
        dictEnd = source;
    }

    {   const char* const sourceEnd = source + inputSize;
        if ((sourceEnd > (const char*)s->dictionary) && (sourceEnd < dictEnd)) {
            s->dictSize = (U32)(dictEnd - sourceEnd);
            if (s->dictSize > 64 KB) s->dictSize = 64 KB;
            if (s->dictSize < 4) s->dictSize = 0;
            s->dictionary = (const BYTE*)dictEnd - s->dictSize;
        }
    }

    if (dictEnd == source) {
        if ((s->dictSize < 64 KB) && (s->dictSize < s->currentOffset))
            return compress_generic(s, source, dest, inputSize, maxOutputSize, limited, tableType, WITH_PREFIX64K, DICT_SMALL, accel);
        return compress_generic(s, source, dest, inputSize, maxOutputSize, limited, tableType, WITH_PREFIX64K, NO_DICT_ISSUE, accel);
    }

    {   int result;
        if (s->dictCtx) {
            if (inputSize > (int)(4 KB)) {
                memcpy(s, s->dictCtx, sizeof(*s));
                result = compress_generic(s, source, dest, inputSize, maxOutputSize, limited, tableType, USING_EXTDICT, NO_DICT_ISSUE, accel);
            } else {
                result = compress_generic(s, source, dest, inputSize, maxOutputSize, limited, tableType, USING_DICTCTX, NO_DICT_ISSUE, accel);
            }
        } else {
            if ((s->dictSize < 64 KB) && (s->dictSize < s->currentOffset))
                result = compress_generic(s, source, dest, inputSize, maxOutputSize, limited, tableType, USING_EXTDICT, DICT_SMALL, accel);
            else
                result = compress_generic(s, source, dest, inputSize, maxOutputSize, limited, tableType, USING_EXTDICT, NO_DICT_ISSUE, accel);
        }
        s->dictionary = (const BYTE*)source;
        s->dictSize = (U32)inputSize;
        return result;
    }
}

static int loadDict_internal(lz4_stream* dict, const char* dictionary, int dictSize, int slow) {
    const int tableType = TT_BYU32;
    const BYTE* p = (const BYTE*)dictionary;
    const BYTE* const dEnd = p + dictSize;
    U32 idx32;

    lz4_initStream(dict);
    dict->currentOffset += 64 KB;
    if (dictSize < 8) return 0;
    if ((dEnd - p) > (long)(64 KB)) p = dEnd - 64 KB;
    dict->dictionary = p;
    dict->dictSize = (U32)(dEnd - p);
    dict->tableType = (U32)tableType;
    idx32 = dict->currentOffset - dict->dictSize;

    while (p <= dEnd - 8) {
        U32 const h = hashPos(p, tableType);
        putIndex(idx32, h, dict->hashTable, tableType);
        p += 3; idx32 += 3;
    }
    if (slow) {
        p = dict->dictionary;
        idx32 = dict->currentOffset - dict->dictSize;
        while (p <= dEnd - 8) {
            U32 const h = hashPos(p, tableType);
            U32 const limit = dict->currentOffset - 64 KB;
            if (getIndex(h, dict->hashTable, tableType) <= limit) {
                putIndex(idx32, h, dict->hashTable, tableType);
            }
            p++; idx32++;
        }
    }
    return (int)dict->dictSize;
}

int lz4_loadDict(lz4_stream* s, const char* dict, int dictSize) { return loadDict_internal(s, dict, dictSize, 0); }
int lz4_loadDictSlow(lz4_stream* s, const char* dict, int dictSize) { return loadDict_internal(s, dict, dictSize, 1); }

int lz4_saveDict(lz4_stream* dict, char* safeBuffer, int dictSize) {
    if ((U32)dictSize > 64 KB) dictSize = 64 KB;
    if ((U32)dictSize > dict->dictSize) dictSize = (int)dict->dictSize;
    if (dictSize > 0) {
        const BYTE* const previousDictEnd = dict->dictionary + dict->dictSize;
        memmove(safeBuffer, previousDictEnd - dictSize, (size_t)dictSize);
    }
    dict->dictionary = (const BYTE*)safeBuffer;
    dict->dictSize = (U32)dictSize;
    return dictSize;
}

void lz4_attach_dictionary(lz4_stream* w, const lz4_stream* d) {
    if (d != NULL) {
        if (w->currentOffset == 0) w->currentOffset = 64 KB;
        if (d->dictSize == 0) d = NULL;
    }
    w->dictCtx = d;
}

/* ---------------- decoder ---------------- */
int lz4_decompress_safe_usingDict(const char* src, char* dst, int srcSize, int dstCapacity,
                                  const char* dictStart, int dictSize)
{
    const BYTE* ip = (const BYTE*)src;
    const BYTE* const iend = ip + srcSize;
    BYTE* op = (BYTE*)dst;
    BYTE* const oend = op + dstCapacity;
    const BYTE* const lowPrefix = (const BYTE*)dst;
    const BYTE* const dictEnd = (const BYTE*)dictStart + (dictStart ? dictSize : 0);
    if (!dictStart) dictSize = 0;

    if (srcSize <= 0) return -1;
    if (dstCapacity == 0) {
        if (srcSize == 1 && *ip == 0) return 0;
        return -1;
    }
    for (;;) {
        unsigned token = *ip++;
        size_t length = token >> ML_BITS;
        if (length == RUN_MASK) {
            unsigned s;
            do {
                if (ip >= iend) return -1;
                s = *ip++;
                length += s;
            } while (s == 255);
        }
        /* literals */
        if ((size_t)(iend - ip) < length) return -1;
        if ((size_t)(oend - op) < length) return -1;
        memcpy(op, ip, length);
        ip += length; op += length;
        if (ip == iend) break;  /* end of block: last literals */
        /* need offset */
        if (iend - ip < 2) return -1;
        {   size_t offset = rd16(ip); ip += 2;
            size_t mlen = token & ML_MASK;
            if (mlen == ML_MASK) {
                unsigned s;
                do {
                    if (ip >= iend) return -1;
                    s = *ip++;
                    mlen += s;
                } while (s == 255);
            }
            mlen += MINMATCH;
            if ((size_t)(oend - op) < mlen) return -1;
            if (offset == 0) return -1;
            if ((size_t)(op - lowPrefix) < offset) {
                /* reference into dictionary */
                size_t const back = offset - (size_t)(op - lowPrefix);
                if (back > (size_t)dictSize) return -1;
                {   const BYTE* m = dictEnd - back;
                    if (mlen <= back) {
                        memmove(op, m, mlen);
                        op += mlen;
                    } else {
                        size_t const copySize = back;
                        size_t restSize = mlen - copySize;
                        memmove(op, m, copySize);
                        op += copySize;
                        {   const BYTE* cp = lowPrefix;
                            while (restSize--) *op++ = *cp++;
                        }
                    }
                }
            } else {
                const BYTE* m = op - offset;
                if (offset >= mlen) { memcpy(op, m, mlen); op += mlen; }
                else { size_t i; for (i = 0; i < mlen; i++) op[i] = m[i]; op += mlen; }
            }
        }
        if (ip >= iend) return -1; /* block must end with literals */
    }
    return (int)(op - (BYTE*)dst);
}
