                        lowLimit = (const BYTE*)source;
                    }
                } else if (dictDirective == USING_EXTDICT) {
                    if (matchIndex < startIndex) {
                        match = dictBase + matchIndex;
                        lowLimit = dictionary;
                    } else {
                        match = base + matchIndex;
                        lowLimit = (const BYTE*)source;
                    }
                } else {
                    match = base + matchIndex;
                }
                forwardH = hashPos(forwardIp, tableType);
                putIndex(current, h, table, tableType);

                if ((dictIssue == DICT_SMALL) && (matchIndex < prefixIdxLimit)) continue;
                if ((tableType != TT_BYU16) && (matchIndex + DIST_MAX < current)) continue;
                if (rd32(match) == rd32(ip)) {
                    if (maybe_extMem) offset = current - matchIndex;
                    break;
                }
            } while (1);
        }

        /* catch up */
        if ((match > lowLimit) && (ip[-1] == match[-1])) {
            do { ip--; match--; } while (((ip > anchor) & (match > lowLimit)) && (ip[-1] == match[-1]));
        }

        {   unsigned const litLength = (unsigned)(ip - anchor);
            token = op++;
            if (limited && (op + litLength + (2 + 1 + LASTLITERALS) + (litLength / 255) > olimit))
                return 0;
            if (litLength >= RUN_MASK) {
