/* LZ4 HC compressor (clean-room implementation of the LZ4 HC strategies) */
#include "lz4hc.h"
#include "lz4blk.h"
#include <string.h>
#include <stdlib.h>

typedef uint8_t BYTE;
typedef uint16_t U16;
typedef uint32_t U32;
typedef uint64_t U64;

#define KB *(1U<<10)
#define GB *(1U<<30)
#define MINMATCH 4
#define LASTLITERALS 5
#define MFLIMIT 12
#define LZ4_MIN_LENGTH (MFLIMIT + 1)
#define DIST_MAX 65535
#define ML_BITS 4
#define ML_MASK ((1U<<ML_BITS)-1)
#define RUN_BITS (8-ML_BITS)
#define RUN_MASK ((1U<<RUN_BITS)-1)
#define OPTIMAL_ML (int)((ML_MASK-1)+MINMATCH)
#define LZ4_OPT_NUM (1<<12)
#define LZ4HC_HASHSIZE 4
#define MIN(a,b) ((a)<(b)?(a):(b))
#define MAX(a,b) ((a)>(b)?(a):(b))

enum { NOT_LIMITED = 0, LIMITED_OUTPUT = 1 };
enum { NO_DICTCTX = 0, USING_DICTCTX_HC = 1 };
enum { STRAT_MID, STRAT_HC, STRAT_OPT };

typedef struct { int strat; int nbSearches; U32 targetLength; } cParams_t;
static const cParams_t k_clTable[LZ4HC_CLEVEL_MAX + 1] = {
    { STRAT_MID, 2, 16 },
    { STRAT_MID, 2, 16 },
    { STRAT_MID, 2, 16 },
    { STRAT_HC, 4, 16 },
    { STRAT_HC, 8, 16 },
    { STRAT_HC, 16, 16 },
    { STRAT_HC, 32, 16 },
    { STRAT_HC, 64, 16 },
    { STRAT_HC, 128, 16 },
    { STRAT_HC, 256, 16 },
    { STRAT_OPT, 96, 64 },
    { STRAT_OPT, 512, 128 },
    { STRAT_OPT, 16384, LZ4_OPT_NUM },
};

static cParams_t getCLevelParams(int cLevel) {
    if (cLevel < 1) cLevel = LZ4HC_CLEVEL_DEFAULT;
    cLevel = MIN(LZ4HC_CLEVEL_MAX, cLevel);
    return k_clTable[cLevel];
}

typedef struct { int off; int len; int back; } match_t;

static inline U32 rd32(const void* p) { U32 v; memcpy(&v, p, 4); return v; }
static inline U16 rd16(const void* p) { U16 v; memcpy(&v, p, 2); return v; }
static inline U64 rd64(const void* p) { U64 v; memcpy(&v, p, 8); return v; }
static inline void wr16(void* p, U16 v) { memcpy(p, &v, 2); }

static inline U32 hashPtr(const void* ptr) { return (rd32(ptr) * 2654435761U) >> ((MINMATCH * 8) - LZ4HC_HASH_LOG); }

#define DELTANEXTU16(table, pos) table[(U16)(pos)]

static inline unsigned lz4_count(const BYTE* pIn, const BYTE* pMatch, const BYTE* pInLimit) {
    const BYTE* const pStart = pIn;
    while (pIn < pInLimit - 7) {
        U64 diff = rd64(pMatch) ^ rd64(pIn);
        if (!diff) { pIn += 8; pMatch += 8; continue; }
        pIn += __builtin_ctzll(diff) >> 3;
        return (unsigned)(pIn - pStart);
    }
    if ((pIn < pInLimit - 3) && (rd32(pMatch) == rd32(pIn))) { pIn += 4; pMatch += 4; }
    if ((pIn < pInLimit - 1) && (rd16(pMatch) == rd16(pIn))) { pIn += 2; pMatch += 2; }
    if ((pIn < pInLimit) && (*pMatch == *pIn)) pIn++;
    return (unsigned)(pIn - pStart);
}

/* ---------------- context management ---------------- */
static void clearTables(lz4hc_ctx* hc4) {
    memset(hc4->hashTable, 0, sizeof(hc4->hashTable));
    memset(hc4->chainTable, 0xFF, sizeof(hc4->chainTable));
}

static void init_internal(lz4hc_ctx* hc4, const BYTE* start) {
    size_t const bufferSize = (size_t)(hc4->end - hc4->prefixStart);
    size_t newStartingOffset = bufferSize + hc4->dictLimit;
    if (newStartingOffset > 1 GB) {
        clearTables(hc4);
        newStartingOffset = 0;
    }
    newStartingOffset += 64 KB;
    hc4->nextToUpdate = (U32)newStartingOffset;
    hc4->prefixStart = start;
    hc4->end = start;
    hc4->dictStart = start;
    hc4->dictLimit = (U32)newStartingOffset;
    hc4->lowLimit = (U32)newStartingOffset;
}

void lz4hc_setCompressionLevel(lz4hc_ctx* s, int level) {
    if (level < 1) level = LZ4HC_CLEVEL_DEFAULT;
    if (level > LZ4HC_CLEVEL_MAX) level = LZ4HC_CLEVEL_MAX;
    s->compressionLevel = (short)level;
}

void lz4hc_initStream(lz4hc_ctx* s) {
    memset(s, 0, sizeof(*s));
    lz4hc_setCompressionLevel(s, LZ4HC_CLEVEL_DEFAULT);
}

void lz4hc_favorDecSpeed(lz4hc_ctx* s, int favor) { s->favorDecSpeed = (favor != 0); }

void lz4hc_resetStream_fast(lz4hc_ctx* s, int level) {
    if (s->dirty) {
        lz4hc_initStream(s);
    } else {
        s->dictLimit += (U32)(s->end - s->prefixStart);
        s->prefixStart = NULL;
        s->end = NULL;
        s->dictCtx = NULL;
    }
    lz4hc_setCompressionLevel(s, level);
}

/* ---------------- hash chain insertion ---------------- */
static void hc_insert(lz4hc_ctx* hc4, const BYTE* ip) {
    U16* const chainTable = hc4->chainTable;
    U32* const hashTable = hc4->hashTable;
    const BYTE* const prefixPtr = hc4->prefixStart;
    U32 const prefixIdx = hc4->dictLimit;
    U32 const target = (U32)(ip - prefixPtr) + prefixIdx;
    U32 idx = hc4->nextToUpdate;
    while (idx < target) {
        U32 const h = hashPtr(prefixPtr + idx - prefixIdx);
        size_t delta = idx - hashTable[h];
        if (delta > DIST_MAX) delta = DIST_MAX;
        DELTANEXTU16(chainTable, idx) = (U16)delta;
        hashTable[h] = idx;
        idx++;
    }
    hc4->nextToUpdate = target;
}

/* ---------------- LZ4MID (level 2) ---------------- */
#define LZ4MID_HASHSIZE 8
#define LZ4MID_HASHLOG (LZ4HC_HASH_LOG - 1)
#define LZ4MID_HASHTABLESIZE (1 << LZ4MID_HASHLOG)

static inline U32 mid_hash4(U32 v) { return (v * 2654435761U) >> (32 - LZ4MID_HASHLOG); }
static inline U32 mid_hash4Ptr(const void* p) { return mid_hash4(rd32(p)); }
static inline U32 mid_hash7(U64 v) { return (U32)(((v << (64 - 56)) * 58295818150454627ULL) >> (64 - LZ4MID_HASHLOG)); }
static inline U32 mid_hash8Ptr(const void* p) { return mid_hash7(rd64(p)); }

#define ADDPOS8(_p, _idx) (hash8Table[mid_hash8Ptr(_p)] = (_idx))
#define ADDPOS4(_p, _idx) (hash4Table[mid_hash4Ptr(_p)] = (_idx))

static void mid_fillHTable(lz4hc_ctx* cctx, const void* dict, size_t size) {
    U32* const hash4Table = cctx->hashTable;
    U32* const hash8Table = hash4Table + LZ4MID_HASHTABLESIZE;
    const BYTE* const prefixPtr = (const BYTE*)dict;
    U32 const prefixIdx = cctx->dictLimit;
    U32 const target = prefixIdx + (U32)size - LZ4MID_HASHSIZE;
    U32 idx = cctx->nextToUpdate;
    if (size <= LZ4MID_HASHSIZE) return;
    for (; idx < target; idx += 3) {
        ADDPOS4(prefixPtr + idx - prefixIdx, idx);
        ADDPOS8(prefixPtr + idx + 1 - prefixIdx, idx + 1);
    }
    idx = (size > 32 KB + LZ4MID_HASHSIZE) ? target - 32 KB : cctx->nextToUpdate;
    for (; idx < target; idx += 1) {
        ADDPOS8(prefixPtr + idx - prefixIdx, idx);
    }
    cctx->nextToUpdate = target;
}

static int hc_countBack(const BYTE* const ip, const BYTE* const match,
                        const BYTE* const iMin, const BYTE* const mMin) {
    int back = 0;
    int const min = (int)MAX(iMin - ip, mMin - match);
    while ((back > min) && (ip[back - 1] == match[back - 1])) back--;
    return back;
}

static match_t hc_searchExtDict(const BYTE* ip, U32 ipIndex,
                                const BYTE* const iLowLimit, const BYTE* const iHighLimit,
                                const lz4hc_ctx* dictCtx, U32 gDictEndIndex,
                                int currentBestML, int nbAttempts) {
    size_t const lDictEndIndex = (size_t)(dictCtx->end - dictCtx->prefixStart) + dictCtx->dictLimit;
    U32 lDictMatchIndex = dictCtx->hashTable[hashPtr(ip)];
    U32 matchIndex = lDictMatchIndex + gDictEndIndex - (U32)lDictEndIndex;
    int offset = 0, sBack = 0;
    while (ipIndex - matchIndex <= DIST_MAX && nbAttempts--) {
        const BYTE* const matchPtr = dictCtx->prefixStart - dictCtx->dictLimit + lDictMatchIndex;
        if (rd32(matchPtr) == rd32(ip)) {
            int mlt;
            int back = 0;
            const BYTE* vLimit = ip + (lDictEndIndex - lDictMatchIndex);
            if (vLimit > iHighLimit) vLimit = iHighLimit;
            mlt = (int)lz4_count(ip + MINMATCH, matchPtr + MINMATCH, vLimit) + MINMATCH;
            back = (ip > iLowLimit) ? hc_countBack(ip, matchPtr, iLowLimit, dictCtx->prefixStart) : 0;
            mlt -= back;
            if (mlt > currentBestML) {
                currentBestML = mlt;
                offset = (int)(ipIndex - matchIndex);
                sBack = back;
            }
        }
        {   U32 const nextOffset = DELTANEXTU16(dictCtx->chainTable, lDictMatchIndex);
            lDictMatchIndex -= nextOffset;
            matchIndex -= nextOffset;
        }
    }
    {   match_t md;
        md.len = currentBestML;
        md.off = offset;
        md.back = sBack;
        return md;
    }
}

static match_t mid_searchHCDict(const BYTE* ip, U32 ipIndex, const BYTE* const iHighLimit,
                                const lz4hc_ctx* dictCtx, U32 gDictEndIndex) {
    return hc_searchExtDict(ip, ipIndex, ip, iHighLimit, dictCtx, gDictEndIndex, MINMATCH - 1, 2);
}

static match_t mid_searchExtDict(const BYTE* ip, U32 ipIndex, const BYTE* const iHighLimit,
                                 const lz4hc_ctx* dictCtx, U32 gDictEndIndex) {
    size_t const lDictEndIndex = (size_t)(dictCtx->end - dictCtx->prefixStart) + dictCtx->dictLimit;
    const U32* const hash4Table = dictCtx->hashTable;
    const U32* const hash8Table = hash4Table + LZ4MID_HASHTABLESIZE;
    {   U32 l8DictMatchIndex = hash8Table[mid_hash8Ptr(ip)];
        U32 m8Index = l8DictMatchIndex + gDictEndIndex - (U32)lDictEndIndex;
        if (ipIndex - m8Index <= DIST_MAX) {
            const BYTE* const matchPtr = dictCtx->prefixStart - dictCtx->dictLimit + l8DictMatchIndex;
            const size_t safeLen = MIN(lDictEndIndex - l8DictMatchIndex, (size_t)(iHighLimit - ip));
            int mlt = (int)lz4_count(ip, matchPtr, ip + safeLen);
            if (mlt >= MINMATCH) {
                match_t md; md.len = mlt; md.off = (int)(ipIndex - m8Index); md.back = 0;
                return md;
            }
        }
    }
    {   U32 l4DictMatchIndex = hash4Table[mid_hash4Ptr(ip)];
        U32 m4Index = l4DictMatchIndex + gDictEndIndex - (U32)lDictEndIndex;
        if (ipIndex - m4Index <= DIST_MAX) {
            const BYTE* const matchPtr = dictCtx->prefixStart - dictCtx->dictLimit + l4DictMatchIndex;
            const size_t safeLen = MIN(lDictEndIndex - l4DictMatchIndex, (size_t)(iHighLimit - ip));
            int mlt = (int)lz4_count(ip, matchPtr, ip + safeLen);
            if (mlt >= MINMATCH) {
                match_t md; md.len = mlt; md.off = (int)(ipIndex - m4Index); md.back = 0;
                return md;
            }
        }
    }
    {   match_t const md = { 0, 0, 0 };
        return md;
    }
}

/* returns 0 on success, 1 on overflow */
static int encodeSequence(const BYTE** _ip, BYTE** _op, const BYTE** _anchor,
                          int matchLength, int offset, int limit, BYTE* oend) {
    size_t length;
    BYTE* const token = (*_op)++;
    BYTE* op = *_op;
    length = (size_t)(*_ip - *_anchor);
    if (limit && ((op + (length / 255) + length + (2 + 1 + LASTLITERALS)) > oend)) { *_op = op; return 1; }
    if (length >= RUN_MASK) {
        size_t len = length - RUN_MASK;
        *token = (BYTE)(RUN_MASK << ML_BITS);
        for (; len >= 255; len -= 255) *op++ = 255;
        *op++ = (BYTE)len;
    } else {
        *token = (BYTE)(length << ML_BITS);
    }
    memcpy(op, *_anchor, length);
    op += length;
    wr16(op, (U16)offset); op += 2;
    length = (size_t)matchLength - MINMATCH;
    if (limit && (op + (length / 255) + (1 + LASTLITERALS) > oend)) { *_op = op; return 1; }
    if (length >= ML_MASK) {
        *token += ML_MASK;
        length -= ML_MASK;
        for (; length >= 510; length -= 510) { *op++ = 255; *op++ = 255; }
        if (length >= 255) { length -= 255; *op++ = 255; }
        *op++ = (BYTE)length;
    } else {
        *token += (BYTE)length;
    }
    *_ip += matchLength;
    *_anchor = *_ip;
    *_op = op;
    return 0;
}

static int encodeLastLiterals(const BYTE* anchor, const BYTE* iend, BYTE** _op, BYTE* oend, int limit) {
    BYTE* op = *_op;
    size_t lastRunSize = (size_t)(iend - anchor);
    size_t llAdd = (lastRunSize + 255 - RUN_MASK) / 255;
    size_t const totalSize = 1 + llAdd + lastRunSize;
    if (limit && (op + totalSize > oend)) return 1;
    if (lastRunSize >= RUN_MASK) {
        size_t acc = lastRunSize - RUN_MASK;
        *op++ = (BYTE)(RUN_MASK << ML_BITS);
        for (; acc >= 255; acc -= 255) *op++ = 255;
        *op++ = (BYTE)acc;
    } else {
        *op++ = (BYTE)(lastRunSize << ML_BITS);
    }
    memcpy(op, anchor, lastRunSize);
    op += lastRunSize;
    *_op = op;
    return 0;
}

static int mid_compress(lz4hc_ctx* const ctx, const char* const src, char* const dst,
                        int* srcSizePtr, int const maxOutputSize, const int limit, const int dict)
{
    U32* const hash4Table = ctx->hashTable;
    U32* const hash8Table = hash4Table + LZ4MID_HASHTABLESIZE;
    const BYTE* ip = (const BYTE*)src;
    const BYTE* anchor = ip;
    const BYTE* const iend = ip + *srcSizePtr;
    const BYTE* const mflimit = iend - MFLIMIT;
    const BYTE* const matchlimit = (iend - LASTLITERALS);
    const BYTE* const ilimit = (iend - LZ4MID_HASHSIZE);
    BYTE* op = (BYTE*)dst;
    BYTE* oend = op + maxOutputSize;

    const BYTE* const prefixPtr = ctx->prefixStart;
    const U32 prefixIdx = ctx->dictLimit;
    const U32 ilimitIdx = (U32)(ilimit - prefixPtr) + prefixIdx;
    const BYTE* const dictStart = ctx->dictStart;
    const U32 dictIdx = ctx->lowLimit;
    const U32 gDictEndIndex = ctx->lowLimit;
    match_t (*searchIntoDict)(const BYTE*, U32, const BYTE* const, const lz4hc_ctx*, U32) = NULL;
    unsigned matchLength;
    unsigned matchDistance;

    if (dict == USING_DICTCTX_HC && ctx->dictCtx) {
        searchIntoDict = (getCLevelParams(ctx->dictCtx->compressionLevel).strat == STRAT_MID) ? mid_searchExtDict : mid_searchHCDict;
    }

    if (*srcSizePtr < 0) return 0;
    if (maxOutputSize < 0) return 0;
    if (*srcSizePtr > LZ4_MAX_INPUT_SIZE) return 0;
    if (*srcSizePtr < LZ4_MIN_LENGTH) goto _last_literals;

    while (ip <= mflimit) {
        const U32 ipIndex = (U32)(ip - prefixPtr) + prefixIdx;
        /* long match */
        {   U32 const h8 = mid_hash8Ptr(ip);
            U32 const pos8 = hash8Table[h8];
            hash8Table[h8] = ipIndex;
            if (ipIndex - pos8 <= DIST_MAX) {
                if (pos8 >= prefixIdx) {
                    const BYTE* const matchPtr = prefixPtr + pos8 - prefixIdx;
                    matchLength = lz4_count(ip, matchPtr, matchlimit);
                    if (matchLength >= MINMATCH) {
                        matchDistance = ipIndex - pos8;
                        goto _encode_sequence;
                    }
                } else {
                    if (pos8 >= dictIdx) {
                        const BYTE* const matchPtr = dictStart + (pos8 - dictIdx);
                        const size_t safeLen = MIN(prefixIdx - pos8, (size_t)(matchlimit - ip));
                        matchLength = lz4_count(ip, matchPtr, ip + safeLen);
                        if (matchLength >= MINMATCH) {
                            matchDistance = ipIndex - pos8;
                            goto _encode_sequence;
                        }
                    }
                }
            }
        }
        /* short match */
        {   U32 const h4 = mid_hash4Ptr(ip);
            U32 const pos4 = hash4Table[h4];
            hash4Table[h4] = ipIndex;
            if (ipIndex - pos4 <= DIST_MAX) {
                if (pos4 >= prefixIdx) {
                    const BYTE* const matchPtr = prefixPtr + (pos4 - prefixIdx);
                    matchLength = lz4_count(ip, matchPtr, matchlimit);
                    if (matchLength >= MINMATCH) {
                        U32 const h8 = mid_hash8Ptr(ip + 1);
                        U32 const pos8 = hash8Table[h8];
                        U32 const m2Distance = ipIndex + 1 - pos8;
                        matchDistance = ipIndex - pos4;
                        if (m2Distance <= DIST_MAX && pos8 >= prefixIdx && ip < mflimit) {
                            const BYTE* const m2Ptr = prefixPtr + (pos8 - prefixIdx);
                            unsigned ml2 = lz4_count(ip + 1, m2Ptr, matchlimit);
                            if (ml2 > matchLength) {
                                hash8Table[h8] = ipIndex + 1;
                                ip++;
                                matchLength = ml2;
                                matchDistance = m2Distance;
                            }
                        }
                        goto _encode_sequence;
                    }
                } else {
                    if (pos4 >= dictIdx) {
                        const BYTE* const matchPtr = dictStart + (pos4 - dictIdx);
                        const size_t safeLen = MIN(prefixIdx - pos4, (size_t)(matchlimit - ip));
                        matchLength = lz4_count(ip, matchPtr, ip + safeLen);
                        if (matchLength >= MINMATCH) {
                            matchDistance = ipIndex - pos4;
                            goto _encode_sequence;
                        }
                    }
                }
            }
        }
        /* no match in prefix */
        if ((dict == USING_DICTCTX_HC) && searchIntoDict && (ipIndex - gDictEndIndex < DIST_MAX - 8)) {
            match_t dMatch = searchIntoDict(ip, ipIndex, matchlimit, ctx->dictCtx, gDictEndIndex);
            if (dMatch.len >= MINMATCH) {
                matchLength = (unsigned)dMatch.len;
                matchDistance = (unsigned)dMatch.off;
                goto _encode_sequence;
            }
        }
        ip += 1 + ((ip - anchor) >> 9);
        continue;

_encode_sequence:
        while (((ip > anchor) & ((U32)(ip - prefixPtr) > matchDistance)) && (ip[-1] == ip[-(int)matchDistance - 1])) {
            ip--; matchLength++;
        }
        ADDPOS8(ip + 1, ipIndex + 1);
        ADDPOS8(ip + 2, ipIndex + 2);
        ADDPOS4(ip + 1, ipIndex + 1);

        {   BYTE* const saved_op = op;
            if (encodeSequence(&ip, &op, &anchor, (int)matchLength, (int)matchDistance, limit, oend)) {
                op = saved_op;
                return 0;
            }
        }
        {   U32 endMatchIdx = (U32)(ip - prefixPtr) + prefixIdx;
            U32 pos_m2 = endMatchIdx - 2;
            if (pos_m2 < ilimitIdx) {
                if (ip - prefixPtr > 5) {
                    ADDPOS8(ip - 5, endMatchIdx - 5);
                }
                ADDPOS8(ip - 3, endMatchIdx - 3);
                ADDPOS8(ip - 2, endMatchIdx - 2);
                ADDPOS4(ip - 2, endMatchIdx - 2);
                ADDPOS4(ip - 1, endMatchIdx - 1);
            }
        }
    }

_last_literals:
    if (encodeLastLiterals(anchor, iend, &op, oend, limit)) return 0;
    *srcSizePtr = (int)(iend - (const BYTE*)src);
    return (int)((char*)op - dst);
}

/* ---------------- hash chain match finder ---------------- */
static U32 rotatePattern(size_t const rotate, U32 const pattern) {
    size_t const bitsToRotate = (rotate & (sizeof(pattern) - 1)) << 3;
    if (bitsToRotate == 0) return pattern;
    return (pattern << bitsToRotate) | (pattern >> (32 - bitsToRotate));
}

static unsigned countPattern(const BYTE* ip, const BYTE* const iEnd, U32 const pattern32) {
    const BYTE* const iStart = ip;
    U64 const pattern = (U64)pattern32 + (((U64)pattern32) << 32);
    while (ip < iEnd - (sizeof(pattern) - 1)) {
        U64 const diff = rd64(ip) ^ pattern;
        if (!diff) { ip += sizeof(pattern); continue; }
        ip += __builtin_ctzll(diff) >> 3;
        return (unsigned)(ip - iStart);
    }
    {   U64 patternByte = pattern;
        while ((ip < iEnd) && (*ip == (BYTE)patternByte)) {
            ip++; patternByte >>= 8;
        }
    }
    return (unsigned)(ip - iStart);
}

static unsigned reverseCountPattern(const BYTE* ip, const BYTE* const iLow, U32 pattern) {
    const BYTE* const iStart = ip;
    while (ip >= iLow + 4) {
        if (rd32(ip - 4) != pattern) break;
        ip -= 4;
    }
    {   const BYTE* bytePtr = (const BYTE*)(&pattern) + 3;
        while (ip > iLow) {
            if (ip[-1] != *bytePtr) break;
            ip--; bytePtr--;
        }
    }
    return (unsigned)(iStart - ip);
}

static int protectDictEnd(U32 const dictLimit, U32 const matchIndex) {
    return ((U32)((dictLimit - 1) - matchIndex) >= 3);
}

enum { REP_UNTESTED, REP_NOT, REP_CONFIRMED };

static match_t insertAndGetWiderMatch(lz4hc_ctx* const hc4, const BYTE* const ip,
                                      const BYTE* const iLowLimit, const BYTE* const iHighLimit,
                                      int longest, const int maxNbAttempts,
                                      const int patternAnalysis, const int chainSwap,
                                      const int dict, const int favorDecSpeed)
{
    U16* const chainTable = hc4->chainTable;
    U32* const hashTable = hc4->hashTable;
    const lz4hc_ctx* const dictCtx = hc4->dictCtx;
    const BYTE* const prefixPtr = hc4->prefixStart;
    const U32 prefixIdx = hc4->dictLimit;
    const U32 ipIndex = (U32)(ip - prefixPtr) + prefixIdx;
    const int withinStartDistance = (hc4->lowLimit + (DIST_MAX + 1) > ipIndex);
    const U32 lowestMatchIndex = (withinStartDistance) ? hc4->lowLimit : ipIndex - DIST_MAX;
    const BYTE* const dictStart = hc4->dictStart;
    const U32 dictIdx = hc4->lowLimit;
    const BYTE* const dictEnd = dictStart + prefixIdx - dictIdx;
    int const lookBackLength = (int)(ip - iLowLimit);
    int nbAttempts = maxNbAttempts;
    U32 matchChainPos = 0;
    U32 const pattern = rd32(ip);
    U32 matchIndex;
    int repeat = REP_UNTESTED;
    size_t srcPatternLength = 0;
    int offset = 0, sBack = 0;

    hc_insert(hc4, ip);
    matchIndex = hashTable[hashPtr(ip)];

    while ((matchIndex >= lowestMatchIndex) && (nbAttempts > 0)) {
        int matchLength = 0;
        nbAttempts--;
        if (favorDecSpeed && (ipIndex - matchIndex < 8)) {
            /* skip */
        } else if (matchIndex >= prefixIdx) {
            const BYTE* const matchPtr = prefixPtr + (matchIndex - prefixIdx);
            if (rd16(iLowLimit + longest - 1) == rd16(matchPtr - lookBackLength + longest - 1)) {
                if (rd32(matchPtr) == pattern) {
                    int const back = lookBackLength ? hc_countBack(ip, matchPtr, iLowLimit, prefixPtr) : 0;
                    matchLength = MINMATCH + (int)lz4_count(ip + MINMATCH, matchPtr + MINMATCH, iHighLimit);
                    matchLength -= back;
                    if (matchLength > longest) {
                        longest = matchLength;
                        offset = (int)(ipIndex - matchIndex);
                        sBack = back;
                    }
                }
            }
        } else {
            const BYTE* const matchPtr = dictStart + (matchIndex - dictIdx);
            if ((matchIndex <= prefixIdx - 4) && (rd32(matchPtr) == pattern)) {
                int back = 0;
                const BYTE* vLimit = ip + (prefixIdx - matchIndex);
                if (vLimit > iHighLimit) vLimit = iHighLimit;
                matchLength = (int)lz4_count(ip + MINMATCH, matchPtr + MINMATCH, vLimit) + MINMATCH;
                if ((ip + matchLength == vLimit) && (vLimit < iHighLimit))
                    matchLength += lz4_count(ip + matchLength, prefixPtr, iHighLimit);
                back = lookBackLength ? hc_countBack(ip, matchPtr, iLowLimit, dictStart) : 0;
                matchLength -= back;
                if (matchLength > longest) {
                    longest = matchLength;
                    offset = (int)(ipIndex - matchIndex);
                    sBack = back;
                }
            }
        }

        if (chainSwap && matchLength == longest) {
            if (matchIndex + (U32)longest <= ipIndex) {
                int const kTrigger = 4;
                U32 distanceToNextMatch = 1;
                int const end = longest - MINMATCH + 1;
                int step = 1;
                int accel = 1 << kTrigger;
                int pos;
                for (pos = 0; pos < end; pos += step) {
                    U32 const candidateDist = DELTANEXTU16(chainTable, matchIndex + (U32)pos);
                    step = (accel++ >> kTrigger);
                    if (candidateDist > distanceToNextMatch) {
                        distanceToNextMatch = candidateDist;
                        matchChainPos = (U32)pos;
                        accel = 1 << kTrigger;
                    }
                }
                if (distanceToNextMatch > 1) {
                    if (distanceToNextMatch > matchIndex) break;
                    matchIndex -= distanceToNextMatch;
                    continue;
                }
            }
        }

        {   U32 const distNextMatch = DELTANEXTU16(chainTable, matchIndex);
            if (patternAnalysis && distNextMatch == 1 && matchChainPos == 0) {
                U32 const matchCandidateIdx = matchIndex - 1;
                if (repeat == REP_UNTESTED) {
                    if (((pattern & 0xFFFF) == (pattern >> 16)) & ((pattern & 0xFF) == (pattern >> 24))) {
                        repeat = REP_CONFIRMED;
                        srcPatternLength = countPattern(ip + sizeof(pattern), iHighLimit, pattern) + sizeof(pattern);
                    } else {
                        repeat = REP_NOT;
                    }
                }
                if ((repeat == REP_CONFIRMED) && (matchCandidateIdx >= lowestMatchIndex)
                    && protectDictEnd(prefixIdx, matchCandidateIdx)) {
                    const int extDict = matchCandidateIdx < prefixIdx;
                    const BYTE* const matchPtr = extDict ? dictStart + (matchCandidateIdx - dictIdx) : prefixPtr + (matchCandidateIdx - prefixIdx);
                    if (rd32(matchPtr) == pattern) {
                        const BYTE* const iLimit = extDict ? dictEnd : iHighLimit;
                        size_t forwardPatternLength = countPattern(matchPtr + sizeof(pattern), iLimit, pattern) + sizeof(pattern);
                        if (extDict && matchPtr + forwardPatternLength == iLimit) {
                            U32 const rotatedPattern = rotatePattern(forwardPatternLength, pattern);
                            forwardPatternLength += countPattern(prefixPtr, iHighLimit, rotatedPattern);
                        }
                        {   const BYTE* const lowestMatchPtr = extDict ? dictStart : prefixPtr;
                            size_t backLength = reverseCountPattern(matchPtr, lowestMatchPtr, pattern);
                            size_t currentSegmentLength;
                            if (!extDict && matchPtr - backLength == prefixPtr && dictIdx < prefixIdx) {
                                U32 const rotatedPattern = rotatePattern((U32)(-(int)backLength), pattern);
                                backLength += reverseCountPattern(dictEnd, dictStart, rotatedPattern);
                            }
                            backLength = matchCandidateIdx - MAX(matchCandidateIdx - (U32)backLength, lowestMatchIndex);
                            currentSegmentLength = backLength + forwardPatternLength;
                            if ((currentSegmentLength >= srcPatternLength) && (forwardPatternLength <= srcPatternLength)) {
                                U32 const newMatchIndex = matchCandidateIdx + (U32)forwardPatternLength - (U32)srcPatternLength;
                                if (protectDictEnd(prefixIdx, newMatchIndex))
                                    matchIndex = newMatchIndex;
                                else
                                    matchIndex = prefixIdx;
                            } else {
                                U32 const newMatchIndex = matchCandidateIdx - (U32)backLength;
                                if (!protectDictEnd(prefixIdx, newMatchIndex)) {
                                    matchIndex = prefixIdx;
                                } else {
                                    matchIndex = newMatchIndex;
                                    if (lookBackLength == 0) {
                                        size_t const maxML = MIN(currentSegmentLength, srcPatternLength);
                                        if ((size_t)longest < maxML) {
                                            if ((size_t)(ip - prefixPtr) + prefixIdx - matchIndex > DIST_MAX) break;
                                            longest = (int)maxML;
                                            offset = (int)(ipIndex - matchIndex);
                                        }
                                        {   U32 const distToNextPattern = DELTANEXTU16(chainTable, matchIndex);
                                            if (distToNextPattern > matchIndex) break;
                                            matchIndex -= distToNextPattern;
                                        }
                                    }
                                }
                            }
                        }
                        continue;
                    }
                }
            }
        }

        matchIndex -= DELTANEXTU16(chainTable, matchIndex + matchChainPos);
    }

    if (dict == USING_DICTCTX_HC && nbAttempts > 0 && withinStartDistance) {
        size_t const dictEndOffset = (size_t)(dictCtx->end - dictCtx->prefixStart) + dictCtx->dictLimit;
        U32 dictMatchIndex = dictCtx->hashTable[hashPtr(ip)];
        matchIndex = dictMatchIndex + lowestMatchIndex - (U32)dictEndOffset;
        while (ipIndex - matchIndex <= DIST_MAX && nbAttempts--) {
            const BYTE* const matchPtr = dictCtx->prefixStart - dictCtx->dictLimit + dictMatchIndex;
            if (rd32(matchPtr) == pattern) {
                int mlt;
                int back = 0;
                const BYTE* vLimit = ip + (dictEndOffset - dictMatchIndex);
                if (vLimit > iHighLimit) vLimit = iHighLimit;
                mlt = (int)lz4_count(ip + MINMATCH, matchPtr + MINMATCH, vLimit) + MINMATCH;
                back = lookBackLength ? hc_countBack(ip, matchPtr, iLowLimit, dictCtx->prefixStart) : 0;
                mlt -= back;
                if (mlt > longest) {
                    longest = mlt;
                    offset = (int)(ipIndex - matchIndex);
                    sBack = back;
                }
            }
            {   U32 const nextOffset = DELTANEXTU16(dictCtx->chainTable, dictMatchIndex);
                dictMatchIndex -= nextOffset;
                matchIndex -= nextOffset;
            }
        }
    }

    {   match_t md;
        md.len = longest;
        md.off = offset;
        md.back = sBack;
        return md;
    }
}

static match_t insertAndFindBestMatch(lz4hc_ctx* const hc4, const BYTE* const ip, const BYTE* const iLimit,
                                      const int maxNbAttempts, const int patternAnalysis, const int dict) {
    return insertAndGetWiderMatch(hc4, ip, ip, iLimit, MINMATCH - 1, maxNbAttempts, patternAnalysis, 0, dict, 0);
}

static int compress_hashChain(lz4hc_ctx* const ctx, const char* const source, char* const dest,
                              int* srcSizePtr, int const maxOutputSize, int maxNbAttempts,
                              const int limit, const int dict)
{
    const int inputSize = *srcSizePtr;
    const int patternAnalysis = (maxNbAttempts > 128);
    const BYTE* ip = (const BYTE*)source;
    const BYTE* anchor = ip;
    const BYTE* const iend = ip + inputSize;
    const BYTE* const mflimit = iend - MFLIMIT;
    const BYTE* const matchlimit = (iend - LASTLITERALS);
    BYTE* op = (BYTE*)dest;
    BYTE* oend = op + maxOutputSize;
    const BYTE* start0;
    const BYTE* start2 = NULL;
    const BYTE* start3 = NULL;
    match_t m0, m1, m2, m3;
    const match_t nomatch = { 0, 0, 0 };

    *srcSizePtr = 0;
    if (inputSize < LZ4_MIN_LENGTH) goto _last_literals;

    while (ip <= mflimit) {
        m1 = insertAndFindBestMatch(ctx, ip, matchlimit, maxNbAttempts, patternAnalysis, dict);
        if (m1.len < MINMATCH) { ip++; continue; }

        start0 = ip; m0 = m1;

_Search2:
        if (ip + m1.len <= mflimit) {
            start2 = ip + m1.len - 2;
            m2 = insertAndGetWiderMatch(ctx, start2, ip + 0, matchlimit, m1.len,
                                        maxNbAttempts, patternAnalysis, 0, dict, 0);
            start2 += m2.back;
        } else {
            m2 = nomatch;
        }

        if (m2.len <= m1.len) {
            if (encodeSequence(&ip, &op, &anchor, m1.len, m1.off, limit, oend)) return 0;
            continue;
        }

        if (start0 < ip) {
            if (start2 < ip + m0.len) {
                ip = start0; m1 = m0;
            }
        }

        if ((start2 - ip) < 3) {
            ip = start2;
            m1 = m2;
            goto _Search2;
        }

_Search3:
        if ((start2 - ip) < OPTIMAL_ML) {
            int correction;
            int new_ml = m1.len;
            if (new_ml > OPTIMAL_ML) new_ml = OPTIMAL_ML;
            if (ip + new_ml > start2 + m2.len - MINMATCH)
                new_ml = (int)(start2 - ip) + m2.len - MINMATCH;
            correction = new_ml - (int)(start2 - ip);
            if (correction > 0) {
                start2 += correction;
                m2.len -= correction;
            }
        }

        if (start2 + m2.len <= mflimit) {
            start3 = start2 + m2.len - 3;
            m3 = insertAndGetWiderMatch(ctx, start3, start2, matchlimit, m2.len,
                                        maxNbAttempts, patternAnalysis, 0, dict, 0);
            start3 += m3.back;
        } else {
            m3 = nomatch;
        }

        if (m3.len <= m2.len) {
            if (start2 < ip + m1.len) m1.len = (int)(start2 - ip);
            if (encodeSequence(&ip, &op, &anchor, m1.len, m1.off, limit, oend)) return 0;
            ip = start2;
            if (encodeSequence(&ip, &op, &anchor, m2.len, m2.off, limit, oend)) return 0;
            continue;
        }

        if (start3 < ip + m1.len + 3) {
            if (start3 >= (ip + m1.len)) {
                if (start2 < ip + m1.len) {
                    int correction = (int)(ip + m1.len - start2);
                    start2 += correction;
                    m2.len -= correction;
                    if (m2.len < MINMATCH) {
                        start2 = start3;
                        m2 = m3;
                    }
                }
                if (encodeSequence(&ip, &op, &anchor, m1.len, m1.off, limit, oend)) return 0;
                ip = start3;
                m1 = m3;
                start0 = start2;
                m0 = m2;
                goto _Search2;
            }
            start2 = start3;
            m2 = m3;
            goto _Search3;
        }

        if (start2 < ip + m1.len) {
            if ((start2 - ip) < OPTIMAL_ML) {
                int correction;
                if (m1.len > OPTIMAL_ML) m1.len = OPTIMAL_ML;
                if (ip + m1.len > start2 + m2.len - MINMATCH)
                    m1.len = (int)(start2 - ip) + m2.len - MINMATCH;
                correction = m1.len - (int)(start2 - ip);
                if (correction > 0) {
                    start2 += correction;
                    m2.len -= correction;
                }
            } else {
                m1.len = (int)(start2 - ip);
            }
        }
        if (encodeSequence(&ip, &op, &anchor, m1.len, m1.off, limit, oend)) return 0;

        ip = start2; m1 = m2;
        start2 = start3; m2 = m3;
        goto _Search3;
    }

_last_literals:
    if (encodeLastLiterals(anchor, iend, &op, oend, limit)) return 0;
    *srcSizePtr = (int)(iend - (const BYTE*)source);
    return (int)(((char*)op) - dest);
}

/* ---------------- optimal parser ---------------- */
typedef struct { int price; int off; int mlen; int litlen; } optimal_t;

static inline int literalsPrice(int const litlen) {
    int price = litlen;
    if (litlen >= (int)RUN_MASK) price += 1 + ((litlen - (int)RUN_MASK) / 255);
    return price;
}

static inline int sequencePrice(int litlen, int mlen) {
    int price = 1 + 2;
    price += literalsPrice(litlen);
    if (mlen >= (int)(ML_MASK + MINMATCH)) price += 1 + ((mlen - (int)(ML_MASK + MINMATCH)) / 255);
    return price;
}

static match_t findLongerMatch(lz4hc_ctx* const ctx, const BYTE* ip, const BYTE* const iHighLimit,
                               int minLen, int nbSearches, const int dict, const int favorDecSpeed) {
    match_t const match0 = { 0, 0, 0 };
    match_t md = insertAndGetWiderMatch(ctx, ip, ip, iHighLimit, minLen, nbSearches, 1, 1, dict, favorDecSpeed);
    if (md.len <= minLen) return match0;
    if (favorDecSpeed) {
        if ((md.len > 18) & (md.len <= 36)) md.len = 18;
    }
    return md;
}

#define TRAILING_LITERALS 3

static int compress_optimal(lz4hc_ctx* ctx, const char* const source, char* dst,
                            int* srcSizePtr, int dstCapacity, int const nbSearches,
                            size_t sufficient_len, const int limit, int const fullUpdate,
                            const int dict, const int favorDecSpeed)
{
    int retval = 0;
    optimal_t* const opt = (optimal_t*)malloc(sizeof(optimal_t) * (LZ4_OPT_NUM + TRAILING_LITERALS));
    const BYTE* ip = (const BYTE*)source;
    const BYTE* anchor = ip;
    const BYTE* const iend = ip + *srcSizePtr;
    const BYTE* const mflimit = iend - MFLIMIT;
    const BYTE* const matchlimit = iend - LASTLITERALS;
    BYTE* op = (BYTE*)dst;
    BYTE* oend = op + dstCapacity;

    if (opt == NULL) return 0;
    *srcSizePtr = 0;
    if (sufficient_len >= LZ4_OPT_NUM) sufficient_len = LZ4_OPT_NUM - 1;

    while (ip <= mflimit) {
        int const llen = (int)(ip - anchor);
        int best_mlen, best_off;
        int cur, last_match_pos = 0;

        match_t const firstMatch = findLongerMatch(ctx, ip, matchlimit, MINMATCH - 1, nbSearches, dict, favorDecSpeed);
        if (firstMatch.len == 0) { ip++; continue; }

        if ((size_t)firstMatch.len > sufficient_len) {
            int const firstML = firstMatch.len;
            if (encodeSequence(&ip, &op, &anchor, firstML, firstMatch.off, limit, oend)) goto _overflow;
            continue;
        }

        {   int rPos;
            for (rPos = 0; rPos < MINMATCH; rPos++) {
                int const cost = literalsPrice(llen + rPos);
                opt[rPos].mlen = 1;
                opt[rPos].off = 0;
                opt[rPos].litlen = llen + rPos;
                opt[rPos].price = cost;
            }
        }
        {   int const matchML = firstMatch.len;
            int const offset = firstMatch.off;
            int mlen;
            for (mlen = MINMATCH; mlen <= matchML; mlen++) {
                int const cost = sequencePrice(llen, mlen);
                opt[mlen].mlen = mlen;
                opt[mlen].off = offset;
                opt[mlen].litlen = llen;
                opt[mlen].price = cost;
            }
        }
        last_match_pos = firstMatch.len;
        {   int addLit;
            for (addLit = 1; addLit <= TRAILING_LITERALS; addLit++) {
                opt[last_match_pos + addLit].mlen = 1;
                opt[last_match_pos + addLit].off = 0;
                opt[last_match_pos + addLit].litlen = addLit;
                opt[last_match_pos + addLit].price = opt[last_match_pos].price + literalsPrice(addLit);
            }
        }

        for (cur = 1; cur < last_match_pos; cur++) {
            const BYTE* const curPtr = ip + cur;
            match_t newMatch;

            if (curPtr > mflimit) break;
            if (fullUpdate) {
                if ((opt[cur + 1].price <= opt[cur].price)
                    && (opt[cur + MINMATCH].price < opt[cur].price + 3))
                    continue;
            } else {
                if (opt[cur + 1].price <= opt[cur].price) continue;
            }

            if (fullUpdate)
                newMatch = findLongerMatch(ctx, curPtr, matchlimit, MINMATCH - 1, nbSearches, dict, favorDecSpeed);
            else
                newMatch = findLongerMatch(ctx, curPtr, matchlimit, last_match_pos - cur, nbSearches, dict, favorDecSpeed);
            if (!newMatch.len) continue;

            if (((size_t)newMatch.len > sufficient_len) || (newMatch.len + cur >= LZ4_OPT_NUM)) {
                best_mlen = newMatch.len;
                best_off = newMatch.off;
                last_match_pos = cur + 1;
                goto encode;
            }

            {   int const baseLitlen = opt[cur].litlen;
                int litlen;
                for (litlen = 1; litlen < MINMATCH; litlen++) {
                    int const price = opt[cur].price - literalsPrice(baseLitlen) + literalsPrice(baseLitlen + litlen);
                    int const pos = cur + litlen;
                    if (price < opt[pos].price) {
                        opt[pos].mlen = 1;
                        opt[pos].off = 0;
                        opt[pos].litlen = baseLitlen + litlen;
                        opt[pos].price = price;
                    }
                }
            }

            {   int const matchML = newMatch.len;
                int ml = MINMATCH;
                for (; ml <= matchML; ml++) {
                    int const pos = cur + ml;
                    int const offset = newMatch.off;
                    int price;
                    int ll;
                    if (opt[cur].mlen == 1) {
                        ll = opt[cur].litlen;
                        price = ((cur > ll) ? opt[cur - ll].price : 0) + sequencePrice(ll, ml);
                    } else {
                        ll = 0;
                        price = opt[cur].price + sequencePrice(0, ml);
                    }
                    if (pos > last_match_pos + TRAILING_LITERALS
                        || price <= opt[pos].price - (int)favorDecSpeed) {
                        if ((ml == matchML) && (last_match_pos < pos))
                            last_match_pos = pos;
                        opt[pos].mlen = ml;
                        opt[pos].off = offset;
                        opt[pos].litlen = ll;
                        opt[pos].price = price;
                    }
                }
            }
            {   int addLit;
                for (addLit = 1; addLit <= TRAILING_LITERALS; addLit++) {
                    opt[last_match_pos + addLit].mlen = 1;
                    opt[last_match_pos + addLit].off = 0;
                    opt[last_match_pos + addLit].litlen = addLit;
                    opt[last_match_pos + addLit].price = opt[last_match_pos].price + literalsPrice(addLit);
                }
            }
        }

        best_mlen = opt[last_match_pos].mlen;
        best_off = opt[last_match_pos].off;
        cur = last_match_pos - best_mlen;

encode:
        {   int candidate_pos = cur;
            int selected_matchLength = best_mlen;
            int selected_offset = best_off;
            while (1) {
                int const next_matchLength = opt[candidate_pos].mlen;
                int const next_offset = opt[candidate_pos].off;
                opt[candidate_pos].mlen = selected_matchLength;
                opt[candidate_pos].off = selected_offset;
                selected_matchLength = next_matchLength;
                selected_offset = next_offset;
                if (next_matchLength > candidate_pos) break;
                candidate_pos -= next_matchLength;
            }
        }
        {   int rPos = 0;
            while (rPos < last_match_pos) {
                int const ml = opt[rPos].mlen;
                int const offset = opt[rPos].off;
                if (ml == 1) { ip++; rPos++; continue; }
                rPos += ml;
                if (encodeSequence(&ip, &op, &anchor, ml, offset, limit, oend)) goto _overflow;
            }
        }
    }

    if (encodeLastLiterals(anchor, iend, &op, oend, limit)) goto _overflow;
    *srcSizePtr = (int)(iend - (const BYTE*)source);
    retval = (int)((char*)op - dst);
    free(opt);
    return retval;
_overflow:
    free(opt);
    return 0;
}

/* ---------------- generic dispatch ---------------- */
static int compress_generic_internal(lz4hc_ctx* const ctx, const char* const src, char* const dst,
                                     int* const srcSizePtr, int const dstCapacity, int cLevel,
                                     const int limit, const int dict)
{
    if ((U32)*srcSizePtr > (U32)LZ4_MAX_INPUT_SIZE) return 0;
    ctx->end += *srcSizePtr;
    {   cParams_t const cParam = getCLevelParams(cLevel);
        int const favor = ctx->favorDecSpeed ? 1 : 0;
        int result;
        if (cParam.strat == STRAT_MID) {
            result = mid_compress(ctx, src, dst, srcSizePtr, dstCapacity, limit, dict);
        } else if (cParam.strat == STRAT_HC) {
            result = compress_hashChain(ctx, src, dst, srcSizePtr, dstCapacity, cParam.nbSearches, limit, dict);
        } else {
            result = compress_optimal(ctx, src, dst, srcSizePtr, dstCapacity, cParam.nbSearches,
                                      cParam.targetLength, limit, cLevel >= LZ4HC_CLEVEL_MAX, dict, favor);
        }
        if (result <= 0) ctx->dirty = 1;
        return result;
    }
}

static void setExternalDict(lz4hc_ctx* ctxPtr, const BYTE* newBlock) {
    if ((ctxPtr->end >= ctxPtr->prefixStart + 4)
        && (getCLevelParams(ctxPtr->compressionLevel).strat != STRAT_MID)) {
        hc_insert(ctxPtr, ctxPtr->end - 3);
    }
    ctxPtr->lowLimit = ctxPtr->dictLimit;
    ctxPtr->dictStart = ctxPtr->prefixStart;
    ctxPtr->dictLimit += (U32)(ctxPtr->end - ctxPtr->prefixStart);
    ctxPtr->prefixStart = newBlock;
    ctxPtr->end = newBlock;
    ctxPtr->nextToUpdate = ctxPtr->dictLimit;
    ctxPtr->dictCtx = NULL;
}

static int compress_generic(lz4hc_ctx* const ctx, const char* const src, char* const dst,
                            int* const srcSizePtr, int const dstCapacity, int cLevel, const int limit)
{
    if (ctx->dictCtx == NULL) {
        return compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit, NO_DICTCTX);
    } else {
        const size_t position = (size_t)(ctx->end - ctx->prefixStart) + (ctx->dictLimit - ctx->lowLimit);
        if (position >= 64 KB) {
            ctx->dictCtx = NULL;
            return compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit, NO_DICTCTX);
        } else if (position == 0 && *srcSizePtr > (int)(4 KB)) {
            memcpy(ctx, ctx->dictCtx, sizeof(lz4hc_ctx));
            setExternalDict(ctx, (const BYTE*)src);
            ctx->compressionLevel = (short)cLevel;
            return compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit, NO_DICTCTX);
        } else {
            return compress_generic_internal(ctx, src, dst, srcSizePtr, dstCapacity, cLevel, limit, USING_DICTCTX_HC);
        }
    }
}

int lz4hc_compress_extState_fastReset(lz4hc_ctx* ctx, const char* src, char* dst, int srcSize, int dstCapacity, int level) {
    lz4hc_resetStream_fast(ctx, level);
    init_internal(ctx, (const BYTE*)src);
    if (dstCapacity < lz4_compressBound(srcSize))
        return compress_generic(ctx, src, dst, &srcSize, dstCapacity, level, LIMITED_OUTPUT);
    return compress_generic(ctx, src, dst, &srcSize, dstCapacity, level, NOT_LIMITED);
}

int lz4hc_compress(const char* src, char* dst, int srcSize, int dstCapacity, int level) {
    lz4hc_ctx* s = (lz4hc_ctx*)malloc(sizeof(lz4hc_ctx));
    int r;
    if (!s) return 0;
    lz4hc_initStream(s);
    r = lz4hc_compress_extState_fastReset(s, src, dst, srcSize, dstCapacity, level);
    free(s);
    return r;
}

int lz4hc_loadDict(lz4hc_ctx* ctxPtr, const char* dictionary, int dictSize) {
    cParams_t cp;
    if (dictSize > (int)(64 KB)) {
        dictionary += (size_t)dictSize - 64 KB;
        dictSize = 64 KB;
    }
    {   int const cLevel = ctxPtr->compressionLevel;
        lz4hc_initStream(ctxPtr);
        lz4hc_setCompressionLevel(ctxPtr, cLevel);
        cp = getCLevelParams(cLevel);
    }
    init_internal(ctxPtr, (const BYTE*)dictionary);
    ctxPtr->end = (const BYTE*)dictionary + dictSize;
    if (cp.strat == STRAT_MID) {
        mid_fillHTable(ctxPtr, dictionary, (size_t)dictSize);
    } else {
        if (dictSize >= LZ4HC_HASHSIZE) hc_insert(ctxPtr, ctxPtr->end - 3);
    }
    return dictSize;
}

void lz4hc_attach_dictionary(lz4hc_ctx* w, const lz4hc_ctx* d) { w->dictCtx = d; }

int lz4hc_compress_continue(lz4hc_ctx* ctxPtr, const char* src, char* dst, int srcSize, int dstCapacity) {
    int const limit = (dstCapacity < lz4_compressBound(srcSize)) ? LIMITED_OUTPUT : NOT_LIMITED;
    if (ctxPtr->prefixStart == NULL)
        init_internal(ctxPtr, (const BYTE*)src);

    if ((size_t)(ctxPtr->end - ctxPtr->prefixStart) + ctxPtr->dictLimit > 2 GB) {
        size_t dictSize = (size_t)(ctxPtr->end - ctxPtr->prefixStart);
        if (dictSize > 64 KB) dictSize = 64 KB;
        lz4hc_loadDict(ctxPtr, (const char*)(ctxPtr->end) - dictSize, (int)dictSize);
    }

    if ((const BYTE*)src != ctxPtr->end)
        setExternalDict(ctxPtr, (const BYTE*)src);

    {   const BYTE* sourceEnd = (const BYTE*)src + srcSize;
        const BYTE* const dictBegin = ctxPtr->dictStart;
        const BYTE* const dictEnd = ctxPtr->dictStart + (ctxPtr->dictLimit - ctxPtr->lowLimit);
        if ((sourceEnd > dictBegin) && ((const BYTE*)src < dictEnd)) {
            if (sourceEnd > dictEnd) sourceEnd = dictEnd;
            ctxPtr->lowLimit += (U32)(sourceEnd - ctxPtr->dictStart);
            ctxPtr->dictStart += (U32)(sourceEnd - ctxPtr->dictStart);
            if (ctxPtr->dictLimit - ctxPtr->lowLimit < LZ4HC_HASHSIZE) {
                ctxPtr->lowLimit = ctxPtr->dictLimit;
                ctxPtr->dictStart = ctxPtr->prefixStart;
            }
        }
    }
    return compress_generic(ctxPtr, src, dst, &srcSize, dstCapacity, ctxPtr->compressionLevel, limit);
}

int lz4hc_saveDict(lz4hc_ctx* streamPtr, char* safeBuffer, int dictSize) {
    int const prefixSize = (int)(streamPtr->end - streamPtr->prefixStart);
    if (dictSize > (int)(64 KB)) dictSize = 64 KB;
    if (dictSize < 4) dictSize = 0;
    if (dictSize > prefixSize) dictSize = prefixSize;
    if (dictSize > 0)
        memmove(safeBuffer, streamPtr->end - dictSize, (size_t)dictSize);
    {   U32 const endIndex = (U32)(streamPtr->end - streamPtr->prefixStart) + streamPtr->dictLimit;
        streamPtr->end = (safeBuffer == NULL) ? NULL : (const BYTE*)safeBuffer + dictSize;
        streamPtr->prefixStart = (const BYTE*)safeBuffer;
        streamPtr->dictLimit = endIndex - (U32)dictSize;
        streamPtr->lowLimit = endIndex - (U32)dictSize;
        streamPtr->dictStart = streamPtr->prefixStart;
        if (streamPtr->nextToUpdate < streamPtr->dictLimit)
            streamPtr->nextToUpdate = streamPtr->dictLimit;
    }
    return dictSize;
}
