/* LZ4 frame format (clean-room implementation) */
#include "lz4frame.h"
#include <stdlib.h>
#include <string.h>

typedef uint8_t BYTE;
typedef uint32_t U32;
typedef uint64_t U64;
#define KB *(1U<<10)
#define MB *(1U<<20)
#define GB *(1U<<30)
#define MIN(a,b) ((a)<(b)?(a):(b))
#define BHSize LZ4F_BLOCK_HEADER_SIZE
#define BFSize LZ4F_BLOCK_CHECKSUM_SIZE
#define minFHSize LZ4F_HEADER_SIZE_MIN
#define maxFHSize LZ4F_HEADER_SIZE_MAX

#define ERR(e) ((size_t)-(ptrdiff_t)(LZ4F_ERROR_##e))

int lz4f_isError(size_t code) { return code > (size_t)-(ptrdiff_t)LZ4F_ERROR_maxCode; }

static const char* const errNames[] = {
    "OK_NoError", "ERROR_GENERIC", "ERROR_maxBlockSize_invalid", "ERROR_blockMode_invalid",
    "ERROR_parameter_invalid", "ERROR_compressionLevel_invalid", "ERROR_headerVersion_wrong",
    "ERROR_blockChecksum_invalid", "ERROR_reservedFlag_set", "ERROR_allocation_failed",
    "ERROR_srcSize_tooLarge", "ERROR_dstMaxSize_tooSmall", "ERROR_frameHeader_incomplete",
    "ERROR_frameType_unknown", "ERROR_frameSize_wrong", "ERROR_srcPtr_wrong",
    "ERROR_decompressionFailed", "ERROR_headerChecksum_invalid", "ERROR_contentChecksum_invalid",
    "ERROR_frameDecoding_alreadyStarted", "ERROR_compressionState_uninitialized",
    "ERROR_parameter_null", "ERROR_io_write", "ERROR_io_read", "ERROR_maxCode"
};

const char* lz4f_getErrorName(size_t code) {
    if (lz4f_isError(code)) return errNames[-(ptrdiff_t)code];
    return "Unspecified error code";
}

static void wrLE32(void* p, U32 v) {
    BYTE* d = (BYTE*)p;
    d[0] = (BYTE)v; d[1] = (BYTE)(v >> 8); d[2] = (BYTE)(v >> 16); d[3] = (BYTE)(v >> 24);
}
static void wrLE64(void* p, U64 v) { wrLE32(p, (U32)v); wrLE32((BYTE*)p + 4, (U32)(v >> 32)); }
static U32 rdLE32(const void* p) {
    const BYTE* s = (const BYTE*)p;
    return (U32)s[0] | ((U32)s[1] << 8) | ((U32)s[2] << 16) | ((U32)s[3] << 24);
}
static U64 rdLE64(const void* p) { return (U64)rdLE32(p) | ((U64)rdLE32((const BYTE*)p + 4) << 32); }

static BYTE headerChecksum(const void* header, size_t length) {
    U32 const xxh = xxh32(header, length, 0);
    return (BYTE)(xxh >> 8);
}

size_t lz4f_getBlockSize(int blockSizeID) {
    static const size_t blockSizes[4] = { 64 KB, 256 KB, 1 MB, 4 MB };
    if (blockSizeID == 0) blockSizeID = 7;
    if (blockSizeID < 4 || blockSizeID > 7) return ERR(maxBlockSize_invalid);
    return blockSizes[blockSizeID - 4];
}

static int optimalBSID(int requestedBSID, size_t srcSize) {
    int proposedBSID = 4;
    size_t maxBlockSize = 64 KB;
    while (requestedBSID > proposedBSID) {
        if (srcSize <= maxBlockSize) return proposedBSID;
        proposedBSID++;
        maxBlockSize <<= 2;
    }
    return requestedBSID;
}

/* ---------------- CDict ---------------- */
lz4f_cdict* lz4f_createCDict(const void* dictBuffer, size_t dictSize) {
    const char* dictStart = (const char*)dictBuffer;
    lz4f_cdict* cd = (lz4f_cdict*)calloc(1, sizeof(*cd));
    if (!cd) return NULL;
    if (dictSize > 64 KB) {
        dictStart += dictSize - 64 KB;
        dictSize = 64 KB;
    }
    cd->dictContent = malloc(dictSize ? dictSize : 1);
    cd->fastCtx = (lz4_stream*)malloc(sizeof(lz4_stream));
    cd->HCCtx = (lz4hc_ctx*)malloc(sizeof(lz4hc_ctx));
    if (!cd->dictContent || !cd->fastCtx || !cd->HCCtx) { lz4f_freeCDict(cd); return NULL; }
    if (dictSize) memcpy(cd->dictContent, dictStart, dictSize);
    lz4_initStream(cd->fastCtx);
    lz4_loadDictSlow(cd->fastCtx, (const char*)cd->dictContent, (int)dictSize);
    lz4hc_initStream(cd->HCCtx);
    lz4hc_setCompressionLevel(cd->HCCtx, LZ4HC_CLEVEL_DEFAULT);
    lz4hc_loadDict(cd->HCCtx, (const char*)cd->dictContent, (int)dictSize);
    return cd;
}

void lz4f_freeCDict(lz4f_cdict* cd) {
    if (!cd) return;
    free(cd->dictContent);
    free(cd->fastCtx);
    free(cd->HCCtx);
    free(cd);
}

