enum { CTX_NONE = 0, CTX_FAST = 1, CTX_HC = 2 };

struct lz4f_cctx_s {
    lz4f_prefs prefs;
    U32 cStage;
    const lz4f_cdict* cdict;
    size_t maxBlockSize;
    size_t maxBufferSize;
