}

static size_t compressBound_internal(size_t srcSize, const lz4f_prefs* prefsPtr, size_t alreadyBuffered) {
    lz4f_prefs prefsNull;
    memset(&prefsNull, 0, sizeof(prefsNull));
    prefsNull.frameInfo.contentChecksumFlag = 1;
    {   const lz4f_prefs* const prefs = (prefsPtr == NULL) ? &prefsNull : prefsPtr;
        U32 const flush = prefs->autoFlush | (srcSize == 0);
        int const blockID = prefs->frameInfo.blockSizeID;
        size_t const blockSize = lz4f_getBlockSize(blockID);
        size_t const maxBuffered = blockSize - 1;
        size_t const bufferedSize = MIN(alreadyBuffered, maxBuffered);
        size_t const maxSrcSize = srcSize + bufferedSize;
        unsigned const nbFullBlocks = (unsigned)(maxSrcSize / blockSize);
        size_t const partialBlockSize = maxSrcSize & (blockSize - 1);
        size_t const lastBlockSize = flush ? partialBlockSize : 0;
        unsigned const nbBlocks = nbFullBlocks + (lastBlockSize > 0);
        size_t const blockCRCSize = BFSize * (size_t)prefs->frameInfo.blockChecksumFlag;
        size_t const frameEnd = BHSize + ((size_t)prefs->frameInfo.contentChecksumFlag * BFSize);
        return ((BHSize + blockCRCSize) * nbBlocks) + (blockSize * nbFullBlocks) + lastBlockSize + frameEnd;
    }
}

size_t lz4f_compressBound(size_t srcSize, const lz4f_prefs* prefs) {
    return compressBound_internal(srcSize, prefs, (size_t)-1);
}

size_t lz4f_compressFrameBound(size_t srcSize, const lz4f_prefs* preferencesPtr) {
    lz4f_prefs prefs;
    size_t const headerSize = maxFHSize;
    if (preferencesPtr != NULL) prefs = *preferencesPtr;
    else memset(&prefs, 0, sizeof(prefs));
    prefs.autoFlush = 1;
    return headerSize + compressBound_internal(srcSize, &prefs, 0);
}

static void initStream(void* ctx, const lz4f_cdict* cdict, int level, int blockMode) {
    if (level < LZ4HC_CLEVEL_MIN) {
        if (cdict || blockMode == LZ4F_blockLinked) {
            lz4_resetStream_fast((lz4_stream*)ctx);
            if (cdict) lz4_attach_dictionary((lz4_stream*)ctx, cdict->fastCtx);
        }
    } else {
        lz4hc_resetStream_fast((lz4hc_ctx*)ctx, level);
        if (cdict) lz4hc_attach_dictionary((lz4hc_ctx*)ctx, cdict->HCCtx);
    }
}

typedef int (*compressFunc_t)(void* ctx, const char* src, char* dst, int srcSize, int dstSize, int level, const lz4f_cdict* cdict);

static int compressBlock(void* ctx, const char* src, char* dst, int srcSize, int dstCapacity, int level, const lz4f_cdict* cdict) {
    int const acceleration = (level < 0) ? -level + 1 : 1;
    initStream(ctx, cdict, level, LZ4F_blockIndependent);
    if (cdict) return lz4_compress_fast_continue((lz4_stream*)ctx, src, dst, srcSize, dstCapacity, acceleration);
    return lz4_compress_fast_extState_fastReset((lz4_stream*)ctx, src, dst, srcSize, dstCapacity, acceleration);
}

static int compressBlock_continue(void* ctx, const char* src, char* dst, int srcSize, int dstCapacity, int level, const lz4f_cdict* cdict) {
    int const acceleration = (level < 0) ? -level + 1 : 1;
    (void)cdict;
    return lz4_compress_fast_continue((lz4_stream*)ctx, src, dst, srcSize, dstCapacity, acceleration);
}

static int compressBlockHC(void* ctx, const char* src, char* dst, int srcSize, int dstCapacity, int level, const lz4f_cdict* cdict) {
    initStream(ctx, cdict, level, LZ4F_blockIndependent);
    if (cdict) return lz4hc_compress_continue((lz4hc_ctx*)ctx, src, dst, srcSize, dstCapacity);
    return lz4hc_compress_extState_fastReset((lz4hc_ctx*)ctx, src, dst, srcSize, dstCapacity, level);
}

static int compressBlockHC_continue(void* ctx, const char* src, char* dst, int srcSize, int dstCapacity, int level, const lz4f_cdict* cdict) {
    (void)level; (void)cdict;
    return lz4hc_compress_continue((lz4hc_ctx*)ctx, src, dst, srcSize, dstCapacity);
}

static compressFunc_t selectCompression(int blockMode, int level) {
    if (level < LZ4HC_CLEVEL_MIN) {
        if (blockMode == LZ4F_blockIndependent) return compressBlock;
        return compressBlock_continue;
    }
    if (blockMode == LZ4F_blockIndependent) return compressBlockHC;
    return compressBlockHC_continue;
}

static size_t makeBlock(void* dst, const void* src, size_t srcSize, compressFunc_t compress, void* lz4ctx,
                        int level, const lz4f_cdict* cdict, int crcFlag) {
    BYTE* const cSizePtr = (BYTE*)dst;
    U32 cSize;
    cSize = (U32)compress(lz4ctx, (const char*)src, (char*)(cSizePtr + BHSize), (int)srcSize, (int)srcSize - 1, level, cdict);
    if (cSize == 0 || cSize >= srcSize) {
        cSize = (U32)srcSize;
        wrLE32(cSizePtr, cSize | LZ4F_BLOCKUNCOMPRESSED_FLAG);
        memcpy(cSizePtr + BHSize, src, srcSize);
    } else {
        wrLE32(cSizePtr, cSize);
    }
    if (crcFlag) {
        U32 const crc32 = xxh32(cSizePtr + BHSize, cSize, 0);
        wrLE32(cSizePtr + BHSize + cSize, crc32);
    }
    return BHSize + cSize + ((U32)crcFlag) * BFSize;
}

static int localSaveDict(lz4f_cctx* c) {
    if (c->prefs.compressionLevel < LZ4HC_CLEVEL_MIN)
        return lz4_saveDict((lz4_stream*)c->lz4CtxPtr, (char*)c->tmpBuff, 64 KB);
    return lz4hc_saveDict((lz4hc_ctx*)c->lz4CtxPtr, (char*)c->tmpBuff, 64 KB);
}

size_t lz4f_compressBegin_usingCDict(lz4f_cctx* cctx, void* dstBuffer, size_t dstCapacity,
                                     const lz4f_cdict* cdict, const lz4f_prefs* preferencesPtr)
{
    lz4f_prefs prefNull;
    BYTE* const dstStart = (BYTE*)dstBuffer;
    BYTE* dstPtr = dstStart;

    if (dstCapacity < maxFHSize) return ERR(dstMaxSize_tooSmall);
    memset(&prefNull, 0, sizeof(prefNull));
    prefNull.frameInfo.contentChecksumFlag = 0;
    if (preferencesPtr == NULL) preferencesPtr = &prefNull;
    cctx->prefs = *preferencesPtr;

    {   int const ctxTypeID = (cctx->prefs.compressionLevel < LZ4HC_CLEVEL_MIN) ? CTX_FAST : CTX_HC;
        size_t const requiredSize = (ctxTypeID == CTX_FAST) ? sizeof(lz4_stream) : sizeof(lz4hc_ctx);
        size_t const allocatedSize = (cctx->lz4CtxAlloc == CTX_NONE) ? 0 :
                                     (cctx->lz4CtxAlloc == CTX_FAST) ? sizeof(lz4_stream) : sizeof(lz4hc_ctx);
        if (allocatedSize < requiredSize) {
            free(cctx->lz4CtxPtr);
            if (ctxTypeID == CTX_FAST) {
                cctx->lz4CtxPtr = malloc(sizeof(lz4_stream));
                if (cctx->lz4CtxPtr) lz4_initStream((lz4_stream*)cctx->lz4CtxPtr);
            } else {
                cctx->lz4CtxPtr = malloc(sizeof(lz4hc_ctx));
                if (cctx->lz4CtxPtr) lz4hc_initStream((lz4hc_ctx*)cctx->lz4CtxPtr);
            }
            if (cctx->lz4CtxPtr == NULL) return ERR(allocation_failed);
            cctx->lz4CtxAlloc = ctxTypeID;
            cctx->lz4CtxType = ctxTypeID;
        } else if (cctx->lz4CtxType != ctxTypeID) {
            if (ctxTypeID == CTX_FAST) {
                lz4_initStream((lz4_stream*)cctx->lz4CtxPtr);
            } else {
                lz4hc_initStream((lz4hc_ctx*)cctx->lz4CtxPtr);
                lz4hc_setCompressionLevel((lz4hc_ctx*)cctx->lz4CtxPtr, cctx->prefs.compressionLevel);
            }
            cctx->lz4CtxType = ctxTypeID;
        }
    }

    if (cctx->prefs.frameInfo.blockSizeID == 0) cctx->prefs.frameInfo.blockSizeID = 7;
    cctx->maxBlockSize = lz4f_getBlockSize(cctx->prefs.frameInfo.blockSizeID);

    {   size_t const requiredBuffSize = preferencesPtr->autoFlush ?
            ((cctx->prefs.frameInfo.blockMode == LZ4F_blockLinked) ? 64 KB : 0) :
            cctx->maxBlockSize + ((cctx->prefs.frameInfo.blockMode == LZ4F_blockLinked) ? 128 KB : 0);
        if (cctx->maxBufferSize < requiredBuffSize) {
            cctx->maxBufferSize = 0;
            free(cctx->tmpBuff);
            cctx->tmpBuff = (BYTE*)malloc(requiredBuffSize);
            if (cctx->tmpBuff == NULL) return ERR(allocation_failed);
            cctx->maxBufferSize = requiredBuffSize;
        }
    }
    cctx->tmpIn = cctx->tmpBuff;
    cctx->tmpInSize = 0;
    xxh32_reset(&cctx->xxh, 0);

    cctx->cdict = cdict;
    if (cctx->prefs.frameInfo.blockMode == LZ4F_blockLinked) {
        initStream(cctx->lz4CtxPtr, cdict, cctx->prefs.compressionLevel, LZ4F_blockLinked);
    }
    if (preferencesPtr->compressionLevel >= LZ4HC_CLEVEL_MIN) {
        lz4hc_favorDecSpeed((lz4hc_ctx*)cctx->lz4CtxPtr, preferencesPtr->favorDecSpeed);
    }

    wrLE32(dstPtr, LZ4F_MAGICNUMBER);
    dstPtr += 4;
    {   BYTE* const headerStart = dstPtr;
        *dstPtr++ = (BYTE)(((1 & 3) << 6)
            + ((cctx->prefs.frameInfo.blockMode & 1) << 5)
            + ((cctx->prefs.frameInfo.blockChecksumFlag & 1) << 4)
            + ((unsigned)(cctx->prefs.frameInfo.contentSize > 0) << 3)
            + ((cctx->prefs.frameInfo.contentChecksumFlag & 1) << 2)
            + (cctx->prefs.frameInfo.dictID > 0));
        *dstPtr++ = (BYTE)((cctx->prefs.frameInfo.blockSizeID & 7) << 4);
        if (cctx->prefs.frameInfo.contentSize) {
            wrLE64(dstPtr, cctx->prefs.frameInfo.contentSize);
            dstPtr += 8;
            cctx->totalInSize = 0;
        }
        if (cctx->prefs.frameInfo.dictID) {
            wrLE32(dstPtr, cctx->prefs.frameInfo.dictID);
            dstPtr += 4;
        }
        *dstPtr = headerChecksum(headerStart, (size_t)(dstPtr - headerStart));
        dstPtr++;
    }
    cctx->cStage = 1;
    return (size_t)(dstPtr - dstStart);
}

size_t lz4f_compressUpdate(lz4f_cctx* cctxPtr, void* dstBuffer, size_t dstCapacity,
                           const void* srcBuffer, size_t srcSize, int stableSrc)
{
    size_t const blockSize = cctxPtr->maxBlockSize;
    const BYTE* srcPtr = (const BYTE*)srcBuffer;
    const BYTE* const srcEnd = srcPtr + srcSize;
    BYTE* const dstStart = (BYTE*)dstBuffer;
    BYTE* dstPtr = dstStart;
    enum { notDone, fromTmpBuffer, fromSrcBuffer } lastBlockCompressed = notDone;
    compressFunc_t const compress = selectCompression(cctxPtr->prefs.frameInfo.blockMode, cctxPtr->prefs.compressionLevel);

    if (cctxPtr->cStage != 1) return ERR(compressionState_uninitialized);
    if (dstCapacity < compressBound_internal(srcSize, &(cctxPtr->prefs), cctxPtr->tmpInSize))
        return ERR(dstMaxSize_tooSmall);

    if (cctxPtr->tmpInSize > 0) {
        size_t const sizeToCopy = blockSize - cctxPtr->tmpInSize;
        if (sizeToCopy > srcSize) {
            memcpy(cctxPtr->tmpIn + cctxPtr->tmpInSize, srcBuffer, srcSize);
            srcPtr = srcEnd;
            cctxPtr->tmpInSize += srcSize;
        } else {
            lastBlockCompressed = fromTmpBuffer;
            memcpy(cctxPtr->tmpIn + cctxPtr->tmpInSize, srcBuffer, sizeToCopy);
            srcPtr += sizeToCopy;
            dstPtr += makeBlock(dstPtr, cctxPtr->tmpIn, blockSize, compress, cctxPtr->lz4CtxPtr,
                                cctxPtr->prefs.compressionLevel, cctxPtr->cdict, cctxPtr->prefs.frameInfo.blockChecksumFlag);
            if (cctxPtr->prefs.frameInfo.blockMode == LZ4F_blockLinked) cctxPtr->tmpIn += blockSize;
            cctxPtr->tmpInSize = 0;
        }
    }

    while ((size_t)(srcEnd - srcPtr) >= blockSize) {
        lastBlockCompressed = fromSrcBuffer;
        dstPtr += makeBlock(dstPtr, srcPtr, blockSize, compress, cctxPtr->lz4CtxPtr,
                            cctxPtr->prefs.compressionLevel, cctxPtr->cdict, cctxPtr->prefs.frameInfo.blockChecksumFlag);
        srcPtr += blockSize;
    }

    if ((cctxPtr->prefs.autoFlush) && (srcPtr < srcEnd)) {
        lastBlockCompressed = fromSrcBuffer;
        dstPtr += makeBlock(dstPtr, srcPtr, (size_t)(srcEnd - srcPtr), compress, cctxPtr->lz4CtxPtr,
                            cctxPtr->prefs.compressionLevel, cctxPtr->cdict, cctxPtr->prefs.frameInfo.blockChecksumFlag);
        srcPtr = srcEnd;
    }

    if ((cctxPtr->prefs.frameInfo.blockMode == LZ4F_blockLinked) && (lastBlockCompressed == fromSrcBuffer)) {
        if (stableSrc) {
            cctxPtr->tmpIn = cctxPtr->tmpBuff;
        } else {
            int const realDictSize = localSaveDict(cctxPtr);
            cctxPtr->tmpIn = cctxPtr->tmpBuff + realDictSize;
        }
    }

    if (!(cctxPtr->prefs.autoFlush)
        && (cctxPtr->tmpIn + blockSize) > (cctxPtr->tmpBuff + cctxPtr->maxBufferSize)) {
        int const realDictSize = localSaveDict(cctxPtr);
        cctxPtr->tmpIn = cctxPtr->tmpBuff + realDictSize;
    }

    if (srcPtr < srcEnd) {
        size_t const sizeToCopy = (size_t)(srcEnd - srcPtr);
        memcpy(cctxPtr->tmpIn, srcPtr, sizeToCopy);
        cctxPtr->tmpInSize = sizeToCopy;
    }

    if (cctxPtr->prefs.frameInfo.contentChecksumFlag)
        xxh32_update(&(cctxPtr->xxh), srcBuffer, srcSize);

    cctxPtr->totalInSize += srcSize;
    return (size_t)(dstPtr - dstStart);
}

size_t lz4f_flush(lz4f_cctx* cctxPtr, void* dstBuffer, size_t dstCapacity) {
    BYTE* const dstStart = (BYTE*)dstBuffer;
    BYTE* dstPtr = dstStart;
    compressFunc_t compress;

    if (cctxPtr->tmpInSize == 0) return 0;
    if (cctxPtr->cStage != 1) return ERR(compressionState_uninitialized);
    if (dstCapacity < (cctxPtr->tmpInSize + BHSize + BFSize)) return ERR(dstMaxSize_tooSmall);

    compress = selectCompression(cctxPtr->prefs.frameInfo.blockMode, cctxPtr->prefs.compressionLevel);
    dstPtr += makeBlock(dstPtr, cctxPtr->tmpIn, cctxPtr->tmpInSize, compress, cctxPtr->lz4CtxPtr,
                        cctxPtr->prefs.compressionLevel, cctxPtr->cdict, cctxPtr->prefs.frameInfo.blockChecksumFlag);
    if (cctxPtr->prefs.frameInfo.blockMode == LZ4F_blockLinked) cctxPtr->tmpIn += cctxPtr->tmpInSize;
    cctxPtr->tmpInSize = 0;

    if ((cctxPtr->tmpIn + cctxPtr->maxBlockSize) > (cctxPtr->tmpBuff + cctxPtr->maxBufferSize)) {
        int const realDictSize = localSaveDict(cctxPtr);
        cctxPtr->tmpIn = cctxPtr->tmpBuff + realDictSize;
    }
    return (size_t)(dstPtr - dstStart);
}

size_t lz4f_compressEnd(lz4f_cctx* cctxPtr, void* dstBuffer, size_t dstCapacity) {
    BYTE* const dstStart = (BYTE*)dstBuffer;
    BYTE* dstPtr = dstStart;
    size_t const flushSize = lz4f_flush(cctxPtr, dstBuffer, dstCapacity);
    if (lz4f_isError(flushSize)) return flushSize;
    dstPtr += flushSize;
    dstCapacity -= flushSize;
    if (dstCapacity < 4) return ERR(dstMaxSize_tooSmall);
    wrLE32(dstPtr, 0);
    dstPtr += 4;
    if (cctxPtr->prefs.frameInfo.contentChecksumFlag) {
        U32 const xxh = xxh32_digest(&(cctxPtr->xxh));
        if (dstCapacity < 8) return ERR(dstMaxSize_tooSmall);
        wrLE32(dstPtr, xxh);
        dstPtr += 4;
    }
    cctxPtr->cStage = 0;
    if (cctxPtr->prefs.frameInfo.contentSize) {
        if (cctxPtr->prefs.frameInfo.contentSize != cctxPtr->totalInSize)
            return ERR(frameSize_wrong);
    }
    return (size_t)(dstPtr - dstStart);
}

size_t lz4f_compressFrame_usingCDict(lz4f_cctx* cctx, void* dstBuffer, size_t dstCapacity,
                                     const void* srcBuffer, size_t srcSize,
                                     const lz4f_cdict* cdict, const lz4f_prefs* preferencesPtr)
{
    lz4f_prefs prefs;
    BYTE* const dstStart = (BYTE*)dstBuffer;
    BYTE* dstPtr = dstStart;
    BYTE* const dstEnd = dstStart + dstCapacity;

    if (preferencesPtr != NULL) prefs = *preferencesPtr;
    else memset(&prefs, 0, sizeof(prefs));
    if (prefs.frameInfo.contentSize != 0)
        prefs.frameInfo.contentSize = (U64)srcSize;

    prefs.frameInfo.blockSizeID = optimalBSID(prefs.frameInfo.blockSizeID, srcSize);
    prefs.autoFlush = 1;
    if (srcSize <= lz4f_getBlockSize(prefs.frameInfo.blockSizeID))
        prefs.frameInfo.blockMode = LZ4F_blockIndependent;

    if (dstCapacity < lz4f_compressFrameBound(srcSize, &prefs)) return ERR(dstMaxSize_tooSmall);

    {   size_t const headerSize = lz4f_compressBegin_usingCDict(cctx, dstBuffer, dstCapacity, cdict, &prefs);
        if (lz4f_isError(headerSize)) return headerSize;
        dstPtr += headerSize;
    }
    {   size_t const cSize = lz4f_compressUpdate(cctx, dstPtr, (size_t)(dstEnd - dstPtr), srcBuffer, srcSize, 1);
        if (lz4f_isError(cSize)) return cSize;
        dstPtr += cSize;
    }
    {   size_t const tailSize = lz4f_compressEnd(cctx, dstPtr, (size_t)(dstEnd - dstPtr));
        if (lz4f_isError(tailSize)) return tailSize;
        dstPtr += tailSize;
    }
    return (size_t)(dstPtr - dstStart);
}

/* ---------------- decompression ---------------- */
enum {
    dstage_getFrameHeader = 0, dstage_storeFrameHeader,
    dstage_init,
    dstage_getBlockHeader, dstage_storeBlockHeader,
    dstage_copyDirect, dstage_getBlockChecksum,
    dstage_getCBlock, dstage_storeCBlock,
    dstage_flushOut,
    dstage_getSuffix, dstage_storeSuffix,
    dstage_getSFrameSize, dstage_storeSFrameSize,
    dstage_skipSkippable
};

struct lz4f_dctx_s {
    lz4f_frameInfo frameInfo;
    int dStage;
    U64 frameRemainingSize;
    size_t maxBlockSize;
    size_t maxBufferSize;
    BYTE* tmpIn;
    size_t tmpInSize;
    size_t tmpInTarget;
    BYTE* tmpOut;
    size_t tmpOutSize;
    size_t tmpOutStart;
    xxh32_state xxh;
    xxh32_state blockChecksum;
    int skipChecksum;
    BYTE header[LZ4F_HEADER_SIZE_MAX];
    /* history management (own implementation) */
    const BYTE* userDict;
    size_t userDictSize;
    BYTE* hist;          /* 64 KB rolling history for linked blocks */
    size_t histSize;
};

lz4f_dctx* lz4f_createDCtx(void) {
    lz4f_dctx* d = (lz4f_dctx*)calloc(1, sizeof(lz4f_dctx));
    if (!d) return NULL;
    d->hist = (BYTE*)malloc(128 KB);
    if (!d->hist) { free(d); return NULL; }
    return d;
}

void lz4f_freeDCtx(lz4f_dctx* d) {
    if (!d) return;
    free(d->tmpIn);
    free(d->tmpOut);
    free(d->hist);
    free(d);
}

void lz4f_resetDCtx(lz4f_dctx* d) {
    d->dStage = dstage_getFrameHeader;
    d->userDict = NULL;
    d->userDictSize = 0;
    d->histSize = 0;
    d->skipChecksum = 0;
    d->frameRemainingSize = 0;
}

static void hist_append(lz4f_dctx* d, const BYTE* p, size_t n) {
    if (n >= 64 KB) {
        memcpy(d->hist, p + n - 64 KB, 64 KB);
        d->histSize = 64 KB;
        return;
    }
    if (d->histSize + n > 128 KB) {
        size_t keep = 64 KB - n;
        if (keep > d->histSize) keep = d->histSize;
        memmove(d->hist, d->hist + d->histSize - keep, keep);
        d->histSize = keep;
    }
    memcpy(d->hist + d->histSize, p, n);
    d->histSize += n;
}

static size_t decodeHeader(lz4f_dctx* dctx, const void* src, size_t srcSize) {
    unsigned blockMode, blockChecksumFlag, contentSizeFlag, contentChecksumFlag, dictIDFlag, blockSizeID;
    size_t frameHeaderSize;
    const BYTE* srcPtr = (const BYTE*)src;

    if (srcSize < minFHSize) return ERR(frameHeader_incomplete);
    memset(&(dctx->frameInfo), 0, sizeof(dctx->frameInfo));

    if ((rdLE32(srcPtr) & 0xFFFFFFF0U) == LZ4F_MAGIC_SKIPPABLE_START) {
        dctx->frameInfo.frameType = 1;
        if (src == (void*)(dctx->header)) {
            dctx->tmpInSize = srcSize;
            dctx->tmpInTarget = 8;
            dctx->dStage = dstage_storeSFrameSize;
            return srcSize;
        } else {
            dctx->dStage = dstage_getSFrameSize;
            return 4;
        }
    }
    if (rdLE32(srcPtr) != LZ4F_MAGICNUMBER) return ERR(frameType_unknown);
    dctx->frameInfo.frameType = 0;

    {   U32 const FLG = srcPtr[4];
        U32 const version = (FLG >> 6) & 3;
        blockChecksumFlag = (FLG >> 4) & 1;
        blockMode = (FLG >> 5) & 1;
        contentSizeFlag = (FLG >> 3) & 1;
        contentChecksumFlag = (FLG >> 2) & 1;
        dictIDFlag = FLG & 1;
        if (((FLG >> 1) & 1) != 0) return ERR(reservedFlag_set);
        if (version != 1) return ERR(headerVersion_wrong);
    }

    frameHeaderSize = minFHSize + (contentSizeFlag ? 8 : 0) + (dictIDFlag ? 4 : 0);

    if (srcSize < frameHeaderSize) {
        if (srcPtr != dctx->header) memcpy(dctx->header, srcPtr, srcSize);
        dctx->tmpInSize = srcSize;
        dctx->tmpInTarget = frameHeaderSize;
        dctx->dStage = dstage_storeFrameHeader;
        return srcSize;
    }

    {   U32 const BD = srcPtr[5];
        blockSizeID = (BD >> 4) & 7;
        if (((BD >> 7) & 1) != 0) return ERR(reservedFlag_set);
        if (blockSizeID < 4) return ERR(maxBlockSize_invalid);
        if (((BD >> 0) & 15) != 0) return ERR(reservedFlag_set);
    }

    {   BYTE const HC = headerChecksum(srcPtr + 4, frameHeaderSize - 5);
        if (HC != srcPtr[frameHeaderSize - 1]) return ERR(headerChecksum_invalid);
    }

    dctx->frameInfo.blockMode = (int)blockMode;
    dctx->frameInfo.blockChecksumFlag = (int)blockChecksumFlag;
    dctx->frameInfo.contentChecksumFlag = (int)contentChecksumFlag;
    dctx->frameInfo.blockSizeID = (int)blockSizeID;
    dctx->maxBlockSize = lz4f_getBlockSize((int)blockSizeID);
    if (contentSizeFlag)
        dctx->frameRemainingSize = dctx->frameInfo.contentSize = rdLE64(srcPtr + 6);
    if (dictIDFlag)
        dctx->frameInfo.dictID = rdLE32(srcPtr + frameHeaderSize - 5);

    dctx->dStage = dstage_init;
    return frameHeaderSize;
}

size_t lz4f_headerSize(const void* src, size_t srcSize) {
    if (src == NULL) return ERR(srcPtr_wrong);
    if (srcSize < 5) return ERR(frameHeader_incomplete);
    if ((rdLE32(src) & 0xFFFFFFF0U) == LZ4F_MAGIC_SKIPPABLE_START) return 8;
    if (rdLE32(src) != LZ4F_MAGICNUMBER) return ERR(frameType_unknown);
    {   BYTE const FLG = ((const BYTE*)src)[4];
        U32 const contentSizeFlag = (FLG >> 3) & 1;
        U32 const dictIDFlag = FLG & 1;
        return minFHSize + (contentSizeFlag ? 8 : 0) + (dictIDFlag ? 4 : 0);
    }
}

size_t lz4f_getFrameInfo(lz4f_dctx* dctx, lz4f_frameInfo* frameInfoPtr, const void* srcBuffer, size_t* srcSizePtr) {
    if (dctx->dStage > dstage_storeFrameHeader) {
        *srcSizePtr = 0;
        *frameInfoPtr = dctx->frameInfo;
        return BHSize;
    } else {
        if (dctx->dStage == dstage_storeFrameHeader) {
            *srcSizePtr = 0;
            return ERR(frameDecoding_alreadyStarted);
        } else {
            size_t const hSize = lz4f_headerSize(srcBuffer, *srcSizePtr);
            if (lz4f_isError(hSize)) { *srcSizePtr = 0; return hSize; }
            if (*srcSizePtr < hSize) { *srcSizePtr = 0; return ERR(frameHeader_incomplete); }
            {   size_t decodeResult = decodeHeader(dctx, srcBuffer, hSize);
                if (lz4f_isError(decodeResult)) {
                    *srcSizePtr = 0;
                } else {
                    *srcSizePtr = decodeResult;
                    decodeResult = BHSize;
                }
                *frameInfoPtr = dctx->frameInfo;
                return decodeResult;
            }
        }
    }
}

/* returns pointer+size of current dictionary for block decoding */
static void currentDict(lz4f_dctx* d, const char** dict, int* dictSize) {
    if (d->frameInfo.blockMode == LZ4F_blockLinked) {
        if (d->histSize) {
            size_t n = d->histSize > 64 KB ? 64 KB : d->histSize;
            *dict = (const char*)d->hist + d->histSize - n;
            *dictSize = (int)n;
            return;
        }
    }
    if (d->userDict && d->userDictSize) {
        size_t n = d->userDictSize > 64 KB ? 64 KB : d->userDictSize;
        *dict = (const char*)d->userDict + d->userDictSize - n;
        *dictSize = (int)n;
        return;
    }
    *dict = NULL;
    *dictSize = 0;
}

size_t lz4f_decompress_usingDict(lz4f_dctx* dctx, void* dstBuffer, size_t* dstSizePtr,
                                 const void* srcBuffer, size_t* srcSizePtr,
                                 const void* dict, size_t dictSize, int skipChecksums)
{
    const BYTE* const srcStart = (const BYTE*)srcBuffer;
    const BYTE* const srcEnd = srcStart + *srcSizePtr;
    const BYTE* srcPtr = srcStart;
    BYTE* const dstStart = (BYTE*)dstBuffer;
    BYTE* const dstEnd = dstStart ? dstStart + *dstSizePtr : NULL;
    BYTE* dstPtr = dstStart;
    const BYTE* selectedIn = NULL;
    unsigned doAnotherStage = 1;
    size_t nextSrcSizeHint = 1;

    if (dctx->dStage <= dstage_init) {
        dctx->userDict = (const BYTE*)dict;
        dctx->userDictSize = dictSize;
    }

    *srcSizePtr = 0;
    *dstSizePtr = 0;
    dctx->skipChecksum |= (skipChecksums != 0);

    while (doAnotherStage) {
        switch (dctx->dStage) {
        case dstage_getFrameHeader:
            if ((size_t)(srcEnd - srcPtr) >= maxFHSize) {
                size_t const hSize = decodeHeader(dctx, srcPtr, (size_t)(srcEnd - srcPtr));
                if (lz4f_isError(hSize)) return hSize;
                srcPtr += hSize;
                break;
            }
            dctx->tmpInSize = 0;
            if (srcEnd - srcPtr == 0) return minFHSize;
            dctx->tmpInTarget = minFHSize;
            dctx->dStage = dstage_storeFrameHeader;
            /* fall-through */

        case dstage_storeFrameHeader:
            {   size_t const sizeToCopy = MIN(dctx->tmpInTarget - dctx->tmpInSize, (size_t)(srcEnd - srcPtr));
                memcpy(dctx->header + dctx->tmpInSize, srcPtr, sizeToCopy);
                dctx->tmpInSize += sizeToCopy;
                srcPtr += sizeToCopy;
            }
            if (dctx->tmpInSize < dctx->tmpInTarget) {
                nextSrcSizeHint = (dctx->tmpInTarget - dctx->tmpInSize) + BHSize;
                doAnotherStage = 0;
                break;
            }
            {   size_t const r = decodeHeader(dctx, dctx->header, dctx->tmpInTarget);
                if (lz4f_isError(r)) return r;
            }
            break;

        case dstage_init:
            if (dctx->frameInfo.contentChecksumFlag) xxh32_reset(&(dctx->xxh), 0);
            {   size_t const bufferNeeded = dctx->maxBlockSize;
                if (bufferNeeded > dctx->maxBufferSize) {
                    dctx->maxBufferSize = 0;
                    free(dctx->tmpIn);
                    dctx->tmpIn = (BYTE*)malloc(dctx->maxBlockSize + BFSize);
                    if (dctx->tmpIn == NULL) return ERR(allocation_failed);
                    free(dctx->tmpOut);
                    dctx->tmpOut = (BYTE*)malloc(bufferNeeded);
                    if (dctx->tmpOut == NULL) return ERR(allocation_failed);
                    dctx->maxBufferSize = bufferNeeded;
                }
            }
            dctx->tmpInSize = 0;
            dctx->tmpInTarget = 0;
            dctx->tmpOutStart = 0;
            dctx->tmpOutSize = 0;
            dctx->histSize = 0;
            if (dctx->frameInfo.blockMode == LZ4F_blockLinked && dctx->userDict && dctx->userDictSize) {
                hist_append(dctx, dctx->userDict, dctx->userDictSize);
            }
            dctx->dStage = dstage_getBlockHeader;
            /* fall-through */

        case dstage_getBlockHeader:
            if ((size_t)(srcEnd - srcPtr) >= BHSize) {
                selectedIn = srcPtr;
                srcPtr += BHSize;
            } else {
                dctx->tmpInSize = 0;
                dctx->dStage = dstage_storeBlockHeader;
            }
            if (dctx->dStage == dstage_storeBlockHeader)
        case dstage_storeBlockHeader:
            {   size_t const remainingInput = (size_t)(srcEnd - srcPtr);
                size_t const wantedData = BHSize - dctx->tmpInSize;
                size_t const sizeToCopy = MIN(wantedData, remainingInput);
                memcpy(dctx->tmpIn + dctx->tmpInSize, srcPtr, sizeToCopy);
                srcPtr += sizeToCopy;
                dctx->tmpInSize += sizeToCopy;
                if (dctx->tmpInSize < BHSize) {
                    nextSrcSizeHint = BHSize - dctx->tmpInSize;
                    doAnotherStage = 0;
                    break;
                }
                selectedIn = dctx->tmpIn;
            }

            {   U32 const blockHeader = rdLE32(selectedIn);
                size_t const nextCBlockSize = blockHeader & 0x7FFFFFFFU;
                size_t const crcSize = (size_t)dctx->frameInfo.blockChecksumFlag * BFSize;
                if (blockHeader == 0) {
                    dctx->dStage = dstage_getSuffix;
                    break;
                }
                if (nextCBlockSize > dctx->maxBlockSize) return ERR(maxBlockSize_invalid);
                if (blockHeader & LZ4F_BLOCKUNCOMPRESSED_FLAG) {
                    dctx->tmpInTarget = nextCBlockSize;
                    if (dctx->frameInfo.blockChecksumFlag) xxh32_reset(&dctx->blockChecksum, 0);
                    dctx->dStage = dstage_copyDirect;
                    break;
                }
                dctx->tmpInTarget = nextCBlockSize + crcSize;
                dctx->dStage = dstage_getCBlock;
                if (dstPtr == dstEnd || srcPtr == srcEnd) {
                    nextSrcSizeHint = BHSize + nextCBlockSize + crcSize;
                    doAnotherStage = 0;
                }
                break;
            }

        case dstage_copyDirect:
            {   size_t sizeToCopy;
                if (dstPtr == NULL) {
                    sizeToCopy = 0;
                } else {
                    size_t const minBuffSize = MIN((size_t)(srcEnd - srcPtr), (size_t)(dstEnd - dstPtr));
                    sizeToCopy = MIN(dctx->tmpInTarget, minBuffSize);
                    memcpy(dstPtr, srcPtr, sizeToCopy);
                    if (!dctx->skipChecksum) {
                        if (dctx->frameInfo.blockChecksumFlag) xxh32_update(&dctx->blockChecksum, srcPtr, sizeToCopy);
                        if (dctx->frameInfo.contentChecksumFlag) xxh32_update(&dctx->xxh, srcPtr, sizeToCopy);
                    }
                    if (dctx->frameInfo.contentSize) dctx->frameRemainingSize -= sizeToCopy;
                    if (dctx->frameInfo.blockMode == LZ4F_blockLinked) hist_append(dctx, dstPtr, sizeToCopy);
                    srcPtr += sizeToCopy;
                    dstPtr += sizeToCopy;
                }
                if (sizeToCopy == dctx->tmpInTarget) {
                    if (dctx->frameInfo.blockChecksumFlag) {
                        dctx->tmpInSize = 0;
                        dctx->dStage = dstage_getBlockChecksum;
                    } else {
                        dctx->dStage = dstage_getBlockHeader;
                    }
                    break;
                }
                dctx->tmpInTarget -= sizeToCopy;
            }
            nextSrcSizeHint = dctx->tmpInTarget + (dctx->frameInfo.blockChecksumFlag ? BFSize : 0) + BHSize;
            doAnotherStage = 0;
            break;

        case dstage_getBlockChecksum:
            {   const void* crcSrc;
                if ((srcEnd - srcPtr >= 4) && (dctx->tmpInSize == 0)) {
                    crcSrc = srcPtr;
                    srcPtr += 4;
                } else {
                    size_t const stillToCopy = 4 - dctx->tmpInSize;
                    size_t const sizeToCopy = MIN(stillToCopy, (size_t)(srcEnd - srcPtr));
                    memcpy(dctx->header + dctx->tmpInSize, srcPtr, sizeToCopy);
                    dctx->tmpInSize += sizeToCopy;
                    srcPtr += sizeToCopy;
                    if (dctx->tmpInSize < 4) {
                        doAnotherStage = 0;
                        break;
                    }
                    crcSrc = dctx->header;
                }
                if (!dctx->skipChecksum) {
                    U32 const readCRC = rdLE32(crcSrc);
                    U32 const calcCRC = xxh32_digest(&dctx->blockChecksum);
                    if (readCRC != calcCRC) return ERR(blockChecksum_invalid);
                }
            }
            dctx->dStage = dstage_getBlockHeader;
            break;

        case dstage_getCBlock:
            if ((size_t)(srcEnd - srcPtr) < dctx->tmpInTarget) {
                dctx->tmpInSize = 0;
                dctx->dStage = dstage_storeCBlock;
                break;
            }
            selectedIn = srcPtr;
            srcPtr += dctx->tmpInTarget;

            if (0)
        case dstage_storeCBlock:
            {   size_t const wantedData = dctx->tmpInTarget - dctx->tmpInSize;
                size_t const inputLeft = (size_t)(srcEnd - srcPtr);
                size_t const sizeToCopy = MIN(wantedData, inputLeft);
                memcpy(dctx->tmpIn + dctx->tmpInSize, srcPtr, sizeToCopy);
                dctx->tmpInSize += sizeToCopy;
                srcPtr += sizeToCopy;
                if (dctx->tmpInSize < dctx->tmpInTarget) {
                    nextSrcSizeHint = (dctx->tmpInTarget - dctx->tmpInSize)
                                    + (dctx->frameInfo.blockChecksumFlag ? BFSize : 0)
                                    + BHSize;
                    doAnotherStage = 0;
                    break;
                }
                selectedIn = dctx->tmpIn;
            }

            if (dctx->frameInfo.blockChecksumFlag) {
                dctx->tmpInTarget -= 4;
                {   U32 const readBlockCrc = rdLE32(selectedIn + dctx->tmpInTarget);
                    U32 const calcBlockCrc = xxh32(selectedIn, dctx->tmpInTarget, 0);
                    if (readBlockCrc != calcBlockCrc) return ERR(blockChecksum_invalid);
                }
            }

            {   const char* dictp;
                int dsz;
                int decodedSize;
                currentDict(dctx, &dictp, &dsz);
                decodedSize = lz4_decompress_safe_usingDict((const char*)selectedIn, (char*)dctx->tmpOut,
                                                            (int)dctx->tmpInTarget, (int)dctx->maxBlockSize,
                                                            dictp, dsz);
                if (decodedSize < 0) return ERR(decompressionFailed);
                if (dctx->frameInfo.contentChecksumFlag && !dctx->skipChecksum)
                    xxh32_update(&(dctx->xxh), dctx->tmpOut, (size_t)decodedSize);
                if (dctx->frameInfo.contentSize)
                    dctx->frameRemainingSize -= (size_t)decodedSize;
                if (dctx->frameInfo.blockMode == LZ4F_blockLinked)
                    hist_append(dctx, dctx->tmpOut, (size_t)decodedSize);
                dctx->tmpOutSize = (size_t)decodedSize;
                dctx->tmpOutStart = 0;
                dctx->dStage = dstage_flushOut;
            }
            /* fall-through */

        case dstage_flushOut:
            if (dstPtr != NULL) {
                size_t const sizeToCopy = MIN(dctx->tmpOutSize - dctx->tmpOutStart, (size_t)(dstEnd - dstPtr));
                memcpy(dstPtr, dctx->tmpOut + dctx->tmpOutStart, sizeToCopy);
                dctx->tmpOutStart += sizeToCopy;
                dstPtr += sizeToCopy;
            }
            if (dctx->tmpOutStart == dctx->tmpOutSize) {
                dctx->dStage = dstage_getBlockHeader;
                break;
            }
            doAnotherStage = 0;
            nextSrcSizeHint = BHSize;
            break;

        case dstage_getSuffix:
            if (dctx->frameRemainingSize) return ERR(frameSize_wrong);
            if (!dctx->frameInfo.contentChecksumFlag) {
                nextSrcSizeHint = 0;
                lz4f_resetDCtx(dctx);
                doAnotherStage = 0;
                break;
            }
            if ((srcEnd - srcPtr) < 4) {
                dctx->tmpInSize = 0;
                dctx->dStage = dstage_storeSuffix;
            } else {
                selectedIn = srcPtr;
                srcPtr += 4;
            }

            if (dctx->dStage == dstage_storeSuffix)
        case dstage_storeSuffix:
            {   size_t const remainingInput = (size_t)(srcEnd - srcPtr);
                size_t const wantedData = 4 - dctx->tmpInSize;
                size_t const sizeToCopy = MIN(wantedData, remainingInput);
                memcpy(dctx->tmpIn + dctx->tmpInSize, srcPtr, sizeToCopy);
                srcPtr += sizeToCopy;
                dctx->tmpInSize += sizeToCopy;
                if (dctx->tmpInSize < 4) {
                    nextSrcSizeHint = 4 - dctx->tmpInSize;
                    doAnotherStage = 0;
                    break;
                }
                selectedIn = dctx->tmpIn;
            }

            if (!dctx->skipChecksum) {
                U32 const readCRC = rdLE32(selectedIn);
                U32 const resultCRC = xxh32_digest(&(dctx->xxh));
                if (readCRC != resultCRC) return ERR(contentChecksum_invalid);
            }
            nextSrcSizeHint = 0;
            lz4f_resetDCtx(dctx);
            doAnotherStage = 0;
            break;

        case dstage_getSFrameSize:
            if ((srcEnd - srcPtr) >= 4) {
                selectedIn = srcPtr;
                srcPtr += 4;
            } else {
                dctx->tmpInSize = 4;
                dctx->tmpInTarget = 8;
                dctx->dStage = dstage_storeSFrameSize;
            }

            if (dctx->dStage == dstage_storeSFrameSize)
        case dstage_storeSFrameSize:
            {   size_t const sizeToCopy = MIN(dctx->tmpInTarget - dctx->tmpInSize, (size_t)(srcEnd - srcPtr));
                memcpy(dctx->header + dctx->tmpInSize, srcPtr, sizeToCopy);
                srcPtr += sizeToCopy;
                dctx->tmpInSize += sizeToCopy;
                if (dctx->tmpInSize < dctx->tmpInTarget) {
                    nextSrcSizeHint = dctx->tmpInTarget - dctx->tmpInSize;
                    doAnotherStage = 0;
                    break;
                }
                selectedIn = dctx->header + 4;
            }

            {   size_t const SFrameSize = rdLE32(selectedIn);
                dctx->frameInfo.contentSize = SFrameSize;
                dctx->tmpInTarget = SFrameSize;
                dctx->dStage = dstage_skipSkippable;
                break;
            }

        case dstage_skipSkippable:
            {   size_t const skipSize = MIN(dctx->tmpInTarget, (size_t)(srcEnd - srcPtr));
                srcPtr += skipSize;
                dctx->tmpInTarget -= skipSize;
                doAnotherStage = 0;
                nextSrcSizeHint = dctx->tmpInTarget;
                if (nextSrcSizeHint) break;
                lz4f_resetDCtx(dctx);
                break;
            }
        }
    }

    *srcSizePtr = (size_t)(srcPtr - srcStart);
    *dstSizePtr = (size_t)(dstPtr - dstStart);
    return nextSrcSizeHint;
}
EOF
gcc -O2 -Wall -c lz4frame.c -o /tmp/lz4frame.o && echo ok"}

