    size_t chunk = 4<<20;
    fseek(f, 0, SEEK_END); size_t fsize = ftell(f); fseek(f, 0, SEEK_SET);
    char* buf = malloc(fsize + 1); fread(buf, 1, fsize, f);
    lz4f_prefs p; memset(&p, 0, sizeof(p));
    p.autoFlush = 1; p.compressionLevel = level; p.frameInfo.blockMode = indep; p.frameInfo.blockSizeID = bsid;
    p.frameInfo.contentChecksumFlag = 1;
    size_t dcap = lz4f_compressFrameBound(chunk, &p) + 64;
    char* dst = malloc(dcap);
    lz4f_cctx* c = lz4f_createCCtx();
    size_t pos = 0;
    size_t h = lz4f_compressBegin_usingCDict(c, dst, dcap, NULL, &p);
    fwrite(dst, 1, h, stdout);
    while (pos < fsize) {
        size_t n = fsize - pos; if (n > chunk) n = chunk;
        lz4f_cctx* cc = c;
        if (pos > 0) {
            if (fresh) cc = lz4f_createCCtx();
            size_t ps = pos < 65536 ? pos : 65536;
