#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "lz4frame.h"
extern int g_loadDictSlow;
/* usage: harness2 level bsid indep file slow freshctx -> chunked mode */
int main(int argc, char** argv) {
    int level = atoi(argv[1]); int bsid = atoi(argv[2]); int indep = atoi(argv[3]);
    g_loadDictSlow = atoi(argv[5]); int fresh = atoi(argv[6]);
    FILE* f = fopen(argv[4], "rb");
    size_t chunk = 4<<20;
    fseek(f, 0, SEEK_END); size_t fsize = ftell(f); fseek(f, 0, SEEK_SET);
    char* buf = malloc(fsize + 1); fread(buf, 1, fsize, f);
    lz4f_prefs p; memset(&p, 0, sizeof(p));
    p.autoFlush = 1; p.compressionLevel = level; p.frameInfo.blockMode = indep; p.frameInfo.blockSizeID = bsid;
    p.frameInfo.contentChecksumFlag = 1;
    size_t dcap = lz4f_compressFrameBound(chunk, &p) + 64;
    char* dst = malloc(dcap);
    lz4f_cctx* c = lz4f_createCCtx();
    size_t pos = 0;
    size_t h = lz4f_compressBegin_usingCDict(c, dst, dcap, NULL, &p);
    fwrite(dst, 1, h, stdout);
    while (pos < fsize) {
        size_t n = fsize - pos; if (n > chunk) n = chunk;
        lz4f_cctx* cc = c;
        if (pos > 0) {
            if (fresh) cc = lz4f_createCCtx();
            size_t ps = pos < 65536 ? pos : 65536;
            lz4f_prefs p2 = p; p2.frameInfo.contentChecksumFlag = 0;
            lz4f_compressBegin_usingDict(cc, dst, dcap, buf + pos - ps, ps, &p2);
        }
        size_t o = lz4f_compressUpdate(cc, dst, dcap, buf + pos, n, 1);
        fwrite(dst, 1, o, stdout);
        pos += n;
    }
    /* end mark + checksum */
    unsigned char e[8] = {0};
    unsigned x = xxh32(buf, fsize, 0);
    e[4]=x; e[5]=x>>8; e[6]=x>>16; e[7]=x>>24;
    fwrite(e, 1, 8, stdout);
    return 0;
}
