static void writeOut(FILE* f, const void* buf, size_t size) {
    if (size == 0) return;
    if (fwrite(buf, 1, size, f) != size) END_PROCESS(70, "Write error : cannot write decoded block");
}

static void writeLE32(void* p, U32 v) {
    BYTE* d = (BYTE*)p;
    d[0] = (BYTE)v; d[1] = (BYTE)(v >> 8); d[2] = (BYTE)(v >> 16); d[3] = (BYTE)(v >> 24);
}
static U32 readLE32(const void* s) {
    const BYTE* p = (const BYTE*)s;
    return (U32)p[0] | ((U32)p[1] << 8) | ((U32)p[2] << 16) | ((U32)p[3] << 24);
}

static int isSkippableMagicNumber(U32 magic) { return (magic & LZ4IO_SKIPPABLEMASK) == LZ4IO_SKIPPABLE0; }

/* ---------------- dictionary ---------------- */
static void* createDict(size_t* dictSize, const char* dictFilename) {
    size_t readSize;
    size_t dictEnd = 0;
    size_t dictLen = 0;
    size_t dictStart;
    size_t circularBufSize = LZ4_MAX_DICT_SIZE;
    char* circularBuf = (char*)malloc(circularBufSize);
    char* dictBuf;
    FILE* dictFile;

    if (!circularBuf) END_PROCESS(25, "Allocation error : not enough memory for circular buffer");
    if (!dictFilename) END_PROCESS(26, "Dictionary error : no filename provided");

    dictFile = openSrcFile(dictFilename);
    if (!dictFile) END_PROCESS(27, "Dictionary error : could not open dictionary file");

    if (strcmp(dictFilename, stdinmark)) {
        (void)fseeko(dictFile, -(off_t)LZ4_MAX_DICT_SIZE, SEEK_END);
    }

    do {
        readSize = fread(circularBuf + dictEnd, 1, circularBufSize - dictEnd, dictFile);
        dictEnd = (dictEnd + readSize) % circularBufSize;
        dictLen += readSize;
    } while (readSize > 0);

    if (dictLen > LZ4_MAX_DICT_SIZE) dictLen = LZ4_MAX_DICT_SIZE;
    *dictSize = dictLen;
    dictStart = (circularBufSize + dictEnd - dictLen) % circularBufSize;

    if (dictStart == 0) {
        dictBuf = circularBuf;
        circularBuf = NULL;
    } else {
        dictBuf = (char*)malloc(dictLen ? dictLen : 1);
        if (!dictBuf) END_PROCESS(28, "Allocation error : not enough memory");
        memcpy(dictBuf, circularBuf + dictStart, circularBufSize - dictStart);
        memcpy(dictBuf + circularBufSize - dictStart, circularBuf, dictLen - (circularBufSize - dictStart));
    }
    if (dictFile != stdin) fclose(dictFile);
    free(circularBuf);
    return dictBuf;
}

static lz4f_cdict* createCDict(const LZ4IO_prefs_t* io_prefs) {
    size_t dictionarySize;
    void* dictionaryBuffer;
    lz4f_cdict* cdict;
    if (!io_prefs->useDictionary) return NULL;
    dictionaryBuffer = createDict(&dictionarySize, io_prefs->dictionaryFilename);
    if (!dictionaryBuffer) END_PROCESS(29, "Dictionary error : could not create dictionary");
    cdict = lz4f_createCDict(dictionaryBuffer, dictionarySize);
    free(dictionaryBuffer);
    return cdict;
}

/* ---------------- legacy compression ---------------- */
static int legacy_fast_compress(const char* src, char* dst, int srcSize, int dstSize, int cLevel) {
    int const acceleration = (cLevel < 0) ? -cLevel : 0;
    return lz4_compress_fast(src, dst, srcSize, dstSize, acceleration);
}

static int compressFilename_Legacy_internal(ull* processed, const char* input_filename, const char* output_filename,
                                            int compressionlevel, const LZ4IO_prefs_t* prefs)
{
    typedef int (*compress_f)(const char* src, char* dst, int srcSize, int dstSize, int cLevel);
    compress_f const compressionFunction = (compressionlevel < 3) ? legacy_fast_compress : lz4hc_compress;
    ull filesize = 0;
    ull compressedfilesize = MAGICNUMBER_SIZE;
    char* in_buff;
    char* out_buff;
    const int outBuffSize = lz4_compressBound(LEGACY_BLOCKSIZE);
    FILE* const finput = openSrcFile(input_filename);
    FILE* foutput;

    *processed = 0;
    if (finput == NULL) return 20;
    foutput = openDstFile(output_filename, prefs);
    if (foutput == NULL) {
        if (finput != stdin) fclose(finput);
        return 20;
    }

    in_buff = (char*)malloc(LEGACY_BLOCKSIZE);
    out_buff = (char*)malloc((size_t)outBuffSize + 4);
    if (!in_buff || !out_buff) END_PROCESS(21, "Allocation error : not enough memory");

    writeLE32(out_buff, LEGACY_MAGICNUMBER);
    if (fwrite(out_buff, 1, MAGICNUMBER_SIZE, foutput) != MAGICNUMBER_SIZE)
        END_PROCESS(22, "Write error : cannot write header");

    while (1) {
        int outSize;
        size_t const inSize = fread(in_buff, 1, LEGACY_BLOCKSIZE, finput);
        if (inSize == 0) break;
        outSize = compressionFunction(in_buff, out_buff + 4, (int)inSize, outBuffSize, compressionlevel);
        compressedfilesize += (ull)outSize + 4;
        DISPLAYUPDATE(2, "\rRead : %u MiB   ==> %.2f%%   ",
                      (unsigned)(filesize >> 20), (double)compressedfilesize / (double)filesize * 100);
        filesize += inSize;
        writeLE32(out_buff, (unsigned)outSize);
        if (fwrite(out_buff, 1, (size_t)outSize + 4, foutput) != (size_t)(outSize + 4))
            END_PROCESS(24, "Write error : cannot write compressed block");
    }
    if (ferror(finput)) END_PROCESS(25, "Error while reading %s ", input_filename);

    DISPLAYLEVEL(2, "\r%79s\r", "");
    DISPLAYLEVEL(2, "Compressed %llu bytes into %llu bytes ==> %.2f%% \n",
                 filesize, compressedfilesize, (double)compressedfilesize / (double)(filesize + !filesize) * 100);

    free(in_buff);
    free(out_buff);
    if (finput != stdin) fclose(finput);
    if (foutput != stdout) fclose(foutput);

    if (strcmp(input_filename, stdinmark) && strcmp(output_filename, stdoutmark) && strcmp(output_filename, nulmark)) {
        struct stat st;
        if (UTIL_getFileStat(input_filename, &st)) UTIL_setFileStat(output_filename, &st);
    }
    if (prefs->removeSrcFile) {
        if (remove(input_filename))
            END_PROCESS(40, "Remove error : %s: %s", input_filename, strerror(errno));
    }
    *processed = filesize;
    return 0;
}

int LZ4IO_compressFilename_Legacy(const char* input_filename, const char* output_filename,
                                  int compressionlevel, const LZ4IO_prefs_t* prefs)
{
    U64 const timeStart = UTIL_getTimeNs();
    clock_t const cpuStart = clock();
    ull processed = 0;
    int const r = compressFilename_Legacy_internal(&processed, input_filename, output_filename, compressionlevel, prefs);
    finalTimeDisplay(timeStart, cpuStart, processed);
    return r;
}

int LZ4IO_compressMultipleFilenames_Legacy(const char** inFileNamesTable, int ifntSize, const char* suffix,
                                           int compressionLevel, const LZ4IO_prefs_t* prefs)
{
    int i;
    int missed_files = 0;
    size_t const suffixSize = strlen(suffix);
    U64 const timeStart = UTIL_getTimeNs();
    clock_t const cpuStart = clock();
    ull totalProcessed = 0;

    for (i = 0; i < ifntSize; i++) {
        ull processed = 0;
        if (!strcmp(suffix, stdoutmark)) {
            missed_files += compressFilename_Legacy_internal(&processed, inFileNamesTable[i], stdoutmark, compressionLevel, prefs) ? 1 : 0;
        } else {
            size_t const ifnSize = strlen(inFileNamesTable[i]);
            char* dstFileName = (char*)malloc(ifnSize + suffixSize + 1);
            if (!dstFileName) return ifntSize;
            strcpy(dstFileName, inFileNamesTable[i]);
            strcat(dstFileName, suffix);
            missed_files += compressFilename_Legacy_internal(&processed, inFileNamesTable[i], dstFileName, compressionLevel, prefs) ? 1 : 0;
            free(dstFileName);
        }
        totalProcessed += processed;
    }
    finalTimeDisplay(timeStart, cpuStart, totalProcessed);
    return missed_files;
}

/* ---------------- frame compression ---------------- */
typedef struct {
    BYTE* srcBuffer;      /* 64 KB prefix room + CHUNK_SIZE */
    size_t srcBufferSize;
    BYTE* dstBuffer;
    size_t dstBufferSize;
    lz4f_cctx* ctx;
    lz4f_cdict* cdict;
} cRess_t;

static lz4f_prefs makePrefs(const LZ4IO_prefs_t* io_prefs, int compressionLevel) {
    lz4f_prefs prefs;
    memset(&prefs, 0, sizeof(prefs));
    prefs.autoFlush = 1;
    prefs.compressionLevel = compressionLevel;
    prefs.frameInfo.blockMode = io_prefs->blockIndependence;
    prefs.frameInfo.blockSizeID = io_prefs->blockSizeId;
    prefs.frameInfo.blockChecksumFlag = io_prefs->blockChecksum;
    prefs.frameInfo.contentChecksumFlag = io_prefs->streamChecksum;
    prefs.favorDecSpeed = (int)io_prefs->favorDecSpeed;
    return prefs;
}

static cRess_t createCResources(const LZ4IO_prefs_t* prefs) {
    cRess_t ress;
    lz4f_prefs p;
    memset(&ress, 0, sizeof(ress));
    memset(&p, 0, sizeof(p));
    p.frameInfo.blockSizeID = 4;  /* smallest blocks => largest bound */
    p.frameInfo.blockChecksumFlag = 1;
    p.frameInfo.contentChecksumFlag = 1;
    p.autoFlush = 1;
    ress.ctx = lz4f_createCCtx();
    if (!ress.ctx) END_PROCESS(30, "Allocation error : can't create LZ4F context");
    ress.srcBufferSize = 64 KB + CHUNK_SIZE;
    ress.srcBuffer = (BYTE*)malloc(ress.srcBufferSize);
    ress.dstBufferSize = lz4f_compressFrameBound(CHUNK_SIZE, &p) + 1024;
    ress.dstBuffer = (BYTE*)malloc(ress.dstBufferSize);
    if (!ress.srcBuffer || !ress.dstBuffer) END_PROCESS(31, "Allocation error : can't allocate buffers");
    ress.cdict = createCDict(prefs);
    return ress;
}

static void freeCResources(cRess_t ress) {
    free(ress.srcBuffer);
    free(ress.dstBuffer);
    lz4f_freeCDict(ress.cdict);
    lz4f_freeCCtx(ress.ctx);
}

static size_t readFull(void* buf, size_t size, FILE* f) {
    return fread(buf, 1, size, f);
}

/* compress one chunk of a multi-chunk frame; returns size of blocks written into dst */
static size_t compressChunk(BYTE* dst, size_t dstCap, const BYTE* src, size_t srcSize,
                            const BYTE* prefix, size_t prefixSize,
                            const lz4f_cdict* cdict, const lz4f_prefs* prefs)
{
    lz4f_cctx* const cctx = lz4f_createCCtx();
    lz4f_prefs p = *prefs;
    BYTE hdr[LZ4F_HEADER_SIZE_MAX];
    size_t r;
    if (!cctx) END_PROCESS(33, "Allocation error : can't create compression context");
    p.frameInfo.contentSize = 0;
    p.frameInfo.contentChecksumFlag = 0;
    if (prefixSize > 0) r = lz4f_compressBegin_usingDict(cctx, hdr, sizeof(hdr), prefix, prefixSize, &p);
    else r = lz4f_compressBegin_usingCDict(cctx, hdr, sizeof(hdr), cdict, &p);
    if (lz4f_isError(r)) END_PROCESS(33, "File header generation failed : %s", lz4f_getErrorName(r));
    r = lz4f_compressUpdate(cctx, dst, dstCap, src, srcSize, 1);
    if (lz4f_isError(r)) END_PROCESS(35, "Compression failed : %s", lz4f_getErrorName(r));
    lz4f_freeCCtx(cctx);
    return r;
}

static int compressFilename_extRess(ull* inStreamSize, cRess_t* ress,
                                    const char* srcFileName, const char* dstFileName,
                                    int compressionLevel, const LZ4IO_prefs_t* io_prefs)
{
    ull filesize = 0;
    ull compressedfilesize = 0;
    FILE* dstFile;
    FILE* srcFile;
    BYTE* const chunkBuf = ress->srcBuffer + 64 KB;
    BYTE* const dstBuffer = ress->dstBuffer;
    size_t const dstBufferSize = ress->dstBufferSize;
    size_t readSize;
    lz4f_prefs prefs = makePrefs(io_prefs, compressionLevel);

    *inStreamSize = 0;
    srcFile = openSrcFile(srcFileName);
    if (srcFile == NULL) return 1;
    dstFile = openDstFile(dstFileName, io_prefs);
    if (dstFile == NULL) { if (srcFile != stdin) fclose(srcFile); return 1; }

    if (io_prefs->contentSizeFlag) {
        U64 const fileSize = UTIL_getOpenFileSize(srcFile);
        prefs.frameInfo.contentSize = fileSize;
        if (fileSize == 0)
            DISPLAYLEVEL(3, "Warning : cannot determine input content size \n");
    }

    readSize = readFull(chunkBuf, CHUNK_SIZE, srcFile);
    if (ferror(srcFile)) END_PROCESS(30, "Error reading %s ", srcFileName);

    if (readSize < CHUNK_SIZE) {
        size_t const cSize = lz4f_compressFrame_usingCDict(ress->ctx, dstBuffer, dstBufferSize, chunkBuf, readSize, ress->cdict, &prefs);
        if (lz4f_isError(cSize)) END_PROCESS(31, "Compression failed : %s", lz4f_getErrorName(cSize));
        filesize = readSize;
        compressedfilesize = cSize;
        DISPLAYUPDATE(2, "\rRead : %u MiB   ==> %.2f%%   ",
                      (unsigned)(filesize >> 20), (double)compressedfilesize / (double)(filesize + !filesize) * 100);
        if (fwrite(dstBuffer, 1, cSize, dstFile) != cSize)
            END_PROCESS(32, "Write error : failed writing single-block compressed frame");
    } else {
        xxh32_state xxh;
        int const linked = (prefs.frameInfo.blockMode == LZ4F_blockLinked);
        size_t prefixSize = 0;
        xxh32_reset(&xxh, 0);
        {   size_t const headerSize = lz4f_compressBegin_usingCDict(ress->ctx, dstBuffer, dstBufferSize, ress->cdict, &prefs);
            if (lz4f_isError(headerSize)) END_PROCESS(33, "File header generation failed : %s", lz4f_getErrorName(headerSize));
            if (fwrite(dstBuffer, 1, headerSize, dstFile) != headerSize)
                END_PROCESS(34, "Write error : cannot write header");
            compressedfilesize += headerSize;
        }
        while (readSize > 0) {
            size_t outSize;
            if (prefs.frameInfo.contentChecksumFlag) xxh32_update(&xxh, chunkBuf, readSize);
            outSize = compressChunk(dstBuffer, dstBufferSize, chunkBuf, readSize,
                                    chunkBuf - prefixSize, linked ? prefixSize : 0,
                                    ress->cdict, &prefs);
            compressedfilesize += outSize;
            DISPLAYUPDATE(2, "\rRead : %u MiB   ==> %.2f%%   ",
                          (unsigned)(filesize >> 20), (double)compressedfilesize / (double)filesize * 100);
            if (fwrite(dstBuffer, 1, outSize, dstFile) != outSize)
                END_PROCESS(36, "Write error : cannot write compressed block");
            filesize += readSize;
            /* keep last 64 KB as prefix for next chunk */
            {   size_t const keep = readSize < 64 KB ? readSize : 64 KB;
                memmove(chunkBuf - keep, chunkBuf + readSize - keep, keep);
                prefixSize = keep;
            }
            readSize = readFull(chunkBuf, CHUNK_SIZE, srcFile);
        }
        if (ferror(srcFile)) END_PROCESS(37, "Error reading %s ", srcFileName);
        {   BYTE tail[8];
            size_t endSize = 4;
            writeLE32(tail, 0);
            if (prefs.frameInfo.contentChecksumFlag) {
                writeLE32(tail + 4, xxh32_digest(&xxh));
                endSize = 8;
            }
            if (prefs.frameInfo.contentSize && prefs.frameInfo.contentSize != filesize)
                END_PROCESS(38, "End of frame error : %s", lz4f_getErrorName((size_t)-(ptrdiff_t)LZ4F_ERROR_frameSize_wrong));
            if (fwrite(tail, 1, endSize, dstFile) != endSize)
                END_PROCESS(39, "Write error : cannot write end of frame");
            compressedfilesize += endSize;
        }
    }

    if (srcFile != stdin) fclose(srcFile);
    if (dstFile != stdout) fclose(dstFile); else fflush(stdout);

    DISPLAYLEVEL(2, "\r%79s\r", "");
    DISPLAYLEVEL(2, "Compressed %llu bytes into %llu bytes ==> %.2f%%\n",
                 filesize, compressedfilesize, (double)compressedfilesize / (double)(filesize + !filesize) * 100);

    if (strcmp(srcFileName, stdinmark) && strcmp(dstFileName, stdoutmark) && strcmp(dstFileName, nulmark)) {
        struct stat statbuf;
        if (UTIL_getFileStat(srcFileName, &statbuf)) UTIL_setFileStat(dstFileName, &statbuf);
    }
    if (io_prefs->removeSrcFile) {
        if (remove(srcFileName))
            END_PROCESS(40, "Remove error : %s: %s", srcFileName, strerror(errno));
    }
    *inStreamSize = filesize;
    return 0;
}

int LZ4IO_compressFilename(const char* srcFileName, const char* dstFileName, int compressionLevel, const LZ4IO_prefs_t* prefs) {
    U64 const timeStart = UTIL_getTimeNs();
    clock_t const cpuStart = clock();
    cRess_t ress = createCResources(prefs);
    ull processed = 0;
    int const result = compressFilename_extRess(&processed, &ress, srcFileName, dstFileName, compressionLevel, prefs);
    freeCResources(ress);
    finalTimeDisplay(timeStart, cpuStart, processed);
    return result;
}

int LZ4IO_compressMultipleFilenames(const char** inFileNamesTable, int ifntSize, const char* suffix,
                                    int compressionLevel, const LZ4IO_prefs_t* prefs)
{
    int i;
    int missed_files = 0;
    size_t const suffixSize = strlen(suffix);
    cRess_t ress;
    U64 const timeStart = UTIL_getTimeNs();
    clock_t const cpuStart = clock();
    ull totalProcessed = 0;

    ress = createCResources(prefs);
    for (i = 0; i < ifntSize; i++) {
        ull processed = 0;
        size_t const ifnSize = strlen(inFileNamesTable[i]);
        if (!strcmp(suffix, stdoutmark)) {
            missed_files += compressFilename_extRess(&processed, &ress, inFileNamesTable[i], stdoutmark, compressionLevel, prefs);
            totalProcessed += processed;
            continue;
        }
        {   char* const dstFileName = (char*)malloc(ifnSize + suffixSize + 1);
            if (dstFileName == NULL) { freeCResources(ress); return ifntSize; }
            strcpy(dstFileName, inFileNamesTable[i]);
            strcat(dstFileName, suffix);
            missed_files += compressFilename_extRess(&processed, &ress, inFileNamesTable[i], dstFileName, compressionLevel, prefs);
            totalProcessed += processed;
            free(dstFileName);
        }
    }
    freeCResources(ress);
    finalTimeDisplay(timeStart, cpuStart, totalProcessed);
    return missed_files;
}

/* ---------------- decompression ---------------- */
typedef struct {
    BYTE* srcBuffer;
    size_t srcBufferSize;
    BYTE* dstBuffer;
    size_t dstBufferSize;
    FILE* dstFile;
    lz4f_dctx* dCtx;
    void* dictBuffer;
    size_t dictBufferSize;
} dRess_t;

#define ENDOFSTREAM ((ull)-1)
#define DECODING_ERROR ((ull)-2)

static U32 g_magicRead = 0;

static dRess_t createDResources(const LZ4IO_prefs_t* prefs) {
    dRess_t ress;
    memset(&ress, 0, sizeof(ress));
    ress.dCtx = lz4f_createDCtx();
    if (!ress.dCtx) END_PROCESS(60, "Can't create LZ4F context");
    ress.srcBufferSize = DEC_IN_SIZE;
    ress.srcBuffer = (BYTE*)malloc(ress.srcBufferSize);
    ress.dstBufferSize = DEC_OUT_SIZE;
    ress.dstBuffer = (BYTE*)malloc(ress.dstBufferSize);
    if (!ress.srcBuffer || !ress.dstBuffer) END_PROCESS(61, "Allocation error : not enough memory");
    if (prefs->useDictionary) {
        ress.dictBuffer = createDict(&ress.dictBufferSize, prefs->dictionaryFilename);
        if (!ress.dictBuffer) END_PROCESS(25, "Dictionary error : could not create dictionary");
    }
    ress.dstFile = NULL;
    return ress;
}

static void freeDResources(dRess_t ress) {
    lz4f_freeDCtx(ress.dCtx);
    free(ress.srcBuffer);
    free(ress.dstBuffer);
    free(ress.dictBuffer);
}

static ull decompressLZ4F(dRess_t* ress, FILE* const srcFile, FILE* const dstFile, const LZ4IO_prefs_t* const prefs) {
    ull filesize = 0;
    size_t nextToLoad;
    int const skipChecksums = ((prefs->blockChecksum == 0) && (prefs->streamChecksum == 0));

    lz4f_resetDCtx(ress->dCtx);
    {   size_t inSize = MAGICNUMBER_SIZE;
        size_t outSize = 0;
        BYTE magic[4];
        writeLE32(magic, LZ4IO_MAGICNUMBER);
        nextToLoad = lz4f_decompress_usingDict(ress->dCtx, ress->dstBuffer, &outSize, magic, &inSize,
                                               ress->dictBuffer, ress->dictBufferSize, skipChecksums);
        if (lz4f_isError(nextToLoad))
            END_PROCESS(62, "Header error : %s", lz4f_getErrorName(nextToLoad));
    }

    for (;;) {
        size_t const readSize = fread(ress->srcBuffer, 1, ress->srcBufferSize, srcFile);
        size_t pos = 0;
        size_t decodedBytes = ress->dstBufferSize;
        if (readSize == 0) break;
        while ((pos < readSize) || (decodedBytes == ress->dstBufferSize)) {
            size_t remaining = readSize - pos;
            decodedBytes = ress->dstBufferSize;
            nextToLoad = lz4f_decompress_usingDict(ress->dCtx, ress->dstBuffer, &decodedBytes,
                                                   ress->srcBuffer + pos, &remaining,
                                                   ress->dictBuffer, ress->dictBufferSize, skipChecksums);
            if (lz4f_isError(nextToLoad))
                END_PROCESS(34, "Decompression error : %s", lz4f_getErrorName(nextToLoad));
            pos += remaining;
            if (decodedBytes) {
                writeOut(dstFile, ress->dstBuffer, decodedBytes);
                filesize += decodedBytes;
            }
            DISPLAYUPDATE(2, "\rDecompressed : %u MiB  ", (unsigned)(filesize >> 20));
            if (remaining == 0 && decodedBytes == 0) break;
        }
    }
    if (ferror(srcFile)) END_PROCESS(67, "Read error");
    if (nextToLoad != 0) END_PROCESS(26, "LZ4F frame decoding could not complete: invalid frame");
    return filesize;
}

static ull decodeLegacyStream(FILE* finput, FILE* foutput, const LZ4IO_prefs_t* prefs) {
    ull streamSize = 0;
    char* const in_buff = (char*)malloc((size_t)LZ4_COMPRESSBOUND(LEGACY_BLOCKSIZE));
    char* const out_buff = (char*)malloc(LEGACY_BLOCKSIZE);
    (void)prefs;
    if (!in_buff || !out_buff) END_PROCESS(60, "Allocation error : not enough memory");

    while (1) {
        unsigned int blockSize;
        {   size_t const sizeCheck = fread(in_buff, 1, LZ4IO_LEGACY_BLOCK_HEADER_SIZE, finput);
            if (sizeCheck == 0) break;
            if (sizeCheck != LZ4IO_LEGACY_BLOCK_HEADER_SIZE)
                END_PROCESS(61, "Error: cannot read block size in Legacy format");
        }
        blockSize = readLE32(in_buff);
        if (blockSize > LZ4_COMPRESSBOUND(LEGACY_BLOCKSIZE)) {
            g_magicRead = blockSize;
            break;
        }
        {   size_t const sizeCheck = fread(in_buff, 1, blockSize, finput);
            if (sizeCheck != blockSize)
                END_PROCESS(63, "Read error : cannot access compressed block !");
        }
        {   int const decodeSize = lz4_decompress_safe_usingDict(in_buff, out_buff, (int)blockSize, LEGACY_BLOCKSIZE, NULL, 0);
            if (decodeSize < 0) END_PROCESS(64, "Decoding Failed ! Corrupted input detected !");
            streamSize += (ull)decodeSize;
            writeOut(foutput, out_buff, (size_t)decodeSize);
            DISPLAYUPDATE(2, "\rDecompressed : %u MiB  ", (unsigned)(streamSize >> 20));
        }
    }
    if (ferror(finput)) END_PROCESS(65, "Read error : ferror");
    free(in_buff);
    free(out_buff);
    return streamSize;
}

static ull passThrough(FILE* finput, FILE* foutput, unsigned char MNstore[MAGICNUMBER_SIZE]) {
    size_t buffer[64 KB / sizeof(size_t)];
    size_t readBytes = 1;
    ull total = MAGICNUMBER_SIZE;
    if (fwrite(MNstore, 1, MAGICNUMBER_SIZE, foutput) != MAGICNUMBER_SIZE)
        END_PROCESS(50, "Pass-through write error");
    while (readBytes) {
        readBytes = fread(buffer, 1, sizeof(buffer), finput);
        total += readBytes;
        writeOut(foutput, buffer, readBytes);
    }
    if (ferror(finput)) END_PROCESS(51, "Read Error");
    return total;
}

static int skipStream(FILE* f, unsigned offset) {
    char buf[16 KB];
    while (offset > 0) {
        size_t const tr = offset < sizeof(buf) ? offset : sizeof(buf);
        size_t const r = fread(buf, 1, tr, f);
        if (r != tr) return 1;
        offset -= (unsigned)tr;
    }
    return 0;
}

static int fseek_u32(FILE* fp, unsigned offset, int where) {
    const unsigned stepMax = 1U << 30;
    int errorNb = 0;
    if (where != SEEK_CUR) return -1;
    while (offset > 0) {
        unsigned s = offset;
        if (s > stepMax) s = stepMax;
        errorNb = fseeko(fp, (off_t)s, SEEK_CUR);
        if (errorNb == 0) { offset -= s; continue; }
        errorNb = skipStream(fp, offset);
        offset = 0;
    }
    return errorNb;
}

static unsigned g_nbFrames = 0;

static ull selectDecoder(dRess_t* ress, FILE* finput, FILE* foutput, const LZ4IO_prefs_t* const prefs) {
    unsigned char MNstore[MAGICNUMBER_SIZE];
    unsigned magicNumber;

    g_nbFrames++;
    if (g_magicRead) {
        magicNumber = g_magicRead;
        g_magicRead = 0;
    } else {
        size_t const nbReadBytes = fread(MNstore, 1, MAGICNUMBER_SIZE, finput);
        if (nbReadBytes == 0) { g_nbFrames = 0; return ENDOFSTREAM; }
        if (nbReadBytes != MAGICNUMBER_SIZE)
            END_PROCESS(40, "Unrecognized header : Magic Number unreadable");
        magicNumber = readLE32(MNstore);
    }
    if (isSkippableMagicNumber(magicNumber)) magicNumber = LZ4IO_SKIPPABLE0;

    switch (magicNumber) {
    case LZ4IO_MAGICNUMBER:
        return decompressLZ4F(ress, finput, foutput, prefs);
    case LEGACY_MAGICNUMBER:
        DISPLAYLEVEL(4, "Detected : Legacy format \n");
        return decodeLegacyStream(finput, foutput, prefs);
    case LZ4IO_SKIPPABLE0:
        DISPLAYLEVEL(4, "Skipping detected skippable area \n");
        {   size_t const nbReadBytes = fread(MNstore, 1, 4, finput);
            if (nbReadBytes != 4)
                END_PROCESS(42, "Stream error : skippable size unreadable");
        }
        {   unsigned const size = readLE32(MNstore);
            int const errorNb = fseek_u32(finput, size, SEEK_CUR);
            if (errorNb != 0)
                END_PROCESS(43, "Stream error : cannot skip skippable area");
        }
        return 0;
    default:
        if (g_nbFrames == 1) {
            if (!prefs->testMode && prefs->overwrite && prefs->passThrough) {
                g_nbFrames = 0;
                return passThrough(finput, foutput, MNstore);
            }
            END_PROCESS(44, "Unrecognized header : file cannot be decoded");
        }
        {   long int const position = ftell(finput);
            DISPLAYLEVEL(2, "Stream followed by undecodable data ");
            if (position != -1L)
                DISPLAYLEVEL(2, "at position %i ", (int)position);
            DISPLAYLEVEL(2, "\n");
        }
        return DECODING_ERROR;
    }
}

static int decompressSrcFile(ull* processed, dRess_t* ress, const char* input_filename, const char* output_filename,
                             const LZ4IO_prefs_t* const prefs)
{
    FILE* const foutput = ress->dstFile;
    ull filesize = 0;
    int result = 0;
    FILE* const finput = openSrcFile(input_filename);
    (void)output_filename;
    *processed = 0;
    if (finput == NULL) return 1;

    for (;;) {
        ull const decodedSize = selectDecoder(ress, finput, foutput, prefs);
        if (decodedSize == ENDOFSTREAM) break;
        if (decodedSize == DECODING_ERROR) { result = 1; break; }
        filesize += decodedSize;
    }

    if (finput != stdin) fclose(finput);
    if (prefs->removeSrcFile) {
        if (remove(input_filename))
            END_PROCESS(45, "Remove error : %s: %s", input_filename, strerror(errno));
    }

    DISPLAYLEVEL(2, "\r%79s\r", "");
    DISPLAYLEVEL(2, "%-30.30s : decoded %llu bytes \n", input_filename, filesize);
    *processed = filesize;
    return result;
}

static int decompressDstFile(ull* processed, dRess_t* ress, const char* input_filename, const char* output_filename,
                             const LZ4IO_prefs_t* const prefs)
{
    int result;
    struct stat statbuf;
    int stat_result = 0;
    FILE* const foutput = openDstFile(output_filename, prefs);
    *processed = 0;
    if (foutput == NULL) return 1;

    if (strcmp(input_filename, stdinmark) && UTIL_getFileStat(input_filename, &statbuf))
        stat_result = 1;

    ress->dstFile = foutput;
    result = decompressSrcFile(processed, ress, input_filename, output_filename, prefs);

    if (foutput != stdout) fclose(foutput); else fflush(stdout);

    if (stat_result != 0 && strcmp(output_filename, stdoutmark) && strcmp(output_filename, nulmark)) {
        UTIL_setFileStat(output_filename, &statbuf);
    }
    return result;
}

int LZ4IO_decompressFilename(const char* input_filename, const char* output_filename, const LZ4IO_prefs_t* prefs) {
    U64 const timeStart = UTIL_getTimeNs();
    clock_t const cpuStart = clock();
    dRess_t ress = createDResources(prefs);
    ull processed = 0;
    int const status = decompressDstFile(&processed, &ress, input_filename, output_filename, prefs);
    if (status) finalTimeDisplay(timeStart, cpuStart, processed);
    freeDResources(ress);
    return status;
}

int LZ4IO_decompressMultipleFilenames(const char** inFileNamesTable, int ifntSize, const char* suffix,
                                      const LZ4IO_prefs_t* prefs)
{
    int i;
    int skippedFiles = 0;
    int missingFiles = 0;
    size_t const suffixSize = strlen(suffix);
    dRess_t ress;
    U64 const timeStart = UTIL_getTimeNs();
    clock_t const cpuStart = clock();
    ull totalProcessed = 0;

    ress = createDResources(prefs);
    if (prefs->blockChecksum == 0 && prefs->streamChecksum == 0) {
        DISPLAYLEVEL(4, "disabling checksum validation during decoding \n");
    }
    ress.dstFile = openDstFile(stdoutmark, prefs);

    for (i = 0; i < ifntSize; i++) {
        ull processed = 0;
        size_t const ifnSize = strlen(inFileNamesTable[i]);
        const char* const suffixPtr = inFileNamesTable[i] + ifnSize - suffixSize;
        if (!strcmp(suffix, stdoutmark)) {
            missingFiles += decompressSrcFile(&processed, &ress, inFileNamesTable[i], stdoutmark, prefs);
            totalProcessed += processed;
            continue;
        }
        if (!strcmp(suffix, nulmark)) {
            missingFiles += decompressSrcFile(&processed, &ress, inFileNamesTable[i], nulmark, prefs);
            totalProcessed += processed;
            continue;
        }
        if (ifnSize <= suffixSize || strcmp(suffixPtr, suffix) != 0) {
            DISPLAYLEVEL(1, "File extension doesn't match expected LZ4_EXTENSION (%4s); will not process file: %s\n", suffix, inFileNamesTable[i]);
            skippedFiles++;
            continue;
        }
        {   char* const outFileName = (char*)malloc(ifnSize - suffixSize + 1);
            if (outFileName == NULL) END_PROCESS(71, "Memory allocation error");
            memcpy(outFileName, inFileNamesTable[i], ifnSize - suffixSize);
            outFileName[ifnSize - suffixSize] = '\0';
            missingFiles += decompressDstFile(&processed, &ress, inFileNamesTable[i], outFileName, prefs);
            totalProcessed += processed;
            free(outFileName);
        }
    }
    fflush(stdout);
    freeDResources(ress);
    finalTimeDisplay(timeStart, cpuStart, totalProcessed);
    return missingFiles + skippedFiles;
}

/* ---------------- --list ---------------- */
typedef enum { lz4Frame = 0, legacyFrame, skippableFrame } frameType_t;
static const char* frameTypeNames[] = { "LZ4Frame", "LegacyFrame", "SkippableFrame" };

typedef struct {
    lz4f_frameInfo lz4FrameInfo;
    frameType_t frameType;
} frameInfo_t;

typedef struct {
    frameInfo_t frameSummary;
    unsigned short eqFrameTypes;
    unsigned short eqBlockTypes;
    unsigned short allContentSize;
    ull frameCount;
    ull fileSize;
    const char* fileName;
} cFileInfo_t;

typedef enum { LZ4IO_LZ4F_OK, LZ4IO_format_not_known, LZ4IO_not_a_file } infoResult;

static const char* blockTypeID(int sizeID, int blockMode, char buffer[4]) {
    buffer[0] = 'B';
    buffer[1] = (char)(sizeID + '0');
    buffer[2] = (blockMode == LZ4F_blockIndependent) ? 'I' : 'D';
    buffer[3] = 0;
    return buffer;
}

static const char* toHuman(long double size, char* buf) {
    const char units[] = { "\0KMGTPEZY" };
    size_t i = 0;
    for (; size >= 1024; i++) size /= 1024;
    sprintf(buf, "%.2Lf%c", size, units[i]);
    return buf;
}

static const char* baseName(const char* input_filename) {
    const char* b = strrchr(input_filename, '/');
    if (!b) return input_filename;
    return b + 1;
}

#define legacyFrameUndecodable (0ULL)

static ull skipBlocksData(FILE* finput, int blockChecksumFlag, int contentChecksumFlag) {
    unsigned char blockInfo[LZ4F_BLOCK_HEADER_SIZE];
    ull totalBlocksSize = 0;
    for (;;) {
        if (!fread(blockInfo, 1, LZ4F_BLOCK_HEADER_SIZE, finput)) {
            if (feof(finput)) return totalBlocksSize;
            return 0;
        }
        totalBlocksSize += LZ4F_BLOCK_HEADER_SIZE;
        {   const unsigned long nextCBlockSize = readLE32(&blockInfo) & 0x7FFFFFFFU;
            const unsigned long nextBlock = nextCBlockSize + (unsigned long)(blockChecksumFlag * LZ4F_BLOCK_CHECKSUM_SIZE);
            if (nextCBlockSize == 0) {
                if (contentChecksumFlag) {
                    if (fseeko(finput, LZ4F_CONTENT_CHECKSUM_SIZE, SEEK_CUR) != 0) return 0;
                    totalBlocksSize += LZ4F_CONTENT_CHECKSUM_SIZE;
                }
                break;
            }
            totalBlocksSize += nextBlock;
            if (fseeko(finput, (off_t)nextBlock, SEEK_CUR) != 0) return 0;
        }
    }
    return totalBlocksSize;
}

static ull skipLegacyBlocksData(FILE* finput) {
    unsigned char blockInfo[LZ4IO_LEGACY_BLOCK_HEADER_SIZE];
    ull totalBlocksSize = 0;
    for (;;) {
        size_t const bhs = fread(blockInfo, 1, LZ4IO_LEGACY_BLOCK_HEADER_SIZE, finput);
        if (bhs == 0) break;
        if (bhs != LZ4IO_LEGACY_BLOCK_HEADER_SIZE) return legacyFrameUndecodable;
        {   const unsigned int nextCBlockSize = readLE32(&blockInfo);
            if (nextCBlockSize == LEGACY_MAGICNUMBER || nextCBlockSize == LZ4IO_MAGICNUMBER || isSkippableMagicNumber(nextCBlockSize)) {
                if (fseeko(finput, -LZ4IO_LEGACY_BLOCK_HEADER_SIZE, SEEK_CUR) != 0)
                    END_PROCESS(37, "impossible to skip backward");
                break;
            }
            if (nextCBlockSize > LZ4IO_LEGACY_BLOCK_SIZE_MAX) {
                DISPLAYLEVEL(4, "Error : block in legacy frame is too large \n");
                return legacyFrameUndecodable;
            }
            totalBlocksSize += LZ4IO_LEGACY_BLOCK_HEADER_SIZE + nextCBlockSize;
            if (fseeko(finput, (off_t)nextCBlockSize, SEEK_CUR) != 0) return legacyFrameUndecodable;
        }
    }
    return totalBlocksSize;
}

#define DISPLAYOUTLEVEL(l, ...) do { if (g_displayLevel >= (l)) { DISPLAYOUT(__VA_ARGS__); } } while (0)

static infoResult getCompressedFileInfo(cFileInfo_t* cfinfo, const char* input_filename) {
    infoResult result = LZ4IO_format_not_known;
    unsigned char buffer[LZ4F_HEADER_SIZE_MAX];
    FILE* const finput = openSrcFile(input_filename);

    if (finput == NULL) return LZ4IO_not_a_file;
    cfinfo->fileSize = UTIL_getOpenFileSize(finput);

    while (!feof(finput)) {
        frameInfo_t frameInfo;
        unsigned magicNumber;
        memset(&frameInfo, 0, sizeof(frameInfo));
        frameInfo.frameType = lz4Frame;
        {   size_t const nbReadBytes = fread(buffer, 1, MAGICNUMBER_SIZE, finput);
            if (nbReadBytes == 0) break;
            result = LZ4IO_format_not_known;
            if (nbReadBytes != MAGICNUMBER_SIZE)
                END_PROCESS(40, "Unrecognized header : Magic Number unreadable");
        }
        magicNumber = readLE32(buffer);
        if (isSkippableMagicNumber(magicNumber)) magicNumber = LZ4IO_SKIPPABLE0;

        switch (magicNumber) {
        case LZ4IO_MAGICNUMBER:
            if (cfinfo->frameSummary.frameType != lz4Frame) cfinfo->eqFrameTypes = 0;
            {   const size_t readBytes = fread(buffer + MAGICNUMBER_SIZE, 1, LZ4F_HEADER_SIZE_MIN - MAGICNUMBER_SIZE, finput);
                if (!readBytes || ferror(finput)) END_PROCESS(71, "Error reading %s", input_filename);
            }
            {   size_t hSize = lz4f_headerSize(&buffer, LZ4F_HEADER_SIZE_MIN);
                if (lz4f_isError(hSize)) break;
                if (hSize > (LZ4F_HEADER_SIZE_MIN + MAGICNUMBER_SIZE)) {
                    const size_t readBytes = fread(buffer + LZ4F_HEADER_SIZE_MIN, 1, hSize - LZ4F_HEADER_SIZE_MIN, finput);
                    if (!readBytes || ferror(finput)) END_PROCESS(72, "Error reading %s", input_filename);
                }
                {   lz4f_dctx* dctx = lz4f_createDCtx();
                    if (!dctx) break;
                    {   unsigned const frameInfoError = lz4f_isError(lz4f_getFrameInfo(dctx, &frameInfo.lz4FrameInfo, buffer, &hSize));
                        lz4f_freeDCtx(dctx);
                        if (frameInfoError) break;
                        if ((cfinfo->frameSummary.lz4FrameInfo.blockSizeID != frameInfo.lz4FrameInfo.blockSizeID ||
                             cfinfo->frameSummary.lz4FrameInfo.blockMode != frameInfo.lz4FrameInfo.blockMode)
                            && cfinfo->frameCount != 0)
                            cfinfo->eqBlockTypes = 0;
                        {   const ull totalBlocksSize = skipBlocksData(finput,
                                    frameInfo.lz4FrameInfo.blockChecksumFlag,
                                    frameInfo.lz4FrameInfo.contentChecksumFlag);
                            if (totalBlocksSize) {
                                char bTypeBuffer[5];
                                blockTypeID(frameInfo.lz4FrameInfo.blockSizeID, frameInfo.lz4FrameInfo.blockMode, bTypeBuffer);
                                DISPLAYOUTLEVEL(3, "    %6llu %14s %5s %8s",
                                             cfinfo->frameCount + 1,
                                             frameTypeNames[frameInfo.frameType],
                                             bTypeBuffer,
                                             frameInfo.lz4FrameInfo.contentChecksumFlag ? "XXH32" : "-");
                                if (frameInfo.lz4FrameInfo.contentSize) {
                                    double const ratio = (double)(totalBlocksSize + hSize) / (double)frameInfo.lz4FrameInfo.contentSize * 100;
                                    DISPLAYOUTLEVEL(3, " %20llu %20llu %9.2f%%\n",
                                                 totalBlocksSize + hSize,
                                                 frameInfo.lz4FrameInfo.contentSize,
                                                 ratio);
                                    frameInfo.lz4FrameInfo.contentSize += cfinfo->frameSummary.lz4FrameInfo.contentSize;
                                } else {
                                    DISPLAYOUTLEVEL(3, " %20llu %20s %9s \n", totalBlocksSize + hSize, "-", "-");
                                    cfinfo->allContentSize = 0;
                                }
                                result = LZ4IO_LZ4F_OK;
                            }
                        }
                    }
                }
            }
            break;
        case LEGACY_MAGICNUMBER:
            frameInfo.frameType = legacyFrame;
            if (cfinfo->frameSummary.frameType != legacyFrame && cfinfo->frameCount != 0) cfinfo->eqFrameTypes = 0;
            cfinfo->eqBlockTypes = 0;
            cfinfo->allContentSize = 0;
            {   const ull totalBlocksSize = skipLegacyBlocksData(finput);
                if (totalBlocksSize == legacyFrameUndecodable) {
                    DISPLAYLEVEL(1, "Corrupted legacy frame \n");
                    result = LZ4IO_format_not_known;
                    break;
                }
                if (totalBlocksSize) {
                    DISPLAYOUTLEVEL(3, "    %6llu %14s %5s %8s %20llu %20s %9s\n",
                                 cfinfo->frameCount + 1,
                                 frameTypeNames[frameInfo.frameType],
                                 "-", "-",
                                 totalBlocksSize + 4,
                                 "-", "-");
                    result = LZ4IO_LZ4F_OK;
                }
            }
            break;
        case LZ4IO_SKIPPABLE0:
            frameInfo.frameType = skippableFrame;
            if (cfinfo->frameSummary.frameType != skippableFrame && cfinfo->frameCount != 0) cfinfo->eqFrameTypes = 0;
            cfinfo->eqBlockTypes = 0;
            cfinfo->allContentSize = 0;
            {   size_t const nbReadBytes = fread(buffer, 1, 4, finput);
                if (nbReadBytes != 4)
                    END_PROCESS(42, "Stream error : skippable size unreadable");
            }
            {   unsigned const size = readLE32(buffer);
                int const errorNb = fseek_u32(finput, size, SEEK_CUR);
                if (errorNb != 0)
                    END_PROCESS(43, "Stream error : cannot skip skippable area");
                DISPLAYOUTLEVEL(3, "    %6llu %14s %5s %8s %20u %20s %9s\n",
                             cfinfo->frameCount + 1,
                             "SkippableFrame",
                             "-", "-", size + 8, "-", "-");
                result = LZ4IO_LZ4F_OK;
            }
            break;
        default:
            {   long int const position = ftell(finput);
                DISPLAYOUTLEVEL(3, "Stream followed by undecodable data ");
                if (position != -1L)
                    DISPLAYOUTLEVEL(3, "at position %i ", (int)position);
                result = LZ4IO_format_not_known;
                DISPLAYOUTLEVEL(3, "\n");
            }
            break;
        }
        if (result != LZ4IO_LZ4F_OK) break;
        cfinfo->frameSummary = frameInfo;
        cfinfo->frameCount++;
    }
    if (finput != stdin) fclose(finput);
    return result;
}

int LZ4IO_displayCompressedFilesInfo(const char** inFileNames, size_t ifnIdx) {
    int result = 0;
    size_t idx = 0;
    if (g_displayLevel < 3) {
        DISPLAYOUT("%10s %14s %5s %11s %13s %8s   %s\n",
                   "Frames", "Type", "Block", "Compressed", "Uncompressed", "Ratio", "Filename");
    }
    for (; idx < ifnIdx; idx++) {
        cFileInfo_t cfinfo;
        memset(&cfinfo, 0, sizeof(cfinfo));
        cfinfo.frameSummary.frameType = lz4Frame;
        cfinfo.eqFrameTypes = 1;
        cfinfo.eqBlockTypes = 1;
        cfinfo.allContentSize = 1;
        cfinfo.fileName = baseName(inFileNames[idx]);
        if (!strcmp(inFileNames[idx], stdinmark) ? !UTIL_isRegFD(0) : !UTIL_isRegFile(inFileNames[idx])) {
            DISPLAYLEVEL(1, "lz4: %s is not a regular file \n", inFileNames[idx]);
            return 0;
        }
        DISPLAYOUTLEVEL(3, "%s(%llu/%llu)\n", cfinfo.fileName, (ull)idx + 1, (ull)ifnIdx);
        DISPLAYOUTLEVEL(3, "    %6s %14s %5s %8s %20s %20s %9s\n",
                        "Frame", "Type", "Block", "Checksum", "Compressed", "Uncompressed", "Ratio");
        {   infoResult const op_result = getCompressedFileInfo(&cfinfo, inFileNames[idx]);
            if (op_result != LZ4IO_LZ4F_OK) {
                DISPLAYLEVEL(1, "lz4: %s: File format not recognized \n", inFileNames[idx]);
                return 1;
            }
        }
        DISPLAYOUTLEVEL(3, "\n");
        if (g_displayLevel < 3) {
            char buffers[3][10];
            DISPLAYOUT("%10llu %14s %5s %11s %13s ",
                       cfinfo.frameCount,
                       cfinfo.eqFrameTypes ? frameTypeNames[cfinfo.frameSummary.frameType] : "-",
                       cfinfo.eqBlockTypes ? blockTypeID(cfinfo.frameSummary.lz4FrameInfo.blockSizeID,
                                                         cfinfo.frameSummary.lz4FrameInfo.blockMode, buffers[0]) : "-",
                       toHuman((long double)cfinfo.fileSize, buffers[1]),
                       cfinfo.allContentSize ? toHuman((long double)cfinfo.frameSummary.lz4FrameInfo.contentSize, buffers[2]) : "-");
            if (cfinfo.allContentSize) {
                double const ratio = (double)cfinfo.fileSize / (double)cfinfo.frameSummary.lz4FrameInfo.contentSize * 100;
                DISPLAYOUT("%8.2f%%  %s \n", ratio, cfinfo.fileName);
            } else {
                DISPLAYOUT("%8s   %s\n", "-", cfinfo.fileName);
            }
        }
    }
    return result;
}
EOF
echo ok"}

