#define _POSIX_C_SOURCE 200809L
#define _DEFAULT_SOURCE
#include "util.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <dirent.h>
#include <sys/types.h>

uint64_t UTIL_getTimeNs(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
}

int UTIL_isDirectory(const char* infilename) {
    struct stat statbuf;
    int const r = stat(infilename, &statbuf);
    if (!r && S_ISDIR(statbuf.st_mode)) return 1;
    return 0;
}

int UTIL_getFileStat(const char* infilename, struct stat* statbuf) {
    int const r = stat(infilename, statbuf);
    if (r || !S_ISREG(statbuf->st_mode)) return 0;
    return 1;
}

int UTIL_isRegFile(const char* infilename) {
    struct stat statbuf;
    return UTIL_getFileStat(infilename, &statbuf);
}

int UTIL_isRegFD(int fd) {
    struct stat statbuf;
    int const r = fstat(fd, &statbuf);
    if (r || !S_ISREG(statbuf.st_mode)) return 0;
    return 1;
}

int UTIL_setFileStat(const char* filename, struct stat* statbuf) {
    int res = 0;
    struct timespec timebuf[2];
    if (!UTIL_isRegFile(filename)) return -1;
    memset(timebuf, 0, sizeof(timebuf));
    timebuf[0].tv_nsec = UTIME_NOW;
    timebuf[1].tv_sec = statbuf->st_mtime;
    res += utimensat(AT_FDCWD, filename, timebuf, 0);
    res += chown(filename, statbuf->st_uid, statbuf->st_gid);
    res += chmod(filename, statbuf->st_mode & 07777);
    errno = 0;
    return -res;
}

uint64_t UTIL_getOpenFileSize(FILE* file) {
    struct stat statbuf;
    int const fd = fileno(file);
    if (fstat(fd, &statbuf) || !S_ISREG(statbuf.st_mode)) return 0;
    return (uint64_t)statbuf.st_size;
}

uint64_t UTIL_getFileSize(const char* infilename) {
    struct stat statbuf;
    if (stat(infilename, &statbuf) || !S_ISREG(statbuf.st_mode)) return 0;
    return (uint64_t)statbuf.st_size;
}

uint64_t UTIL_getTotalFileSize(const char** fileNamesTable, unsigned nbFiles) {
    uint64_t total = 0;
    unsigned n;
    for (n = 0; n < nbFiles; n++) total += UTIL_getFileSize(fileNamesTable[n]);
    return total;
}

#define LIST_SIZE_INCREASE (8 * 1024)

static int prepareFileList(const char* dirName, char** bufStart, size_t* pos, char** bufEnd) {
    DIR* dir;
    struct dirent* entry;
    size_t dirLength;
    int nbFiles = 0;

    if (!(dir = opendir(dirName))) {
        fprintf(stderr, "Cannot open directory '%s': %s\n", dirName, strerror(errno));
        return 0;
    }
    dirLength = strlen(dirName);
    errno = 0;
    while ((entry = readdir(dir)) != NULL) {
        char* path;
        size_t fnameLength, pathLength;
        if (strcmp(entry->d_name, "..") == 0 || strcmp(entry->d_name, ".") == 0) continue;
        fnameLength = strlen(entry->d_name);
        path = (char*)malloc(dirLength + fnameLength + 2);
        if (!path) { closedir(dir); return 0; }
        memcpy(path, dirName, dirLength);
        path[dirLength] = '/';
        memcpy(path + dirLength + 1, entry->d_name, fnameLength);
        pathLength = dirLength + 1 + fnameLength;
        path[pathLength] = 0;

        if (UTIL_isDirectory(path)) {
            nbFiles += prepareFileList(path, bufStart, pos, bufEnd);
            if (*bufStart == NULL) { free(path); closedir(dir); return 0; }
        } else {
            if (*bufStart + *pos + pathLength >= *bufEnd) {
                ptrdiff_t newListSize = (*bufEnd - *bufStart) + LIST_SIZE_INCREASE;
                char* nb = (char*)realloc(*bufStart, (size_t)newListSize + pathLength);
                if (nb == NULL) { free(*bufStart); *bufStart = NULL; free(path); closedir(dir); return 0; }
                *bufStart = nb;
                *bufEnd = *bufStart + newListSize + pathLength;
            }
            if (*bufStart + *pos + pathLength < *bufEnd) {
                memcpy(*bufStart + *pos, path, pathLength + 1);
                *pos += pathLength + 1;
                nbFiles++;
            }
        }
        free(path);
        errno = 0;
    }
    if (errno != 0) {
        fprintf(stderr, "readdir(%s) error: %s\n", dirName, strerror(errno));
        free(*bufStart);
        *bufStart = NULL;
    }
    closedir(dir);
    return nbFiles;
}

const char** UTIL_createFileList(const char** inputNames, unsigned inputNamesNb, char** allocatedBuffer, unsigned* allocatedNamesNb) {
    size_t pos;
    unsigned i, nbFiles;
    char* buf = (char*)malloc(LIST_SIZE_INCREASE);
    char* bufend = buf + LIST_SIZE_INCREASE;
    const char** fileTable;

    if (!buf) return NULL;
    for (i = 0, pos = 0, nbFiles = 0; i < inputNamesNb; i++) {
        if (!UTIL_isDirectory(inputNames[i])) {
            size_t const len = strlen(inputNames[i]);
            if (buf + pos + len >= bufend) {
                ptrdiff_t newListSize = (bufend - buf) + LIST_SIZE_INCREASE;
                char* nb = (char*)realloc(buf, (size_t)newListSize + len);
                if (!nb) { free(buf); return NULL; }
                buf = nb;
                bufend = buf + newListSize + len;
            }
            if (buf + pos + len < bufend) {
