/* ---- 64-bit hash for content verification ---- */
static U64 fnv64(const void* p, size_t n) {
    const BYTE* b = (const BYTE*)p;
    U64 h = 1469598103934665603ULL;
    size_t i;
    for (i = 0; i < n; i++) { h ^= b[i]; h *= 1099511628211ULL; }
    return h;
}

typedef struct {
    int cLevel;
    const char* dictBuf;
    int dictSize;
    lz4_stream* stream;
    lz4_stream* dictStream;
    lz4hc_ctx* streamHC;
    lz4hc_ctx* dictStreamHC;
} compParams;

static void compInit(compParams* p) {
    p->stream = NULL; p->dictStream = NULL; p->streamHC = NULL; p->dictStreamHC = NULL;
    if (p->dictSize) {
        if (p->cLevel < LZ4HC_CLEVEL_MIN) {
            p->stream = (lz4_stream*)calloc(1, sizeof(lz4_stream));
            p->dictStream = (lz4_stream*)calloc(1, sizeof(lz4_stream));
            lz4_initStream(p->stream);
            lz4_initStream(p->dictStream);
            lz4_loadDict(p->dictStream, p->dictBuf, p->dictSize);
        } else {
            p->streamHC = (lz4hc_ctx*)malloc(sizeof(lz4hc_ctx));
            p->dictStreamHC = (lz4hc_ctx*)malloc(sizeof(lz4hc_ctx));
            lz4hc_initStream(p->streamHC);
            lz4hc_initStream(p->dictStreamHC);
            lz4hc_resetStream_fast(p->dictStreamHC, p->cLevel);
            lz4hc_loadDict(p->dictStreamHC, p->dictBuf, p->dictSize);
        }
    }
}

static int compBlock(compParams* p, const char* src, char* dst, int srcSize, int dstSize) {
    if (p->dictSize) {
        if (p->cLevel < LZ4HC_CLEVEL_MIN) {
            int const acceleration = (p->cLevel < 0) ? -p->cLevel + 1 : 1;
            lz4_resetStream_fast(p->stream);
            lz4_attach_dictionary(p->stream, p->dictStream);
            return lz4_compress_fast_continue(p->stream, src, dst, srcSize, dstSize, acceleration);
        } else {
            lz4hc_resetStream_fast(p->streamHC, p->cLevel);
            lz4hc_attach_dictionary(p->streamHC, p->dictStreamHC);
            return lz4hc_compress_continue(p->streamHC, src, dst, srcSize, dstSize);
        }
    }
    if (p->cLevel < LZ4HC_CLEVEL_MIN) {
        int const acceleration = (p->cLevel < 0) ? -p->cLevel + 1 : 1;
        return lz4_compress_fast(src, dst, srcSize, dstSize, acceleration);
    }
    return lz4hc_compress(src, dst, srcSize, dstSize, p->cLevel);
}

static void compCleanup(compParams* p) {
    free(p->stream); free(p->dictStream); free(p->streamHC); free(p->dictStreamHC);
}

/* decode-only mode : decompress a full LZ4 frame */
static int frameDecode(const char* src, char* dst, int srcSize, int dstCapacity, const char* dict, int dictSize) {
    lz4f_dctx* const dctx = lz4f_createDCtx();
    size_t srcPos = 0, dstPos = 0;
    size_t hint = 1;
    if (!dctx) return -1;
    while (srcPos < (size_t)srcSize) {
        size_t dSize = (size_t)dstCapacity - dstPos;
        size_t sSize = (size_t)srcSize - srcPos;
        hint = lz4f_decompress_usingDict(dctx, dst + dstPos, &dSize, src + srcPos, &sSize, dict, (size_t)dictSize, (int)g_skipChecksums);
        if (lz4f_isError(hint)) { lz4f_freeDCtx(dctx); return -1; }
        srcPos += sSize;
        dstPos += dSize;
        if (sSize == 0 && dSize == 0) break;
    }
    lz4f_freeDCtx(dctx);
    if (hint != 0) return -2;
    return (int)dstPos;
}

typedef struct {
    const char* srcPtr;
    size_t srcSize;
    char* cPtr;
    size_t cRoom;
    size_t cSize;
    char* resPtr;
    size_t resSize;
} blockParam_t;

static int benchMem(const void* srcBuffer, size_t srcSize, const char* displayName, int cLevel,
                    const size_t* fileSizes, U32 nbFiles, const char* dictBuf, int dictSize)
{
    size_t const blockSize = (g_blockSize >= 32 && !g_decodeOnly ? g_blockSize : srcSize) + (!srcSize);
    U32 const maxNbBlocks = (U32)((srcSize + (blockSize - 1)) / blockSize) + nbFiles;
    blockParam_t* const blockTable = (blockParam_t*)malloc(maxNbBlocks * sizeof(blockParam_t));
    size_t const maxCompressedSize = (size_t)lz4_compressBound((int)srcSize) + (maxNbBlocks * 1024);
    void* const compressedBuffer = malloc(maxCompressedSize);
    size_t const decMultiplier = g_decodeOnly ? 255 : 1;
    size_t const maxInSize = (size_t)LZ4_MAX_INPUT_SIZE / decMultiplier;
    size_t const maxDecSize = srcSize < maxInSize ? srcSize * decMultiplier : LZ4_MAX_INPUT_SIZE;
    void* const resultBuffer = malloc(maxDecSize + 1);
    int benchError = 0;
    U32 nbBlocks;
    compParams compP;

    if (!compressedBuffer || !resultBuffer || !blockTable)
        END_PROCESS(31, "allocation error : not enough memory");

    if (strlen(displayName) > 17) displayName += strlen(displayName) - 17;

    compP.cLevel = cLevel;
    compP.dictBuf = dictBuf;
    compP.dictSize = dictSize;
    compInit(&compP);

    {   const char* srcPtr = (const char*)srcBuffer;
        char* cPtr = (char*)compressedBuffer;
        char* resPtr = (char*)resultBuffer;
        U32 fileNb;
        for (nbBlocks = 0, fileNb = 0; fileNb < nbFiles; fileNb++) {
            size_t remaining = fileSizes[fileNb];
            U32 const nbBlocksforThisFile = (U32)((remaining + (blockSize - 1)) / blockSize);
            U32 const blockEnd = nbBlocks + nbBlocksforThisFile;
            for (; nbBlocks < blockEnd; nbBlocks++) {
                size_t const thisBlockSize = MIN(remaining, blockSize);
                size_t const resMaxSize = thisBlockSize * decMultiplier;
                size_t const resCapa = (thisBlockSize < maxInSize) ? resMaxSize : LZ4_MAX_INPUT_SIZE;
                blockTable[nbBlocks].srcPtr = srcPtr;
                blockTable[nbBlocks].cPtr = cPtr;
                blockTable[nbBlocks].resPtr = resPtr;
                blockTable[nbBlocks].srcSize = thisBlockSize;
                blockTable[nbBlocks].cRoom = (size_t)lz4_compressBound((int)thisBlockSize);
                srcPtr += thisBlockSize;
                cPtr += blockTable[nbBlocks].cRoom;
                resPtr += resCapa;
                remaining -= thisBlockSize;
            }
        }
    }

    memset(compressedBuffer, 0, maxCompressedSize);

    if (g_decodeOnly) {
        U32 blockNb;
        for (blockNb = 0; blockNb < nbBlocks; blockNb++) {
            memcpy(blockTable[blockNb].cPtr, blockTable[blockNb].srcPtr, blockTable[blockNb].srcSize);
            blockTable[blockNb].cSize = blockTable[blockNb].srcSize;
        }
    }

    {   U64 fastestC = (U64)(-1LL), fastestD = (U64)(-1LL);
        U64 const crcOrig = fnv64(srcBuffer, srcSize);
        U64 coolTime = UTIL_getTimeNs();
        U64 const maxTime = (g_nbSeconds * TIMELOOP_NANOSEC) + 100;
        U32 nbCompressionLoops = (U32)((5 MB) / (srcSize + 1)) + 1;
        U32 nbDecodeLoops = (U32)((200 MB) / (srcSize + 1)) + 1;
        U64 totalCTime = 0, totalDTime = 0;
        U32 cCompleted = (g_decodeOnly == 1), dCompleted = 0;
#define NB_MARKS 4
        const char* const marks[NB_MARKS] = { " |", " /", " =", "\\" };
        U32 markNb = 0;
        size_t cSize = srcSize;
        size_t totalRSize = srcSize;
        double ratio = 0.;

        DISPLAYLEVEL(2, "\r%79s\r", "");
        while (!cCompleted || !dCompleted) {
            if (UTIL_getTimeNs() - coolTime > ACTIVEPERIOD_NANOSEC) {
                DISPLAYLEVEL(2, "\rcooling down ...    \r");
                sleep(COOLPERIOD_SEC);
                coolTime = UTIL_getTimeNs();
            }

            DISPLAYLEVEL(2, "%2s-%-17.17s :%10u ->\r", marks[markNb], displayName, (U32)totalRSize);
            if (!cCompleted) {
                U64 const clockStart = UTIL_getTimeNs();
                U32 nbLoops;
                for (nbLoops = 0; nbLoops < nbCompressionLoops; nbLoops++) {
                    U32 blockNb;
                    for (blockNb = 0; blockNb < nbBlocks; blockNb++) {
                        int const r = compBlock(&compP, blockTable[blockNb].srcPtr, blockTable[blockNb].cPtr,
                                                (int)blockTable[blockNb].srcSize, (int)blockTable[blockNb].cRoom);
                        if (r <= 0 && blockTable[blockNb].srcSize > 0) END_PROCESS(1, "LZ4 compression failed");
                        blockTable[blockNb].cSize = (size_t)r;
                    }
                }
                {   U64 const duration = UTIL_getTimeNs() - clockStart;
                    if (duration > 0) {
                        if (duration < fastestC * nbCompressionLoops)
                            fastestC = duration / nbCompressionLoops;
                        if (fastestC == 0) fastestC = 1;
                        nbCompressionLoops = (U32)(TIMELOOP_NANOSEC / fastestC) + 1;
                    } else {
                        nbCompressionLoops *= 100;
                    }
                    totalCTime += duration;
                    cCompleted = totalCTime > maxTime;
                }

                cSize = 0;
                {   U32 blockNb; for (blockNb = 0; blockNb < nbBlocks; blockNb++) cSize += blockTable[blockNb].cSize; }
                cSize += !cSize;
                ratio = (double)totalRSize / (double)cSize;
                markNb = (markNb + 1) % NB_MARKS;
                DISPLAYOUTLEVEL(2, "%2s-%-17.17s :%10u ->%10u (%5.3f),%6.1f MB/s\r",
                                marks[markNb], displayName,
                                (U32)totalRSize, (U32)cSize, ratio,
                                ((double)totalRSize / (double)fastestC) * 1000);
            }

            if (!dCompleted) memset(resultBuffer, 0xD6, srcSize);

            if (!dCompleted) {
                U64 const clockStart = UTIL_getTimeNs();
                U32 nbLoops;
                for (nbLoops = 0; nbLoops < nbDecodeLoops; nbLoops++) {
                    U32 blockNb;
                    for (blockNb = 0; blockNb < nbBlocks; blockNb++) {
                        size_t const inMaxSize = (size_t)INT_MAX / decMultiplier;
                        size_t const resCapa = (blockTable[blockNb].srcSize < inMaxSize) ?
                                                blockTable[blockNb].srcSize * decMultiplier : INT_MAX;
                        int regenSize;
                        if (g_decodeOnly)
                            regenSize = frameDecode(blockTable[blockNb].cPtr, blockTable[blockNb].resPtr,
                                                    (int)blockTable[blockNb].cSize, (int)resCapa, dictBuf, dictSize);
                        else
                            regenSize = lz4_decompress_safe_usingDict(blockTable[blockNb].cPtr, blockTable[blockNb].resPtr,
                                                    (int)blockTable[blockNb].cSize, (int)resCapa, dictBuf, dictSize);
                        if (regenSize < 0) {
                            DISPLAY("%s() failed on block %u of size %u : %s \n",
                                    g_decodeOnly ? "LZ4F_decompress" : "LZ4_decompress_safe_usingDict",
                                    blockNb, (unsigned)blockTable[blockNb].srcSize,
                                    g_decodeOnly ? "ERROR_frameType_unknown" : "error");
                            if (g_decodeOnly) DISPLAY("Is input using LZ4 Frame format ? \n");
                            benchError = 1;
                            break;
                        }
                        blockTable[blockNb].resSize = (size_t)regenSize;
                    }
                    if (benchError) break;
                }
                {   U64 const duration = UTIL_getTimeNs() - clockStart;
                    if (duration > 0) {
                        if (duration < fastestD * nbDecodeLoops)
                            fastestD = duration / nbDecodeLoops;
                        if (fastestD == 0) fastestD = 1;
                        nbDecodeLoops = (U32)(TIMELOOP_NANOSEC / fastestD) + 1;
                    } else {
                        nbDecodeLoops *= 100;
                    }
                    totalDTime += duration;
                    dCompleted = totalDTime > (DECOMP_MULT * maxTime);
                }
            }
            if (benchError) break;

            if (g_decodeOnly) {
                unsigned u;
                totalRSize = 0;
                for (u = 0; u < nbBlocks; u++) totalRSize += blockTable[u].resSize;
            }
            markNb = (markNb + 1) % NB_MARKS;
            ratio = (double)totalRSize / (double)cSize;
            DISPLAYOUTLEVEL(2, "%2s-%-17.17s :%10u ->%10u (%5.3f),%6.1f MB/s, %6.1f MB/s\r",
                            marks[markNb], displayName,
                            (U32)totalRSize, (U32)cSize, ratio,
                            ((double)totalRSize / (double)fastestC) * 1000,
                            ((double)totalRSize / (double)fastestD) * 1000);

            if (!g_decodeOnly) {
                U64 const crcCheck = fnv64(resultBuffer, srcSize);
                if (crcOrig != crcCheck) {
                    size_t u;
                    DISPLAY("\n!!! WARNING !!! %17s : Invalid Checksum : %x != %x   \n",
                            displayName, (unsigned)crcOrig, (unsigned)crcCheck);
                    benchError = 1;
                    for (u = 0; u < srcSize; u++) {
                        if (((const BYTE*)srcBuffer)[u] != ((BYTE*)resultBuffer)[u]) {
                            U32 segNb, bNb, pos;
                            size_t bacc = 0;
                            DISPLAY("Decoding error at pos %u ", (U32)u);
                            for (segNb = 0; segNb < nbBlocks; segNb++) {
                                if (bacc + blockTable[segNb].srcSize > u) break;
                                bacc += blockTable[segNb].srcSize;
                            }
                            pos = (U32)(u - bacc);
                            bNb = pos / (128 KB);
                            DISPLAY("(block %u, sub %u, pos %u) \n", segNb, bNb, pos);
                            break;
                        }
                        if (u == srcSize - 1) DISPLAY("no difference detected\n");
                    }
                    break;
                }
            }
        }

        if (g_displayLevel == 1) {
            double const cSpeed = ((double)srcSize / (double)fastestC) * 1000;
            double const dSpeed = ((double)srcSize / (double)fastestD) * 1000;
            if (g_additionalParam)
                DISPLAYOUT("-%-3i%11i (%5.3f) %6.2f MB/s %6.1f MB/s  %s (param=%d)\n", cLevel, (int)cSize, ratio, cSpeed, dSpeed, displayName, g_additionalParam);
            else
                DISPLAYOUT("-%-3i%11i (%5.3f) %6.2f MB/s %6.1f MB/s  %s \n", cLevel, (int)cSize, ratio, cSpeed, dSpeed, displayName);
        }
        DISPLAYOUTLEVEL(2, "%2i#\n", cLevel);
    }

    compCleanup(&compP);
    free(blockTable);
    free(compressedBuffer);
    free(resultBuffer);
    return benchError;
}

static size_t findMaxMem(U64 requiredMem) {
    size_t const step = 64 MB;
    void* testmem = NULL;
    size_t const maxMemory = (size_t)(1ULL << ((sizeof(size_t) * 8) - 31));
    requiredMem = (((requiredMem >> 26) + 1) << 26);
    requiredMem += 2 * step;
    if (requiredMem > maxMemory) requiredMem = maxMemory;
    while (!testmem) {
        if (requiredMem > step) requiredMem -= step;
        else requiredMem >>= 1;
        testmem = malloc((size_t)requiredMem);
    }
    free(testmem);
    if (requiredMem > step) requiredMem -= step;
    else requiredMem >>= 1;
    return (size_t)requiredMem;
}

static int benchCLevel(void* srcBuffer, size_t benchedSize, const char* displayName, int cLevel, int cLevelLast,
                       const size_t* fileSizes, unsigned nbFiles, const char* dictBuf, int dictSize)
{
    int l;
    int benchError = 0;
    const char* pch = strrchr(displayName, '\\');
    if (!pch) pch = strrchr(displayName, '/');
    if (pch) displayName = pch + 1;

    if (g_displayLevel == 1 && !g_additionalParam)
        DISPLAY("bench %s %s: input %u bytes, %u seconds, %u KB blocks\n",
                "1.10.0", "", (U32)benchedSize, g_nbSeconds, (U32)(g_blockSize >> 10));

    if (cLevelLast < cLevel) cLevelLast = cLevel;
    for (l = cLevel; l <= cLevelLast; l++) {
        benchError |= benchMem(srcBuffer, benchedSize, displayName, l, fileSizes, nbFiles, dictBuf, dictSize);
    }
    return benchError;
}

static void loadFiles(void* buffer, size_t bufferSize, size_t* fileSizes, const char** fileNamesTable, unsigned nbFiles) {
    size_t pos = 0, totalSize = 0;
    unsigned n;
    for (n = 0; n < nbFiles; n++) {
        FILE* f;
        U64 fileSize = UTIL_getFileSize(fileNamesTable[n]);
        if (UTIL_isDirectory(fileNamesTable[n])) {
            DISPLAYLEVEL(2, "Ignoring %s directory...       \n", fileNamesTable[n]);
            fileSizes[n] = 0;
            continue;
        }
        f = fopen(fileNamesTable[n], "rb");
        if (f == NULL) END_PROCESS(10, "impossible to open file %s", fileNamesTable[n]);
        DISPLAYUPDATE(2, "Loading %s...       \r", fileNamesTable[n]);
        if (fileSize > bufferSize - pos) {
            fileSize = bufferSize - pos;
            nbFiles = n;
        }
        {   size_t const readSize = fread(((char*)buffer) + pos, 1, (size_t)fileSize, f);
            if (readSize != (size_t)fileSize) END_PROCESS(11, "could not read %s", fileNamesTable[n]);
            pos += readSize;
        }
        fileSizes[n] = (size_t)fileSize;
        totalSize += (size_t)fileSize;
        fclose(f);
    }
    if (totalSize == 0) END_PROCESS(12, "no data to bench");
}

static int benchFileTable(const char** fileNamesTable, unsigned nbFiles, int cLevel, int cLevelLast,
                          const char* dictBuf, int dictSize)
{
    void* srcBuffer;
    size_t benchedSize;
    int benchError = 0;
    size_t* fileSizes = (size_t*)calloc(nbFiles ? nbFiles : 1, sizeof(size_t));
    U64 const totalSizeToLoad = UTIL_getTotalFileSize(fileNamesTable, nbFiles);
    char mfName[20] = { 0 };

    if (!fileSizes) END_PROCESS(12, "not enough memory for fileSizes");
    benchedSize = findMaxMem(totalSizeToLoad * 3) / 3;
    if (benchedSize == 0) END_PROCESS(12, "not enough memory");
    if ((U64)benchedSize > totalSizeToLoad) benchedSize = (size_t)totalSizeToLoad;
    if (benchedSize > LZ4_MAX_INPUT_SIZE) {
        benchedSize = LZ4_MAX_INPUT_SIZE;
        DISPLAY("File(s) bigger than LZ4's max input size; testing %u MB only...\n", (U32)(benchedSize >> 20));
    } else {
        if (benchedSize < totalSizeToLoad)
            DISPLAY("Not enough memory; testing %u MB only...\n", (U32)(benchedSize >> 20));
    }
    srcBuffer = malloc(benchedSize + !benchedSize);
    if (!srcBuffer) END_PROCESS(12, "not enough memory");

    loadFiles(srcBuffer, benchedSize, fileSizes, fileNamesTable, nbFiles);

    snprintf(mfName, sizeof(mfName), " %u files", nbFiles);
    {   const char* const displayName = (nbFiles > 1) ? mfName : fileNamesTable[0];
        benchError = benchCLevel(srcBuffer, benchedSize, displayName, cLevel, cLevelLast,
                                 fileSizes, nbFiles, dictBuf, dictSize);
    }
    free(srcBuffer);
    free(fileSizes);
    return benchError;
}

/* simple deterministic data generator for synthetic test */
static void genBuffer(void* buffer, size_t size, double matchProba) {
    BYTE* const op = (BYTE*)buffer;
    U32 seed = 0;
    size_t pos = 0;
#define RAND() (seed = seed * 1103515245U + 12345U, (seed >> 16) & 0x7FFF)
    while (pos < size) {
        if (pos > 16 && (RAND() % 1000) < (U32)(matchProba * 1000)) {
            size_t const off = 1 + RAND() % (pos < 32768 ? pos : 32768);
            size_t len = 4 + RAND() % 16;
            size_t k;
            for (k = 0; k < len && pos < size; k++, pos++) op[pos] = op[pos - off];
        } else {
            op[pos++] = (BYTE)('0' + RAND() % 64);
        }
    }
}

static int syntheticTest(int cLevel, int cLevelLast, double compressibility, const char* dictBuf, int dictSize) {
    int benchError = 0;
    char name[20] = { 0 };
    size_t benchedSize = 10000000;
    void* const srcBuffer = malloc(benchedSize);
    if (!srcBuffer) END_PROCESS(21, "not enough memory");
    genBuffer(srcBuffer, benchedSize, compressibility);
    snprintf(name, sizeof(name), "Synthetic %2u%%", (unsigned)(compressibility * 100));
    benchError = benchCLevel(srcBuffer, benchedSize, name, cLevel, cLevelLast, &benchedSize, 1, dictBuf, dictSize);
    free(srcBuffer);
    return benchError;
}

static int benchFilesSeparately(const char** fileNamesTable, unsigned nbFiles, int cLevel, int cLevelLast,
                                const char* dictBuf, int dictSize)
{
    int benchError = 0;
    unsigned fileNb;
    if (cLevel > LZ4HC_CLEVEL_MAX) cLevel = LZ4HC_CLEVEL_MAX;
    if (cLevelLast > LZ4HC_CLEVEL_MAX) cLevelLast = LZ4HC_CLEVEL_MAX;
    if (cLevelLast < cLevel) cLevelLast = cLevel;
    for (fileNb = 0; fileNb < nbFiles; fileNb++)
        benchError |= benchFileTable(fileNamesTable + fileNb, 1, cLevel, cLevelLast, dictBuf, dictSize);
    return benchError;
}

int BMK_benchFiles(const char** fileNamesTable, unsigned nbFiles, int cLevel, int cLevelLast, const char* dictFileName) {
    int benchError = 0;
    double const compressibility = 0.5;
    char* dictBuf = NULL;
    size_t dictSize = 0;

    if (cLevel > LZ4HC_CLEVEL_MAX) cLevel = LZ4HC_CLEVEL_MAX;
    if (g_decodeOnly) {
        DISPLAYLEVEL(2, "Benchmark Decompression of LZ4 Frame ");
        if (g_skipChecksums) {
            DISPLAYLEVEL(2, "_without_ checksum even when present \n");
        } else {
            DISPLAYLEVEL(2, "+ Checksum when present \n");
        }
        cLevelLast = cLevel;
    }
    if (cLevelLast > LZ4HC_CLEVEL_MAX) cLevelLast = LZ4HC_CLEVEL_MAX;
    if (cLevelLast < cLevel) cLevelLast = cLevel;
    if (cLevelLast > cLevel)
        DISPLAYLEVEL(2, "Benchmarking levels from %d to %d\n", cLevel, cLevelLast);

    if (dictFileName) {
        FILE* dictFile = NULL;
        U64 const dictFileSize = UTIL_getFileSize(dictFileName);
        if (!dictFileSize) END_PROCESS(25, "Dictionary error : could not stat dictionary file");
        dictFile = fopen(dictFileName, "rb");
        if (!dictFile) END_PROCESS(25, "Dictionary error : could not open dictionary file");
        if (dictFileSize > LZ4_MAX_DICT_SIZE) {
            dictSize = LZ4_MAX_DICT_SIZE;
            if (fseeko(dictFile, (off_t)(dictFileSize - dictSize), SEEK_SET))
                END_PROCESS(25, "Dictionary error : could not seek dictionary file");
        } else {
            dictSize = (size_t)dictFileSize;
        }
        dictBuf = (char*)malloc(dictSize);
        if (!dictBuf) END_PROCESS(25, "Allocation error : not enough memory");
        if (fread(dictBuf, 1, dictSize, dictFile) != dictSize)
            END_PROCESS(25, "Dictionary error : could not read dictionary file");
        fclose(dictFile);
    }

    if (nbFiles == 0)
        benchError = syntheticTest(cLevel, cLevelLast, compressibility, dictBuf, (int)dictSize);
    else {
        if (g_benchSeparately)
            benchError = benchFilesSeparately(fileNamesTable, nbFiles, cLevel, cLevelLast, dictBuf, (int)dictSize);
        else
            benchError = benchFileTable(fileNamesTable, nbFiles, cLevel, cLevelLast, dictBuf, (int)dictSize);
    }
    free(dictBuf);
    return benchError;
}
