words = open('/tmp/t/text','rb').read()
def gen(size):
    kind = random.choice(['text','rand','zeros','mixed','repeat','binary','sparse'])
    if kind == 'text':
        s = random.randint(0, len(words)-1); out = (words[s:] + words)[:size]
    elif kind == 'rand':
        out = os.urandom(size)
    elif kind == 'zeros':
        out = bytes(size)
    elif kind == 'repeat':
        pat = os.urandom(random.randint(1, 20)); out = (pat * (size // len(pat) + 1))[:size]
    elif kind == 'binary':
        out = bytes(random.choice([0,1,2,3,255,128]) for _ in range(min(size, 200000)))
        out = (out * (size // max(1,len(out)) + 1))[:size]
    elif kind == 'sparse':
        b = bytearray(size)
        for _ in range(size // 100 + 1):
            p = random.randint(0, max(0,size-1));
            if size: b[p] = random.randint(0,255)
        out = bytes(b)
    else:
        out = bytearray()
        while len(out) < size:
            r = random.random()
            if r < 0.3: out += os.urandom(random.randint(1, 3000))
            elif r < 0.6: s = random.randint(0, len(words)-1); out += words[s:s+random.randint(1, 20000)]
            elif r < 0.8 and len(out) > 10:
                off = random.randint(1, min(len(out), 70000)); l = random.randint(4, 300)
                for i in range(l): out.append(out[-off])
            else: out += bytes(random.randint(1, 500))
        out = bytes(out[:size])
    return kind, out
