    if random.random() < 0.2: opts.append('-BX')
    if random.random() < 0.2: opts.append('--content-size')
    if random.random() < 0.1: opts.append('--no-frame-crc')
    if random.random() < 0.15: opts.append('--favor-decSpeed')
    if random.random() < 0.15: opts += ['-D', '/tmp/cmp/fixture/dict.bin']
    if random.random() < 0.05: opts = [o for o in opts if o not in ('-BD','-BX','--content-size','--no-frame-crc')] + ['-l']
    cmd = opts + ['-c', '-q', '/tmp/cmp/fz_in']
    r = subprocess.run(['/workspace/executable'] + cmd, capture_output=True)
    n = subprocess.run(['/tmp/my/executable'] + cmd, capture_output=True)
    ok = r.returncode == n.returncode and r.stdout == n.stdout and r.stderr == n.stderr
    # also roundtrip decode with my decoder
    if ok and r.returncode == 0:
        dopts = ['-D', '/tmp/cmp/fixture/dict.bin'] if '-D' in opts else []
        open('/tmp/cmp/fz_c','wb').write(r.stdout)
        d = subprocess.run(['/tmp/my/executable', '-dc', '-q'] + dopts + ['/tmp/cmp/fz_c'], capture_output=True)
        if d.stdout != data or d.returncode != 0:
            ok = False; print("  roundtrip failed", d.returncode, d.stderr[:200])
    if not ok:
